-- 3. Upsert Questions
INSERT INTO public.questions (
  id, cert_id, question_number, text, options,
  correct_answers, explanation, category, tags, image_url, status
) VALUES
  ('ccdv-1', 'ccdv-f', 1, 'Your Claude application''s content policy defines categories of content that it must never produce under any circumstances. The application currently has no way to enforce this policy, and content in these categories is appearing in its output. How would you enforce the content policy?', '[{"key":"A","text":"Enhance the system prompt to contain explicit instructions for the categories to avoid, complete with examples of each category. Treat the strengthened prompt as the primary enforcement mechanism for the application’s content policy across all responses."},{"key":"B","text":"Remove the content policy entirely and let any output reach users during normal operation, accepting whatever content the application produces in response to incoming traffic."},{"key":"C","text":"Add deterministic output filtering that checks responses against the content policy before they reach users."},{"key":"D","text":"Move enforcement to users by asking them to report content policy violations after the violating content has already reached them in the application’s responses."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng lọc đầu ra xác định sẽ đánh giá từng phản hồi được tạo theo danh mục bị cấm đã xác định trước khi được gửi tới người dùng, cho phép chặn nội dung phù hợp một cách nhất quán. Các hướng dẫn do hệ thống nhắc nhở có thể điều khiển hành vi của mô hình nhưng không phải là biện pháp kiểm soát thực thi được đảm bảo.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-2', 'ccdv-f', 2, 'Your Claude application’s API keys are kept in a secrets manager. The team is considering whether to use the same key in development, staging, and production. How should the keys be handled across environments?', '[{"key":"A","text":"Use a single development key everywhere on the grounds that production keys are too risky to deploy across the application''s three environments during normal operation."},{"key":"B","text":"Use distinct keys for each environment so a compromise in one environment does not affect the others during normal operation across the application’s lifecycle."},{"key":"C","text":"Rotate the same key across environments at random intervals on the grounds that random rotation provides isolation between environments without requiring distinct keys."},{"key":"D","text":"Use the same key across all environments for simplicity and treat the propagation of any compromise as a known operational tradeoff for the team''s key management approach."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mỗi môi trường nên sử dụng khóa API riêng. Thông tin xác thực dành riêng cho môi trường tách biệt sự thỏa hiệp, thu hồi, kiểm tra, quyền và luân chuyển, do đó, việc tiếp xúc trong quá trình phát triển hoặc dàn dựng sẽ không cấp quyền truy cập vào sản xuất. Tài liệu Anthropic cũng khuyên bạn nên tạo khóa API chuyên dụng để sử dụng API trực tiếp và lưu trữ an toàn.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-3', 'ccdv-f', 3, 'The team is considering whether to implement a new capability as a custom tool or use an existing built-in tool that almost meets the use case but is missing one specific feature. How should you make the decision?', '[{"key":"A","text":"Review the built-in tool’s documentation and assess whether its existing capabilities are sufficient to cover the use case without any modification or extension."},{"key":"B","text":"Identify whether the team has previously built similar custom tools and use those precedents to determine which approach is more consistent with the existing codebase."},{"key":"C","text":"Examine the custom tool option by scoping the implementation effort and determining whether the additional flexibility justifies the development and maintenance cost."},{"key":"D","text":"Evaluate whether the missing feature can be addressed by extending the built-in tool or warrants a custom tool, then choose accordingly."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chọn phương pháp dựa trên việc liệu công cụ tích hợp sẵn có thể được mở rộng để hỗ trợ tính năng còn thiếu hay không và liệu phương pháp đó có phù hợp hơn với tính linh hoạt, nỗ lực triển khai và bảo trì liên tục của công cụ tùy chỉnh hay không. Điều này đánh giá sự cân bằng về mặt kỹ thuật và vòng đời có liên quan của cả hai lựa chọn.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-4', 'ccdv-f', 4, 'A teammate has asked for an explanation of when a Skill is the better choice than an MCP server. The teammate is unsure how the two differ in practice when both can be reused across teams. How would you describe the distinction?', '[{"key":"A","text":"A Skill is preferable for cross-team reuse because it loads more efficiently than an MCP server during normal operation in the team’s typical multi-team workloads."},{"key":"B","text":"A Skill bundles prompts, scripts, and data into a package the model loads as a unit while a MCP server exposes resources, tools, and prompts through a standard client interface."},{"key":"C","text":"A Skill and an MCP server are equivalent extension mechanisms that the team can use interchangeably for any reusable capability that needs to be accessible across teams."},{"key":"D","text":"A Skill is the older mechanism and an MCP server is the newer one, so the team should prefer an MCP server for any reusable capability that the team builds going forward."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hướng dẫn gói Kỹ năng và tài nguyên quy trình làm việc tùy chọn, bao gồm tập lệnh, mẫu và tài liệu tham khảo để hướng dẫn công việc lặp lại. Máy chủ MCP hiển thị thông tin trực tiếp và các hành động được kiểm soát thông qua giao diện máy khách-máy chủ tiêu chuẩn, bao gồm các công cụ, tài nguyên và lời nhắc. Các kỹ năng có thể bổ sung cho máy chủ MCP bằng cách xác định cách sử dụng các khả năng của chúng cho quy trình làm việc.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-5', 'ccdv-f', 5, 'You are creating a system prompt for a Claude application that must generate output in a particular JSON shape. The downstream system will reject any output that fails to conform to the schema. Your prompt would need to ...', '[{"key":"A","text":"omit any reference to the format and rely on a post-processing step in the application to reshape Claude’s output."},{"key":"B","text":"instruct Claude to return JSON sometimes and free text other times so the application''s output captures both formats."},{"key":"C","text":"include explicit constraints describing the required JSON schema and an instruction to produce only output matching that schema."},{"key":"D","text":"instruct Claude to use whichever output format it considers most appropriate for each request the application handles."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi hệ thống hạ nguồn yêu cầu một lược đồ JSON cụ thể, mô hình phải nhận được hướng dẫn rõ ràng xác định lược đồ đó và chỉ yêu cầu đầu ra ở định dạng đó. Các ràng buộc định dạng đầu ra cụ thể, rõ ràng sẽ cải thiện sự tuân thủ và ngăn chặn văn bản tự do bổ sung hoặc các cấu trúc không tương thích.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-6', 'ccdv-f', 6, 'Your Claude application generates good responses for typical inputs but has difficulty with edge cases. You have several labeled examples of edge-case inputs and the desired response for each. You want to use these examples to improve the model’s treatment of edge cases. What is the best way to use these examples?', '[{"key":"A","text":"Embed the examples in a database for the model to find during inference."},{"key":"B","text":"Train a custom model on the edge-case examples and deploy that custom model in place of the team’s current Claude integration."},{"key":"C","text":"Add the labeled edge-case examples to the prompt as few-shot examples so the model can learn the pattern."},{"key":"D","text":"Tell users to avoid submitting the edge-case inputs to the application by adding warnings in the application’s user interface."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lời nhắc Few-shot đặt các ví dụ đầu vào-đầu ra được gắn nhãn đại diện trong lời nhắc để Claude có thể suy luận và áp dụng mẫu xử lý mong muốn. Anthropic đề xuất các ví dụ đa dạng, phù hợp bao gồm các trường hợp khó khăn vì chúng cải thiện độ chính xác và tính nhất quán của đầu ra.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-7', 'ccdv-f', 7, 'Your Claude application validates structured output, but it has been treating validation failures as terminal errors. Every validation failure makes the entire user request fail. The team wants to handle validation failures more gracefully. How would you handle the validation failures?', '[{"key":"A","text":"Tell users that validation failures are unavoidable and instruct them to perform manual accuracy checks before relying on outputs."},{"key":"B","text":"Disable output validation until the underlying cause of validation failures has been identified and addressed in a future release."},{"key":"C","text":"Treat validation failures as a recognized error path that triggers retry, repair, or fallback logic before failing the user request."},{"key":"D","text":"Pass validation failures directly to downstream systems and let each downstream system decide how to handle the malformed output."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lỗi xác thực phải được xử lý dưới dạng đường dẫn lỗi được nhận dạng với khả năng khôi phục giới hạn: thử tạo lại, sửa chữa dữ liệu có cấu trúc không hợp lệ khi an toàn hoặc sử dụng phương án dự phòng hợp lệ trước khi không thực hiện được yêu cầu mà người dùng hướng tới. Việc duy trì xác thực tại chỗ sẽ ngăn chặn đầu ra không đúng định dạng tiếp cận các hệ thống hạ nguồn đồng thời tránh các lỗi thiết bị đầu cuối không cần thiết.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-8', 'ccdv-f', 8, 'You are designing an agent to manage a complex claim-processing workflow. Each claim proceeds through fact extraction, eligibility evaluation, and a decision step. The three subtasks have separate success criteria, and some claims need iteration between fact extraction and eligibility evaluation before a decision can be made.  
  
Which agent pattern would you use?', '[{"key":"A","text":"A single tool-use loop pattern that gives one agent access to all the tools needed for fact extraction, eligibility evaluation, and decision-making."},{"key":"B","text":"A graph-based pattern that lets the agent move between subtasks based on the state of each claim, with each subtask evaluated against its own criteria."},{"key":"C","text":"A linear chain pattern that processes every claim through fact extraction, then eligibility evaluation, then decision, with no return paths between subtasks."},{"key":"D","text":"A streaming pattern that emits partial decisions as the agent processes each claim, refining the output until a final decision emerges from the stream."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mẫu dựa trên biểu đồ mô hình hóa từng nhiệm vụ phụ dưới dạng một nút trạng thái với các chuyển tiếp có điều kiện, cho phép các yêu cầu chuyển từ đánh giá tính đủ điều kiện sang trích xuất dữ kiện khi cần thêm hoặc chỉnh sửa dữ kiện. Nó cũng hỗ trợ đánh giá từng nhiệm vụ phụ chuyên biệt dựa trên các tiêu chí thành công của chính nó. Tính linh hoạt này là cần thiết cho các quy trình phân nhánh và lặp lại, không giống như chuỗi tuần tự cố định.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-9', 'ccdv-f', 9, 'The Anthropic API has deprecated a request parameter that your Claude application uses in approximately 40 locations across the codebase. The deprecation notice provides a six-month window before the parameter is removed and recommends a replacement parameter with slightly different semantics. You would address the deprecation by ...', '[{"key":"A","text":"swapping all 40 call sites in a single change right away to prevent drawn-out migration work that will delay ongoing functioning."},{"key":"B","text":"migrating all 40 call sites in a single change near the removal date to ensure the deprecated parameter continues to work as long as possible."},{"key":"C","text":"adding regression tests to cover the parameter’s behavior, then migrating call sites in batches that you validate against regression tests."},{"key":"D","text":"keeping the deprecated parameter in place while writing a wrapper function around it to insulate the rest of the codebase from the eventual change."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi một tham số API không còn được dùng nữa được thay thế bằng ngữ nghĩa khác, các thử nghiệm hồi quy sẽ giữ nguyên hành vi dự định làm đường cơ sở di chuyển. Việc cập nhật các trang web cuộc gọi theo lô đã xác thực sẽ giới hạn phạm vi của từng thay đổi, sớm phát hiện những khác biệt về hành vi và cho phép quá trình di chuyển kết thúc một cách an toàn trước khi xóa. Anthropic khuyến nghị nên kiểm tra kỹ lưỡng các ứng dụng có giải pháp thay thế trước ngày ngừng hoạt động và cập nhật mã kịp thời.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-10', 'ccdv-f', 10, 'A Claude application uses structured output that downstream code consumes. The team wants to gracefully handle malformed or unexpected output so that it does not crash downstream systems. The best option for addressing this issue is to ...', '[{"key":"A","text":"use the output the model produces and leave schema enforcement to a later phase of production after the application is more complete."},{"key":"B","text":"apply defensive parsing to handle unexpected fields, missing values, and type mismatches that the downstream code might otherwise crash on."},{"key":"C","text":"crash on any unexpected output and require manual recovery on affected requests the application handles during normal operation."},{"key":"D","text":"silently drop any output that does not match expectations so downstream systems do not see the malformed output the application receives from the model."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng phân tích cú pháp phòng thủ xác thực và xử lý một cách an toàn các trường không mong muốn, giá trị bị thiếu và loại không khớp ở ranh giới nơi đầu ra của mô hình nhập mã ứng dụng, ngăn chặn lỗi phân tích cú pháp hoặc lỗi thời gian chạy không được xử lý. Anthropic lưu ý rằng nếu không có kết quả đầu ra có cấu trúc, JSON không đúng định dạng, thiếu trường bắt buộc, loại không nhất quán và vi phạm lược đồ có thể xảy ra; xử lý xuôi dòng mạnh mẽ giải quyết các trường hợp lỗi này.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-11', 'ccdv-f', 11, 'A teammate asks why your Claude agent’s tool definitions contain detailed descriptions even though the tool names are already descriptive. They propose removing those descriptions to make the tool definitions simpler. How would you reply?', '[{"key":"A","text":"Agree with the teammate because tool names are sufficient for the model to choose the right tool on every request the agent handles."},{"key":"B","text":"Explain that the model uses the tool description to decide when to call the tool, and descriptions disambiguate cases where the tool name is not enough."},{"key":"C","text":"Suggest moving the descriptions out of the tool definition and into a separate documentation file the team maintains so the tool definitions stay short and the descriptions remain available."},{"key":"D","text":"Suggest replacing the descriptions with example calls embedded in the tool definition, treating example calls as a complete substitute for the prose description."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude sử dụng mô tả của công cụ để hiểu công cụ đó làm gì, khi nào nên và không nên gọi nó cũng như các tham số của nó ảnh hưởng đến hành vi như thế nào. Mô tả chi tiết cung cấp ngữ cảnh mà tên công cụ không thể diễn đạt một cách đáng tin cậy, giúp Claude phân biệt giữa các công cụ và chọn công cụ thích hợp. Anthropic xác định mô tả công cụ chi tiết là yếu tố chính ảnh hưởng đến hiệu suất sử dụng công cụ.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-12', 'ccdv-f', 12, 'You are designing a Claude application that requires structured JSON output for downstream processing. The output schema is clearly defined, and downstream systems will reject malformed JSON. Your application design would ...', '[{"key":"A","text":"avoid structured output and use free-form text everywhere instead, on the grounds that free-form text is more flexible and handles edge cases better than structured schemas."},{"key":"B","text":"structure the prompt to request output in a schema that is described in plain English, with downstream systems parsing whatever shape Claude produces."},{"key":"C","text":"define a clear schema and structure the prompt to request output in that schema, with downstream systems handling any validation needed."},{"key":"D","text":"define a clear schema, structure the prompt to request output in that schema, and validate Claude’s output against the schema before passing it downstream."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lược đồ được xác định cung cấp cho mô hình một định dạng mục tiêu rõ ràng, đồng thời việc xác thực JSON được trả về dựa trên lược đồ đó sẽ ngăn JSON không đúng định dạng, thiếu trường bắt buộc, loại dữ liệu không chính xác và các vi phạm lược đồ khác tiếp cận các hệ thống từ chối dữ liệu đầu vào không hợp lệ. Hướng dẫn đầu ra có cấu trúc của Anthropic cũng xác định JSON tuân thủ lược đồ là cơ chế thích hợp để xử lý xuôi dòng đáng tin cậy.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-13', 'ccdv-f', 13, 'Your Claude application processes 50-page legal contracts and generates summaries with citation references to the source. The team is considering whether to send each contract as a whole or divide it into smaller pieces. The contracts fit within Claude’s context window.  
  
Initial testing indicates that whole-document processing produces summaries with better cross-section reasoning, but citation accuracy occasionally drifts in later sections. Chunked processing yields stronger citation accuracy for each chunk but loses cross-section reasoning. The team has not yet decided which property is more important. How would you guide the team’s decision?', '[{"key":"A","text":"Assess the cost and latency implications of both approaches against the application’s performance requirements before recommending which processing strategy to adopt."},{"key":"B","text":"Examine the use cases where cross-section reasoning failures occur and assess whether whole-document processing meets the application’s accuracy requirements across a representative sample of contracts."},{"key":"C","text":"Review the citation accuracy results from chunked processing and determine whether the loss of cross-section reasoning produces summaries that still meet the application’s quality bar."},{"key":"D","text":"Identify which property matters more for the application’s actual use case and let that decision drive the chunking approach, then validate the choice against representative contracts."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phương pháp xử lý phải được thúc đẩy bởi đặc tính chất lượng quan trọng nhất đối với trường hợp sử dụng thực tế của ứng dụng: việc xử lý toàn bộ tài liệu thiên về lý luận giữa các phần hợp đồng, trong khi việc phân nhóm thiên về độ chính xác của trích dẫn trong mỗi phần. Sau đó, phương pháp đã chọn sẽ được thử nghiệm với các hợp đồng đại diện để xác nhận rằng nó đáp ứng tiêu chuẩn chất lượng cần thiết.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-14', 'ccdv-f', 14, 'A teammate has asked you to explain why the team’s Claude application is charged a different rate for output tokens than for input tokens. They had assumed that the two rates were identical.  
  
How would you explain the difference?', '[{"key":"A","text":"Output tokens are typically billed at a higher rate than input tokens, and cost models for the application should reflect both rates separately."},{"key":"B","text":"Output tokens are typically billed at the same rate as input tokens, and the apparent rate difference is a billing error to report to Anthropic."},{"key":"C","text":"Output tokens are typically billed at a lower rate than input tokens, because output tokens are cheaper to produce than input tokens are to process."},{"key":"D","text":"Output tokens are not billed at all, because cost is determined entirely by the input tokens sent to the model on each request."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Anthropic định giá mã thông báo đầu vào và đầu ra dưới dạng danh mục sử dụng riêng biệt và bảng giá mô hình của nó thường tính phí trên mỗi mã thông báo đầu ra cao hơn trên mỗi mã thông báo đầu vào cơ sở. Do đó, các mô hình chi phí phải tính toán phí mã thông báo đầu vào và mã thông báo đầu ra một cách độc lập bằng cách sử dụng tỷ lệ tương ứng của chúng.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-15', 'ccdv-f', 15, 'You are designing a multi-step Claude workflow in which certain steps must reason without viewing the complete preceding conversation history. The team wants to keep particular context isolated to particular steps. The context-engineering technique to use is ...', '[{"key":"A","text":"context isolation through subagents or multi-step agentic workflows that scope each step’s context to only what the step needs."},{"key":"B","text":"using a single global prompt that applies to every step in the workflow no matter what each step is reasoning about during its run."},{"key":"C","text":"embedding the full prior history in each step regardless of whether the step needs the prior history for its reasoning."},{"key":"D","text":"augmenting the context with all available content at every step so each step has access to the entire prior history of the workflow during its reasoning."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng tách biệt ngữ cảnh sẽ chỉ đưa từng bước của tác nhân phụ hoặc quy trình làm việc vào phạm vi thông tin cần thiết cho nhiệm vụ của nó, ngăn lịch sử cuộc trò chuyện không liên quan trước đó bị lộ cho bước đó. Anthropic xác định bối cảnh riêng biệt là trường hợp sử dụng hợp lệ cho các tác nhân phụ trong quy trình làm việc của tác nhân.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-16', 'ccdv-f', 16, 'A teammate is reviewing the team’s threat model for a Claude application and has asked you to identify the AI-specific threat categories the model should cover. The teammate has already listed traditional web-application threats and wants to know which additional categories apply to a Claude application.  
  
Which AI-specific threat categories would you add?', '[{"key":"A","text":"Supply chain attacks on the Claude SDK because the SDK itself is the only point of vulnerability that a Claude application introduces beyond traditional web application threats."},{"key":"B","text":"Network-level denial of service and physical infrastructure attacks, because these categories cover the threats most likely to affect any Claude application in production."},{"key":"C","text":"Cross-site scripting and SQL injection, because these traditional web application threats apply with equal weight to any application that uses Claude in any way."},{"key":"D","text":"Prompt injection, data leakage from prompts or context, jailbreak attempts, and unsafe model output that bypasses application controls."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ứng dụng Claude có những rủi ro dành riêng cho LLM: prompt injection có thể chuyển hướng hành vi của mô hình, lời nhắc và ngữ cảnh có thể tiết lộ dữ liệu nhạy cảm, các nỗ lực bẻ khóa có thể phá vỡ các biện pháp bảo vệ và đầu ra được tạo không an toàn có thể bỏ qua hoặc làm suy yếu các biện pháp kiểm soát ứng dụng. Anthropic xác định các bản bẻ khóa và cả prompt injection trực tiếp và gián tiếp là các mô hình mối đe dọa riêng biệt, đồng thời khuyến nghị hạn chế quyền truy cập của mô hình vào dữ liệu và hành động nhạy cảm.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-17', 'ccdv-f', 17, 'A Claude agent can access a tool that retrieves customer records. A teammate observes that the agent sometimes invokes the tool with arguments not declared by its schema, causing the downstream service to return an error each time. The teammate suggests loosening the schema so the tool accepts any arguments the model generates.  
  
How would you respond?', '[{"key":"A","text":"Remove the schema entirely and rely on the downstream service to reject invalid calls, treating the downstream service as the team’s primary enforcement layer."},{"key":"B","text":"Loosen the schema as the teammate proposed so the downstream service receives every call the agent makes during normal operation."},{"key":"C","text":"Add a system prompt instruction telling the model to produce schema-conforming arguments, treating the prompt instruction as the primary mechanism for keeping the agent’s tool calls valid."},{"key":"D","text":"Keep the schema strict, validate arguments before dispatching, and return a structured error so the agent can retry."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lược đồ công cụ thiết lập hợp đồng đầu vào hợp lệ cho một công cụ. Quá trình xác thực nghiêm ngặt trước khi gửi sẽ ngăn các đối số không đúng định dạng hoặc không được khai báo tiếp cận dịch vụ hạ nguồn và lỗi công cụ có cấu trúc sẽ cung cấp phản hồi mà tổng đài viên có thể sử dụng để thực hiện lần thử lại đã sửa. Lời nhắc có thể cải thiện hành vi nhưng không thay thế việc xác thực ở ranh giới hệ thống.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-18', 'ccdv-f', 18, 'Your Claude agent’s hooks currently fire for every action, substantially slowing the agent even when the actions present no risk. The team wants to scope the hooks more precisely. How should you scope the hooks?', '[{"key":"A","text":"Replace hooks with system prompt instructions on the grounds that prompt instructions can produce the same enforcement effect that hooks produce on the agent’s actions."},{"key":"B","text":"Scope hooks to only the high-risk actions, such as destructive operations or sensitive data access, and remove hooks from low-risk actions to balance safety with performance."},{"key":"C","text":"Disable all hooks while the team re-scopes them, treating the period of no hook enforcement as a temporary state during the re-scoping work."},{"key":"D","text":"Disable the agent during peak hours so the hook overhead does not slow the application down during the busiest periods of the day across the application’s operation."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cấu hình hook Claude Code hỗ trợ các bộ so khớp và bộ lọc có điều kiện hạn chế trình xử lý thực hiện các lệnh gọi hoặc lệnh phụ công cụ có liên quan. Chỉ áp dụng móc nối cho các hoạt động có rủi ro cao—chẳng hạn như các lệnh phá hoại hoặc truy cập dữ liệu nhạy cảm—duy trì các biện pháp bảo vệ mang tính quyết định đồng thời tránh chi phí quá trình thực hiện chúng đối với các hành động có rủi ro thấp.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-19', 'ccdv-f', 19, 'You are designing an agent for a multi-step research task. You want it to divide the task into smaller parts, delegate each part to a specialized subagent, and consolidate the results. The agent pattern to apply is ...', '[{"key":"A","text":"a single tool-use loop that includes every tool the agent might need across all subtasks."},{"key":"B","text":"an orchestrator and subagent pattern with specialized subagents assigned to each subtask."},{"key":"C","text":"a memory pattern that stores the entire research history in advance, before any subtask begins execution."},{"key":"D","text":"a context-window pruning pattern that drops each subtask’s content after the agent moves on."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mẫu người quản lý/người điều phối sử dụng một tác nhân trung tâm để ủy thác công việc cho các tác nhân chuyên môn và tổng hợp kết quả đầu ra của họ thành một kết quả thống nhất. OpenAI mô tả đây là mẫu trình quản lý cho quy trình làm việc đa tác nhân được phối hợp.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-20', 'ccdv-f', 20, 'You are creating an agent that must call multiple internal APIs and a database in a structured, repeatable manner. Your team has chosen the Claude Agent SDK instead of building a custom loop. You are configuring the agent’s tool definitions and execution loop. How should you configure the tools and execution loop?', '[{"key":"A","text":"Call the Messages API directly and let the model format its tool calls in plain text."},{"key":"B","text":"Use the SDK’s tool interface and loop, with conversation history stored in a separate team database."},{"key":"C","text":"Use the SDK’s tool interface and let the SDK handle the loop, dispatch, and history."},{"key":"D","text":"Use the SDK’s tool interface and write the loop and history layer in the team’s own code."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Trình chạy công cụ SDK của Claude hỗ trợ các công cụ do SDK xác định và tự động quản lý vòng lặp tác nhân, bao gồm việc gửi công cụ, xử lý yêu cầu/phản hồi và lịch sử trạng thái hội thoại. Điều này loại bỏ nhu cầu xây dựng và duy trì một vòng lặp tùy chỉnh hoặc lớp lịch sử riêng biệt cho quy trình làm việc sử dụng công cụ thông thường.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-21', 'ccdv-f', 21, 'Your team’s Claude agent has built up several customizations that bypass the SDK defaults, including custom history management, retry logic, and error handling. A new team member proposes reverting every customization to make the codebase easier to maintain. The tech lead disagrees, stating that each customization was introduced for a reason. What would you advise the team?', '[{"key":"A","text":"Revert all customizations to the SDK’s defaults to standardize the codebase."},{"key":"B","text":"Decide on each customization individually based on its original reason and the SDK’s current capabilities."},{"key":"C","text":"Keep all customizations, trusting that the tech lead’s original reasoning is still valid."},{"key":"D","text":"Migrate the agent off the SDK and rebuild it with a custom loop."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mỗi lần ghi đè SDK phải được đánh giá riêng dựa trên nhu cầu đã chứng minh ban đầu và khả năng hiện tại của SDK. Điều này duy trì hành vi tùy chỉnh ở những nơi cần thiết đồng thời loại bỏ các phần ghi đè đã trở nên dư thừa, cải thiện khả năng bảo trì mà không làm mất đi độ tin cậy hoặc chức năng cần thiết.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-22', 'ccdv-f', 22, 'Your team’s Claude application has been in production for one year, and the team has chosen to formalize its testing strategy. At present, the team writes ad-hoc tests for individual features but lacks an overall testing approach. Which testing approach should be formalized?', '[{"key":"A","text":"Adopt a test-driven development practice where unit tests are written before each feature is implemented and must pass before code is merged."},{"key":"B","text":"Define unit tests for individual functions, integration tests for the Claude integration, and end-to-end tests for critical user flows, applied consistently across the codebase."},{"key":"C","text":"Continue writing ad-hoc tests as features ship and introduce a peer review step to ensure each test adequately covers the feature being released."},{"key":"D","text":"Define a single testing approach that uses end-to-end tests and apply it consistently across all new features as they are added to the codebase."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chiến lược thử nghiệm theo lớp giúp xác thực nhanh chóng, tập trung các chức năng riêng lẻ thông qua các thử nghiệm đơn vị, xác minh sự tích hợp Claude với các thử nghiệm tích hợp và bảo vệ các hành trình quan trọng nhất của người dùng bằng các thử nghiệm toàn diện. Việc áp dụng các cấp độ này một cách nhất quán sẽ mang lại phạm vi bao phủ toàn diện và có thể bảo trì cho cơ sở mã; chỉ dựa vào các thử nghiệm toàn diện hoặc tiếp tục thử nghiệm đặc biệt sẽ không mang lại sự cân bằng đó.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-23', 'ccdv-f', 23, 'A teammate submitted a pull request that introduces a Claude-powered feature to your service. The code functions, but its prompt and model choice are hard-coded inline, it lacks error handling, and there are no tests for the integration. What would you request in code review?', '[{"key":"A","text":"Request changes that move prompt and model configuration to a configurable location, add error handling for Claude API failures, and add tests for the integration."},{"key":"B","text":"Request changes that move prompt and model configuration to a configurable location and add tests, treating the missing error handling as a follow-up release item."},{"key":"C","text":"Approve the pull request and add the missing pieces yourself in a follow-up commit so the teammate can move on to other work immediately."},{"key":"D","text":"Approve the pull request as-is, on the grounds that the feature works in the happy path and the missing pieces can be added in follow-up commits."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cài đặt mô hình và lời nhắc phải có thể định cấu hình được, lỗi API Claude yêu cầu xử lý lỗi rõ ràng để có hành vi dịch vụ đáng tin cậy và cần có các thử nghiệm tích hợp để xác thực tính năng và ngăn chặn sự hồi quy. Cả ba đều là những thay đổi cần xem xét trước khi phê duyệt.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-24', 'ccdv-f', 24, 'A teammate asks why your Claude application sometimes returns a response that repeats the prompt text, while at other times it rephrases that prompt text. They suspect there is a bug in the application’s request construction. How would you respond?', '[{"key":"A","text":"Explain that LLMs generate output token by token, and variation in how prompt content appears in output is a property of generation, not a bug in request construction."},{"key":"B","text":"Confirm that the variation is a bug in the application’s request construction and start investigating which part of the application is producing the inconsistent prompt text."},{"key":"C","text":"Tell the teammate that the variation depends on which Claude model serves the request, and recommend pinning the application to a single model version to make the output behavior consistent."},{"key":"D","text":"Tell the teammate that the variation is caused by the application sending two different prompts on different runs and propose a code change that pins the system prompt to a single version."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô hình ngôn ngữ tạo đầu ra dưới dạng sự tiếp nối từng mã thông báo của ngữ cảnh đầu vào của chúng. Sự thay đổi thông thường trong quá trình tạo có thể khiến từ ngữ nhắc nhở được lặp lại trong một phản hồi và được trình bày lại trong một phản hồi khác mà không cho thấy lỗi trong việc xây dựng yêu cầu.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-25', 'ccdv-f', 25, 'The team is considering whether to integrate with the Claude API directly or via a third-party abstraction layer that supports multiple LLM providers. The team has determined that all current and anticipated use cases run on Claude, no internal customer has asked for LLM portability, and the product roadmap contains no multi-provider support over the next two years. The third-party abstraction would add about 15 percent overhead in code complexity and introduce an additional dependency.  
  
Which integration approach would you recommend?', '[{"key":"A","text":"The third-party abstraction layer, on the grounds that multi-provider support is valuable for any application as a matter of long-term flexibility across vendors."},{"key":"B","text":"Direct integration with Claude through its SDK, because no multi-provider need exists and abstraction would add complexity that does not pay off."},{"key":"C","text":"A custom multi-provider abstraction layer the team builds in-house so that the team controls every part of the abstraction the application uses for its API calls."},{"key":"D","text":"Both integration paths in parallel, where the application uses each path on different runs to compare which performs better in production over time."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc tích hợp SDK Claude trực tiếp đáp ứng mọi yêu cầu đã xác định đồng thời tránh được sự phức tạp và sự phụ thuộc của mã bổ sung do tính trừu tượng của nhiều nhà cung cấp. Lớp trừu tượng chỉ hợp lý khi tính di động của nhà cung cấp hoặc hỗ trợ nhiều nhà cung cấp mang lại lợi ích mong đợi cụ thể.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-26', 'ccdv-f', 26, 'You are examining an architectural diagram for a Claude-powered travel-booking system. It depicts a top-level component that interprets user requests and three subordinate components responsible for flights, hotels, and ground transportation. The top-level component routes each request, sequences the subordinate components, and reconciles their outputs into a final itinerary. The diagram also indicates that every subordinate component has its own tool list and its own short conversation history, neither of which is shared with the others. Which architectural pattern does this diagram most closely represent?', '[{"key":"A","text":"A manager and supervisor pattern with shared context, where the top-level agent and the subagents all share a single conversation history that grows as the request flows through the system."},{"key":"B","text":"A manager and supervisor pattern with isolated context per subagent, where the top-level agent coordinates specialized subagents that each maintain their own conversation history and tool list."},{"key":"C","text":"A retrieval-augmented pattern, where the top-level component retrieves relevant context from the subordinate components'' indexed data stores before generating each response."},{"key":"D","text":"A pipeline pattern, where each component processes the user request in sequence and passes the full conversation history along with the request to the next component in the pipeline."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Người quản lý hoặc người giám sát điều phối các đại lý phụ chuyên biệt, ủy quyền các phần có liên quan của nhiệm vụ, sắp xếp trình tự công việc và tổng hợp kết quả đầu ra của họ. Danh sách công cụ riêng biệt và lịch sử hội thoại không chia sẻ cho biết ngữ cảnh riêng biệt cho từng tác nhân phụ, thay vì mẫu trình quản lý ngữ cảnh dùng chung hoặc quy trình chuyển toàn bộ lịch sử giữa các giai đoạn. Hướng dẫn của Anthropic xác định bối cảnh biệt lập và luồng công việc độc lập là cách sử dụng thích hợp cho các tác nhân phụ.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-27', 'ccdv-f', 27, 'You are designing a Claude application that preserves user sessions across multi-turn conversations. The product team has asked how the application will manage session lifecycle: when sessions should expire, how state is reset, and how it prevents stale context from being carried into new conversations. How would you design the session lifecycle?', '[{"key":"A","text":"Define explicit session expiration rules but rely on users to start new conversations when they want fresh context, with no automatic reset triggers in the application."},{"key":"B","text":"Define explicit session expiration rules, state reset triggers, and rules for starting fresh sessions so stale context does not leak into new conversations."},{"key":"C","text":"Define a single short session timeout that applies across all conversations and treat the timeout as the application’s complete session lifecycle mechanism."},{"key":"D","text":"Define state reset triggers tied to specific application events but apply them across all sessions globally, with no per-session expiration rules."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Vòng đời phiên mạnh mẽ xác định các quy tắc hết hạn mỗi phiên, trình kích hoạt rõ ràng giúp xóa trạng thái phiên và các điều kiện để bắt đầu phiên mới. Cùng với nhau, các biện pháp kiểm soát này ngăn chặn bối cảnh hội thoại cũ bị rò rỉ sang các cuộc hội thoại tiếp theo.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-28', 'ccdv-f', 28, 'Your enterprise has an AWS contract requiring Claude API calls to be routed through Amazon Bedrock instead of the direct Anthropic API. Your team is developing a new Claude application and is unfamiliar with this restriction. How should you build the application?', '[{"key":"A","text":"Build two parallel implementations of every call, one for the direct Anthropic API and one for Bedrock, and pick the faster one at runtime."},{"key":"B","text":"Configure the application to invoke Claude through the Bedrock-compatible API path while keeping the application’s logic provider- agnostic."},{"key":"C","text":"Build the application against the direct Anthropic API and ignore the contractual requirement to route Claude calls through Amazon Bedrock."},{"key":"D","text":"Build the application against the direct Anthropic API now and migrate to Bedrock in a follow-up release once the team has more experience with the Bedrock API."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Yêu cầu của Claude phải được gửi qua Amazon Bedrock để đáp ứng yêu cầu định tuyến theo hợp đồng. Anthropic hỗ trợ gọi Claude trên Bedrock thông qua tích hợp Bedrock và SDK, cho phép logic tương tác Claude cấp cao hơn của ứng dụng vẫn tách rời khỏi nhà cung cấp cơ bản trong khi đường dẫn gọi được định cấu hình sử dụng Bedrock.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-29', 'ccdv-f', 29, 'You have recently deployed a new Claude-powered application to production. Development is finished, and the system is now actively used by internal teams. The system’s next phase of work is ...', '[{"key":"A","text":"operating and maintaining the system, including monitoring, responding to issues, and planning evolution."},{"key":"B","text":"handing the system over to a separate operations team that will manage it independently of the development team going forward."},{"key":"C","text":"retiring the system, since shipping is the final lifecycle stage for any application that reaches production."},{"key":"D","text":"running a formal post-deployment review that assesses the development phase before the team does any further work on the system."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một ứng dụng sản xuất sẽ tiến hành các hoạt động và bảo trì liên tục, bao gồm giám sát, ứng phó sự cố và lập kế hoạch hoặc đưa ra sự phát triển trong tương lai.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-30', 'ccdv-f', 30, 'You are setting up Claude Code for a new project. The team must configure permissions, default model selections, and environment-specific behavior at the project level so that the configuration remains consistent for every developer working in the repository. Which Claude Code mechanism would you use?', '[{"key":"A","text":"environment variables that each developer sets on their own machine when working with Claude Code on the project."},{"key":"B","text":"a shared spreadsheet that lists configuration values for team members to reference and update by hand as the project evolves."},{"key":"C","text":"the settings.json file, scoped at the project level so the configuration applies consistently across developers and persists with the repository."},{"key":"D","text":"a system prompt embedded in every Claude Code conversation by each developer at the start of every session in the project."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tệp `.claude/settings.json` trong phạm vi dự án được kiểm soát phiên bản bằng kho lưu trữ và được chia sẻ giữa các cộng tác viên. Nó hỗ trợ cấu hình như quyền, biến môi trường và mặc định của mô hình, cung cấp hành vi Claude Code nhất quán ở cấp dự án.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-31', 'ccdv-f', 31, 'You are developing a Claude application that must keep a persistent connection to a service streaming real-time updates. The team is uncertain which communication pattern to use. Which communication pattern would you choose?', '[{"key":"A","text":"A single long HTTP request the server holds open indefinitely, with no standard websocket framing on the connection."},{"key":"B","text":"File-based communication where the service writes new updates to disk and the application polls the file system for changes."},{"key":"C","text":"A websocket, because websockets are designed for bidirectional, persistent, real-time communication between the client and the streaming service."},{"key":"D","text":"Repeated short-lived HTTP polling requests, where the application opens a new HTTP connection each time it checks for updates."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }WebSockets được thiết kế để liên lạc liên tục, hai chiều, theo thời gian thực giữa khách hàng và dịch vụ phát trực tuyến, tránh chi phí và độ trễ của các yêu cầu thăm dò lặp đi lặp lại.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-32', 'ccdv-f', 32, 'Your Claude application’s prompt was authored months ago and has not been updated. The team has learned through evaluations that the prompt performs well for common cases but performs poorly for a particular category of inputs whose volume has increased. How should you respond?', '[{"key":"A","text":"Replace the prompt with a new one aligned to the underperforming category, treating any common-case performance change as a known tradeoff."},{"key":"B","text":"Tell users to avoid the underperforming category by adding warnings in the application''s user interface about handled inputs."},{"key":"C","text":"Iterate on the prompt to address the underperforming category, validate the change with evals, and continue refining as needed."},{"key":"D","text":"Add the underperforming category to a separate Claude application with its own prompt so the original prompt does not change."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Prompt engineering phải là một quá trình lặp đi lặp lại: cập nhật lời nhắc để cải thiện hiệu suất cho danh mục lỗi ngày càng tăng, xác thực bản cập nhật bằng các đánh giá cũng bảo vệ hiệu suất trong trường hợp thông thường và tiếp tục tinh chỉnh dựa trên kết quả.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-33', 'ccdv-f', 33, 'You are developing a Claude application that must provide model output to end users as it is produced, rather than waiting for the entire response to finish. The Claude API mechanism to use is ...', '[{"key":"A","text":"structured JSON output, which delivers responses only after the model has finalized the JSON shape across the entire response."},{"key":"B","text":"prompt caching, which speeds up the cost profile of future requests and does not affect the delivery timing of the first response."},{"key":"C","text":"streaming responses, which deliver tokens incrementally as the model generates them so users see output progressively."},{"key":"D","text":"the batch API, which delivers full responses after a delay suitable for non-interactive workloads."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng phát trực tuyến của Claude gửi dần dần các phản hồi của API Tin nhắn thông qua các sự kiện do máy chủ gửi, bao gồm cả các vùng văn bản khi quá trình tạo diễn ra. Điều này cho phép ứng dụng hiển thị đầu ra dần dần thay vì chờ phản hồi hoàn chỉnh.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-34', 'ccdv-f', 34, 'You are designing a Claude application that processes customer-support tickets in two stages: a triage stage that classifies tickets and a response stage that drafts replies. The team is considering either one Claude call for both stages or separate Claude calls for each stage. How would you structure the application?', '[{"key":"A","text":"Use separate Claude calls for triage and response, because each stage has distinct inputs, outputs, and success criteria that benefit from focused prompts."},{"key":"B","text":"Use a single Claude call for triage and then use a non-Claude rule-based system for response generation, on the grounds that rule-based systems are more reliable for drafting replies."},{"key":"C","text":"Use multiple Claude calls in parallel that each draft a complete ticket reply, then have a fourth Claude call select the best one to send to the customer."},{"key":"D","text":"Use a single Claude call for both stages, on the grounds that a single call is cheaper than multiple calls in any production Claude application setup."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các lệnh gọi Claude riêng biệt cho phép giai đoạn phân loại sử dụng lời nhắc phân loại tập trung và tạo ra kết quả trung gian có thể được kiểm tra, đánh giá, định tuyến hoặc hạn chế trước khi lời nhắc dành riêng cho phản hồi soạn thảo câu trả lời. Chuỗi nhắc nhở rõ ràng phù hợp khi ứng dụng cần một quy trình tuần tự được xác định và các đầu ra trung gian có thể quan sát được.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-35', 'ccdv-f', 35, 'The product team has expressed a new Claude feature in business terms: “agents should help our analysts create client memos more quickly.” You need to translate this into actionable technical requirements for the engineering team. Your first step would be to …', '[{"key":"A","text":"ask the analysts about the current memo production process to see where they think Claude could be introduced as a prompt-driven drafting step."},{"key":"B","text":"examine what model capabilities and tier options are available and determine which best supports the memo drafting workflow described by the product team."},{"key":"C","text":"assess what similar agent-based features have been built internally or in the industry and use those precedents to scope the technical approach."},{"key":"D","text":"interpret the functional and infrastructure requirements implied by the business goal."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các mục tiêu kinh doanh trước tiên phải được hiểu là các yêu cầu về chức năng, chẳng hạn như nhiệm vụ soạn thảo bản ghi nhớ bắt buộc của tổng đài viên và tương tác của người dùng cũng như các yêu cầu về cơ sở hạ tầng hoặc phi chức năng, chẳng hạn như các hạn chế về hiệu suất, bảo mật, tích hợp và độ tin cậy. Những yêu cầu đó cung cấp cơ sở cho việc khám phá quy trình làm việc, lựa chọn mô hình và phạm vi kỹ thuật sau này.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-36', 'ccdv-f', 36, 'Your team is getting ready to deploy a configuration change that updates several prompt versions across a Claude application used by multiple downstream systems. The change has already been tested in staging, but the team has not evaluated how the prompt change will affect every downstream system that relies on the application''s output. What should you do before deploying the change?', '[{"key":"A","text":"Document the prompt version changes in the application changelog and proceed with the rollout, treating the staging test results as sufficient evidence of impact across all downstream systems."},{"key":"B","text":"Limit the rollout to systems that were explicitly included in staging testing, and defer all other downstream systems until a later release cycle."},{"key":"C","text":"Notify downstream system owners that a change is coming and schedule the rollout for the following week, without conducting a formal impact assessment."},{"key":"D","text":"Assess the configuration impact on each downstream system before rolling out, and coordinate with downstream system owners as needed."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Thay đổi phiên bản nhắc nhở có thể thay đổi hợp đồng đầu ra, hành vi, định dạng hoặc chất lượng mà các hệ thống phụ thuộc sử dụng. Do đó, mỗi phần phụ thuộc hạ nguồn đều yêu cầu đánh giá tác động trước khi triển khai, với sự phối hợp từ chủ sở hữu nếu cần. Hướng dẫn đánh giá của Anthropic khuyên bạn nên chạy lại bộ đánh giá đầy đủ sau khi cập nhật kịp thời để xác định xem lời nhắc mới ảnh hưởng như thế nào đến hiệu suất trong các trường hợp thử nghiệm.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-37', 'ccdv-f', 37, 'Your Claude application makes a high volume of API calls during business hours and very few calls overnight. The team is concerned about remaining within rate limits at peak hours and wants to understand how the Claude API applies those limits. How should you proceed?', '[{"key":"A","text":"Examine the peak-hour request patterns in your application logs and smooth traffic by distributing requests more evenly across the business-hours window."},{"key":"B","text":"Assess the average payload size of current API calls and consolidate requests where possible to reduce the total number of calls made during peak hours."},{"key":"C","text":"Review the API documentation for streaming endpoints and evaluate whether migrating peak-hour calls to streaming reduces exposure to rate limit enforcement."},{"key":"D","text":"Identify the rate limits, design the application to stay within them during peak hours, and use exponential backoff when limits are reached."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }API Claude thực thi các giới hạn cấp tổ chức đối với các yêu cầu mỗi phút, mã thông báo đầu vào mỗi phút và mã thông báo đầu ra mỗi phút, bao gồm cả các khoảng thời gian ngắn thông qua cơ chế nhóm mã thông báo. Các ứng dụng phải xác định các giới hạn có thể áp dụng của mình, duy trì lưu lượng truy cập vào giờ cao điểm trong giới hạn đó và xử lý các phản hồi giới hạn tốc độ bằng cách chờ và thử lại với độ trễ theo cấp số nhân. Phản hồi giới hạn tốc độ 429 cung cấp tiêu đề `retry-after` cho biết thời điểm thử lại có thể thành công.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-38', 'ccdv-f', 38, 'A teammate asks you to explain the distinction between context engineering and prompt engineering. They have heard the terms used interchangeably and are uncertain how each applies to a Claude application that handles long-running, multi-step tasks. How would you describe the difference?', '[{"key":"A","text":"Prompt engineering focuses on the model''s response, while context engineering focuses on the user’s input across many sessions in a long-running multi-step Claude application."},{"key":"B","text":"Prompt engineering and context engineering each address content the team gives Claude, but the team can group them under a single workflow because the practices use overlapping techniques."},{"key":"C","text":"Prompt engineering is the older term for prompt design, while context engineering is the newer term that has replaced it in modern Claude applications across the industry."},{"key":"D","text":"Prompt engineering shapes individual prompts for specific outputs, while context engineering manages how content flows across turns and steps and takes steps to keep relevant state visible."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Prompt engineering định hình các hướng dẫn, ví dụ, ràng buộc và định dạng đầu ra của một tương tác mô hình riêng lẻ. Kỹ thuật bối cảnh quản lý thông tin liên quan và trạng thái được cung cấp trong suốt quy trình làm việc dài, gồm nhiều bước, bao gồm tính liên tục giữa các lượt hoặc cửa sổ ngữ cảnh, do đó mô hình sẽ giữ lại thông tin cần thiết cho công việc tiếp theo.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-39', 'ccdv-f', 39, 'A Claude application sometimes declines to answer questions that should be within scope, including questions it has previously answered correctly. You want to investigate this behavior. What should be the first step of the investigation?', '[{"key":"A","text":"Identify which questions have been refused and compare them against previously answered questions to determine what changed between the successful and refused interactions."},{"key":"B","text":"Test whether removing or adjusting those instructions resolves the behavior."},{"key":"C","text":"Assess whether the refusals cluster around specific input patterns, question types, or time periods by analyzing the distribution of refused requests in the logs."},{"key":"D","text":"Examine traces of the refused requests to identify what triggers the refusal, whether input patterns, system prompt content, or other context."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Dấu vết yêu cầu hiển thị bối cảnh đầy đủ của mỗi lần từ chối, cho phép xác định trình kích hoạt cụ thể—chẳng hạn như mẫu đầu vào, nội dung lời nhắc của hệ thống hoặc bối cảnh yêu cầu khác—trước khi thực hiện thay đổi hoặc thực hiện phân tích tổng hợp. Claude xác định các trường hợp từ chối an toàn bằng lý do dừng `refusal`, do đó, việc kiểm tra ở cấp độ yêu cầu là điểm khởi đầu thích hợp để chẩn đoán các trường hợp đó.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-40', 'ccdv-f', 40, 'A new Claude model release provides performance improvements for several reasoning tasks, but it changes how it responds to system prompts containing multi-section instructions. Your application relies extensively on multi-section system prompts. An initial evaluation using the application’s real workload finds that the new model performs 8 percent better on reasoning tasks, but its format change causes malformed output on approximately 3 percent of requests. The team is considering whether to upgrade.  
  
How would you make the decision?', '[{"key":"A","text":"Upgrade and add a downstream validation step that catches the 3 percent malformed output before it reaches users, treating the validation step as the team’s mitigation for the format change."},{"key":"B","text":"Adapt the application’s system prompt to the new model’s format expectations and re-evaluate, then upgrade only if the adapted prompt eliminates the malformed output while preserving the reasoning improvements."},{"key":"C","text":"Stay on the previous model permanently to avoid the malformed output rate and any future format changes that subsequent model releases might introduce in the application."},{"key":"D","text":"Upgrade immediately, because the 8 percent reasoning improvement outweighs the 3 percent malformed output rate across the application’s typical request distribution."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc nâng cấp mô hình phải được xác thực theo lời nhắc và khối lượng công việc thực tế của ứng dụng. Khi xảy ra hồi quy do định dạng phản hồi đã thay đổi cho lời nhắc hệ thống nhiều phần, hãy điều chỉnh lời nhắc cho phù hợp với quy ước hướng dẫn và định dạng tài liệu của mô hình mới, sau đó là đánh giá lại, trực tiếp kiểm tra xem liệu khả năng tương thích có thể được khôi phục mà không làm mất đi lợi ích lý luận đã đo được hay không. Hướng dẫn nhắc nhở của Claude đề xuất các yêu cầu đầu ra rõ ràng, rõ ràng và lời nhắc có cấu trúc dành cho các lệnh phức tạp, đồng thời hướng dẫn di chuyển yêu cầu cập nhật lời nhắc và cấu hình khi di chuyển giữa các thế hệ mô hình.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-41', 'ccdv-f', 41, 'You are establishing the configuration-management approach for a new Claude Code project. Your team will use `CLAUDE.md` files and `settings.json` files to control behavior, and you want to ensure that changes are tracked and reviewable. The configuration-management approach would ...', '[{"key":"A","text":"version-control CLAUDE.md alongside the project’s source code and settings.json files in a separate repository from the project’s source code."},{"key":"B","text":"version-control CLAUDE.md and settings.json files alongside the project’s source code, with changes reviewed through standard pull request workflows the team applies."},{"key":"C","text":"duplicate CLAUDE.md and settings.json files in multiple repositories to provide redundancy, on the grounds that a single source of truth is risky for project configuration."},{"key":"D","text":"version-control CLAUDE.md and settings.json files in a separate repository from the project’s source code, so configuration evolves independently from the application code over time."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các hướng dẫn `CLAUDE.md` cấp dự án được nhóm chia sẻ thông qua kiểm soát nguồn và cài đặt dự án được chia sẻ thuộc về kho lưu trữ mà họ định cấu hình. Việc giữ cả hai bên cạnh nguồn ứng dụng sẽ cung cấp một lịch sử có thể xem lại và cho phép các điều khiển yêu cầu kéo tiêu chuẩn chi phối các thay đổi đối với mã và cấu hình Claude Code của nó.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-42', 'ccdv-f', 42, 'You are launching a new Claude application and have a small set of well-labeled examples that show the required output format. You want to use these examples to steer Claude’s behavior. How would you guide the application’s behavior?', '[{"key":"A","text":"Embed the examples in a database and retrieve them at runtime as reference material for the team."},{"key":"B","text":"Use zero-shot prompting and rely on the model’s general capability to produce the desired output format consistently across all incoming requests."},{"key":"C","text":"Train a custom model on the labeled examples before deployment so that the application does not need to include the examples in any prompt during operation."},{"key":"D","text":"Use multi-shot prompting by including the labeled examples in the prompt so Claude can match the desired output format on each request."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lời nhắc nhiều cảnh bao gồm các ví dụ được gắn nhãn trong lời nhắc, cho phép Claude nhận dạng và tái tạo định dạng đầu ra dự định cho từng yêu cầu. Anthropic xác định các ví dụ few-shot hoặc nhiều ảnh được chế tạo tốt như một cách đáng tin cậy để định hướng định dạng đầu ra và cải thiện tính nhất quán.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-43', 'ccdv-f', 43, 'A Claude application produces outputs that progressively drift from the expected JSON format after several conversation turns. The initial few turns generate correctly formatted output, but later turns gradually lose structure. How would you address this drift?', '[{"key":"A","text":"Truncate every response to the first few characters, validate that the truncated output matches the expected JSON structure, and log any mismatches for review."},{"key":"B","text":"Identify the failure mode as format drift, examine how the conversation context evolves over turns, and address the drift through context management or output validation."},{"key":"C","text":"Switch to a smaller Claude model and re-test the application to determine whether the drift persists across conversation turns."},{"key":"D","text":"Restart the application after every turn and monitor whether the format remains consistent across subsequent interactions."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Sự lệch định dạng trong ứng dụng nhiều lượt được giải quyết bằng cách kiểm tra xem ngữ cảnh hội thoại tích lũy ảnh hưởng như thế nào đến việc tuân thủ hướng dẫn, quản lý ngữ cảnh đó và xác thực kết quả đầu ra theo cấu trúc JSON được yêu cầu. Các ràng buộc rõ ràng về định dạng đầu ra và lời nhắc có cấu trúc giúp duy trì định dạng nhất quán, trong khi quá trình xác thực sẽ phát hiện các đầu ra không đạt sơ đồ yêu cầu.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-44', 'ccdv-f', 44, 'Your team uses Claude Code across several repositories. You want team rules and general coding standards to apply to every repository, while other rules should apply only to particular repositories. The team currently duplicates instructions in each repository’s `CLAUDE.md` file. How would you handle this?', '[{"key":"A","text":"Use a CLAUDE.md hierarchy that scopes general standards broadly and project-specific context within each repository’s local CLAUDE.md."},{"key":"B","text":"Stop using CLAUDE.md altogether and ask each developer to configure Claude Code manually for each project they work on."},{"key":"C","text":"Move all instructions to a separate documentation site that developers consult during Claude Code sessions across all repositories."},{"key":"D","text":"Use a single repository’s CLAUDE.md as the central source of truth and link to it from every other repository’s CLAUDE.md file."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code đọc các tệp `CLAUDE.md` theo thứ bậc, cho phép các hướng dẫn có phạm vi rộng nhằm cung cấp các tiêu chuẩn chung và các tệp cục bộ trong kho lưu trữ để thêm các quy tắc dành riêng cho dự án. Điều này tập trung hướng dẫn chung mà không làm mất bối cảnh cụ thể của kho lưu trữ.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-45', 'ccdv-f', 45, 'A team has deployed a multi-agent system where a primary agent breaks down user requests and assigns subtasks to three specialized subagents: one for data retrieval, one for analysis, and one for report generation. In production, the team finds that subagents make redundant tool calls, sometimes exceed token budgets, and occasionally produce contradictory outputs—all of which the primary agent forwards without detecting. What is the most appropriate way to resolve these failures?', '[{"key":"A","text":"Strengthen the primary agent’s management layer to enforce per-subagent tool budgets, validate outputs against a defined schema before passing them forward, and establish explicit handoff contracts between stages."},{"key":"B","text":"Give each subagent read access to the other subagents’ outputs so they can identify and resolve contradictions without routing back through the primary agent."},{"key":"C","text":"Add retry logic to each subagent so that when a tool call fails, the subagent retries automatically before escalating – and configure each subagent to log its tool calls and outputs to a shared trace so the team can audit redundancy and contradictions after the fact."},{"key":"D","text":"Collapse the three subagents into a single large-context model call that handles retrieval, analysis, and generation in one pass."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lớp điều phối chính sẽ quản lý các tác nhân chuyên biệt thông qua các giới hạn tài nguyên có thể thực thi cho mỗi tác nhân, xác thực đầu ra có cấu trúc và các hợp đồng rõ ràng về thông tin được truyền giữa các giai đoạn. Các biện pháp kiểm soát này ngăn chặn việc tool use và mã thông báo tràn không cần thiết, từ chối các đầu ra không đúng định dạng hoặc không tương thích trước khi truyền bá, đồng thời làm rõ các trách nhiệm và định dạng dữ liệu dự kiến ​​đủ để giảm mâu thuẫn.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-46', 'ccdv-f', 46, 'Your Claude application produces inconsistent outputs for similar inputs, even when it uses the same model and prompt. You want to troubleshoot the issue systematically. Your debugging approach would ...', '[{"key":"A","text":"retry every request that produces an unexpected output and log the results to identify whether repeated calls converge on a consistent response pattern."},{"key":"B","text":"lower the model’s temperature and re-run the inconsistent inputs to determine whether the parameter change reduces output variability across runs."},{"key":"C","text":"capture full traces of input, system prompt, user messages, model output, and parameters, then analyze the differences between consistent and inconsistent runs."},{"key":"D","text":"assume inconsistent outputs reflect normal LLM non-determinism and document the variability as an accepted characteristic of the application’s behavior."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Dấu vết yêu cầu và phản hồi đầy đủ giúp các hoạt động có thể lặp lại và so sánh được. Việc ghi lại đầu vào, lời nhắc hệ thống, thông báo người dùng, đầu ra mô hình và các tham số sẽ bộc lộ những khác biệt ẩn về ngữ cảnh hoặc cấu hình có thể gây ra hành vi không nhất quán. Tài liệu của Anthropic hỗ trợ ghi nhật ký và kiểm tra các đầu ra API trung gian khi chẩn đoán hành vi của ứng dụng.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-47', 'ccdv-f', 47, 'You are choosing among Claude models for a task. The team has identified three relevant tradeoff dimensions: quality, latency, and cost. The appropriate model is the one that ...', '[{"key":"A","text":"fits the task’s quality, latency, and cost requirements together, recognizing that improving one dimension typically affects the others."},{"key":"B","text":"meets the task’s cost target within a defined latency budget, with quality validated against a representative sample of inputs after the model is selected."},{"key":"C","text":"meets the task’s quality requirements at an acceptable latency, with cost reviewed separately once the quality and latency bar has been established."},{"key":"D","text":"satisfies the task’s latency requirement first, then evaluated against quality and cost thresholds to confirm the selection is acceptable across all three dimensions."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc lựa chọn mô hình Claude phải đáp ứng đồng thời các yêu cầu về chất lượng, độ trễ và chi phí của nhiệm vụ vì khả năng của mô hình, thời gian phản hồi và giá mã thông báo là những sự cân bằng phụ thuộc lẫn nhau. Việc chọn theo một chiều trước và đánh giá các chiều khác sau đó có thể tạo ra một mô hình không phù hợp với khối lượng công việc tổng thể. Tài liệu về giá mô hình của Anthropic cũng cho thấy rằng các mô hình Claude có chi phí khác nhau về mặt vật chất, việc củng cố chi phí đó phải được xem xét cùng với các yêu cầu về hiệu suất.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-48', 'ccdv-f', 48, 'You are using Claude Code in an automated continuous-integration pipeline. The pipeline must have Claude Code perform a set of clearly defined tasks without asking for confirmation, and its output must be captured for downstream processing. How should the pipeline be configured?', '[{"key":"A","text":"Disable Claude Code’s confirmation prompts globally across all environments so the pipeline runs without interruption from any prompt."},{"key":"B","text":"Run Claude Code in headless mode with the required permissions configured in settings.json and capture its output for downstream processing."},{"key":"C","text":"Replace Claude Code with a different tool that does not require any configuration to operate without confirmation prompts in the pipeline."},{"key":"D","text":"Run Claude Code in interactive mode and have a developer manually approve every confirmation prompt while the pipeline executes its tasks."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code hỗ trợ thực thi không tương tác/không đầu với chế độ in (`-p`) cho tập lệnh và quy trình CI. Việc định cấu hình trước các công cụ được phép trong `settings.json` cho phép các hành động được xác định chạy mà không cần phê duyệt thủ công và đầu ra JSON hoặc luồng-JSON có thể được ghi lại để xử lý tiếp theo.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-49', 'ccdv-f', 49, 'The Claude application your team built has expanded over six months, and its prompt-handling code has built up duplication and convoluted control flow. The functionality works, but adding new features is becoming more difficult. How should you address this?', '[{"key":"A","text":"Move all the prompt-handling code into a single large function to reduce the number of files developers have to navigate when reading the code."},{"key":"B","text":"Continue adding features and plan a refactoring pass after the next two release cycles when the team has more bandwidth for internal work."},{"key":"C","text":"Plan a refactoring pass to consolidate duplicated logic, separate concerns, and simplify control flow before adding new features."},{"key":"D","text":"Refactor the prompt-handling code in small increments as part of each new feature ticket, treating the cleanup as a side effect of feature work."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một quy trình tái cấu trúc theo kế hoạch sẽ loại bỏ nợ kỹ thuật đang gây khó khăn cho việc phát triển thêm. Hợp nhất logic trùng lặp, tách biệt các mối quan tâm và đơn giản hóa luồng điều khiển sẽ cải thiện khả năng bảo trì và thiết lập nền tảng an toàn hơn cho các tính năng mới.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-50', 'ccdv-f', 50, 'You are configuring a Claude application that will handle a mix of multi-turn conversations and one-off requests. You want to use caching methods to lower token costs where applicable. A teammate also proposes caching the model’s output so the application need not make duplicate Claude calls when similar queries arrive. You would use prompt caching for ...', '[{"key":"A","text":"the model’s output, treating the response from each request as cacheable content the application can return on similar future queries."},{"key":"B","text":"nothing, because prompt caching does not affect cost in any application that mixes multi-turn conversations and one-off requests in a single deployment."},{"key":"C","text":"only the user’s input portion of each request because user input is the part of the prompt that varies the most across the application''s normal operation."},{"key":"D","text":"the static portions of prompts that are repeated across requests, such as system prompts, instructions, or shared context."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Prompt caching sử dụng lại tiền tố giống hệt của lời nhắc API để giảm thời gian và chi phí xử lý mã thông báo đầu vào. Tiền tố có thể sử dụng lại phải chứa nội dung tĩnh lặp lại theo yêu cầu, bao gồm lời nhắc hệ thống, hướng dẫn, ngữ cảnh dùng chung, ví dụ và định nghĩa công cụ. Nó không lưu trữ đầu ra mô hình được tạo ra; bộ nhớ đệm phản hồi ở cấp ứng dụng là một kỹ thuật riêng biệt.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-51', 'ccdv-f', 51, 'Your Claude application uses multi-step workflows in which each step’s output is required only briefly before the agent continues. Cumulative tool output is filling the context window with content that is no longer relevant. How would you manage the accumulating tool output?', '[{"key":"A","text":"Apply prompt caching to the accumulated tool outputs so the application does not re-pay for the older content on each subsequent step."},{"key":"B","text":"Keep every tool output in the context indefinitely so the agent has the full record of every step it has executed during the workflow."},{"key":"C","text":"Switch to a smaller Claude model that processes context more efficiently and treat any quality loss as a tradeoff for the cost reduction."},{"key":"D","text":"Apply tool output pruning to remove tool outputs that are no longer needed by later steps in the workflow."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc cắt bớt đầu ra của công cụ sẽ loại bỏ các kết quả mà các bước quy trình công việc sau này no yêu cầu lâu hơn, ngăn nội dung kết quả công cụ lỗi thời sử dụng cửa sổ ngữ cảnh. Các khối kết quả công cụ đóng góp vào mã thông báo đầu vào được gửi tới Claude, do đó, các kết quả được giữ lại trong bộ nhớ đệm không giải quyết được tình trạng phình to ngữ cảnh.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-52', 'ccdv-f', 52, 'You are deciding between STDIO-based and HTTP-based communication for an MCP server. The server will be started by a locally running Claude Code session. Which communication pattern should you use?', '[{"key":"A","text":"HTTP on the grounds that HTTP is preferable to STDIO in any context the application might encounter during normal operation."},{"key":"B","text":"HTTP polling against the MCP server, treating HTTP as a substitute for the standard MCP communication patterns."},{"key":"C","text":"STDIO and HTTP simultaneously for redundancy, with the team running two communication patterns at the same time across Claude Code sessions."},{"key":"D","text":"STDIO because STDIO is well-suited to local process communication and avoids unnecessary network setup."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }STDIO phù hợp với máy chủ MCP cục bộ, do quy trình sinh ra: máy khách khởi chạy máy chủ dưới dạng quy trình con và trao đổi thông báo JSON-RPC thông qua đầu vào và đầu ra tiêu chuẩn. Điều này tránh được điểm cuối và cấu hình mạng không cần thiết được yêu cầu bởi truyền tải HTTP. [MCP Transport Specification](https://modelcontextprotocol.io/specification/2025-06-18/basic/transports)', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published'),
  ('ccdv-53', 'ccdv-f', 53, 'You are explaining to a stakeholder why executing the same Claude prompt twice may yield slightly different results. The stakeholder is worried that this indicates the application is broken. How would you respond to the stakeholder’s concern?', '[{"key":"A","text":"Tell the stakeholder the variation is caused by Claude being updated continuously by Anthropic, and that switching to a fixed model snapshot will eliminate the variation entirely."},{"key":"B","text":"Tell the stakeholder the variation comes from network latency and that switching to a faster network connection will produce more consistent results across runs."},{"key":"C","text":"Tell the stakeholder the variation is a bug that the team will fix in the next release of the application, then create a work ticket to fix the bug."},{"key":"D","text":"Explain that LLMs are non-deterministic by default due to sampling, and describe how the application handles this through validation, retries, or temperature adjustment."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc tạo LLM mang tính xác suất: việc lấy mẫu có thể chọn các mã thông báo hợp lý khác nhau cho các đầu vào giống hệt nhau, do đó có thể có sự khác biệt nhỏ giữa các lần chạy và bản thân nó không chỉ ra lỗi ứng dụng. Các ứng dụng sản xuất phải quản lý sự thay đổi này bằng các biện pháp như xác nhận đầu ra, thử lại và—khi được hỗ trợ bởi mô hình đã chọn—các biện pháp kiểm soát lấy mẫu chẳng hạn như nhiệt độ. Anthropic lưu ý rằng đầu ra API có thể không mang tính xác định ngay cả ở nhiệt độ 0.', 'General', ARRAY['CCDV-F', 'General']::text[], NULL, 'published')
ON CONFLICT (id) DO UPDATE SET
