BEGIN;

-- 1. Ensure custom_certificates table has is_disabled & badge column
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS is_disabled BOOLEAN DEFAULT false;
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS badge TEXT DEFAULT 'none';

-- 2. Upsert Certificate metadata
INSERT INTO public.custom_certificates (
  id, name, code, description, difficulty, estimated_hours, color_class, icon_name, is_vip, is_disabled, badge
) VALUES (
  'ccar-p',
  'Claude Certified Architect — Professional',
  'CCAR-P',
  'Chinh phục chứng chỉ cấp cao Claude Certified Architect (Professional). Thiết kế hệ thống AI quy mô doanh nghiệp, quản trị rủi ro & an toàn bảo mật, tối ưu hóa độ trễ/chi phí và điều phối tác nhân đa luồng.',
  'Nâng cao',
  '18-24 Giờ',
  'bg-gradient-to-br from-orange-700 via-red-800 to-slate-950 text-white',
  'ShieldCheck',
  false,
  true,
  'new'
) ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  code = EXCLUDED.code,
  description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty,
  estimated_hours = EXCLUDED.estimated_hours,
  color_class = EXCLUDED.color_class,
  icon_name = EXCLUDED.icon_name,
  badge = EXCLUDED.badge;

-- 3. Upsert Questions
INSERT INTO public.questions (
  id, cert_id, question_number, text, options,
  correct_answers, explanation, category, tags, image_url, status
) VALUES
  ('ccarp-1', 'ccar-p', 1, 'You are evaluating a customer-support agent’s configuration. Each prospective tool belongs to one of four categories: (1) required to carry out defined tasks, (2) frequently used and reduces hand-offs, (3) occasionally helpful for unrelated work, (4) speculative future utility.  
  
Which categories should generally stay in the agent configuration?', '[{"key":"A","text":"Only category 3, because occasionally useful tools for unrelated work provide broader coverage and should take priority over tools required for the agent’s defined tasks."},{"key":"B","text":"Only category 4, because speculative future-utility tools provide the most flexibility and should be configured even when no defined task currently requires them."},{"key":"C","text":"Categories 1 and 2 only, because they map to defined tasks and the agent’s regular hand-offs."},{"key":"D","text":"All four categories, because broader tool access is categorically better for agent performance regardless of whether the tools map to defined tasks or regular hand-offs."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các công cụ dành cho tổng đài viên nên được giới hạn ở những khả năng hỗ trợ các nhiệm vụ đã xác định và quy trình hoạt động thông thường. Các công cụ cần thiết cho phép thực hiện công việc dự định của tổng đài viên và các công cụ được sử dụng thường xuyên giúp giảm việc chuyển giao sẽ cải thiện việc thực hiện thường lệ của nó. Đôi khi các công cụ hữu ích không liên quan và các công cụ mang tính suy đoán trong tương lai không biện minh cho việc truy cập hiện tại và mở rộng bộ công cụ có sẵn một cách không cần thiết. API của OpenAI hỗ trợ ràng buộc mô hình với một bộ công cụ được phép xác định trước.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-2', 'ccar-p', 2, 'A technical team is cataloguing risks particular to Claude’s use in a document-grounded Q&A system.  
  
Which two items are failure modes inherent to LLM-based systems rather than generic software defects? (Select two.)', '[{"key":"A","text":"An expired TLS certificate blocks outbound API calls to Claude."},{"key":"B","text":"A database connection timeout causes retrieval to return an empty result set."},{"key":"C","text":"The model refuses a legitimate query because surface features trigger an overly broad safety pattern."},{"key":"D","text":"A misconfigured load balancer routes requests to a deprecated API version."},{"key":"E","text":"The model generates a plausible-sounding answer unsupported by any retrieved document."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các cơ chế an toàn có thể từ chối yêu cầu hợp pháp khi trình phân loại xác định các tính năng liên quan đến danh mục bị hạn chế; Anthropic lưu ý rằng công việc vô hại có thể gây ra một số danh mục từ chối. LLM cũng có thể gây ảo giác, tạo ra nội dung không chính xác về mặt thực tế hoặc không nhất quán với ngữ cảnh được cung cấp, do đó, một câu trả lời hợp lý có thể thiếu sự hỗ trợ trong các tài liệu được truy xuất. Chứng chỉ hết hạn, hết thời gian truy xuất và định tuyến cân bằng tải không chính xác là các lỗi cấu hình hoặc cơ sở hạ tầng thông thường.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-3', 'ccar-p', 3, 'You are adding human review to a high-volume classification pipeline in which reviewing every output is impractical.  
  
Which sampling strategy best balances throughput and quality oversight?', '[{"key":"A","text":"No sampling, relying entirely on user complaints to reveal quality and safety problems after they affect users."},{"key":"B","text":"Risk-stratified sampling that reviews all low-confidence and high-impact outputs and a smaller random sample of high-confidence routine outputs."},{"key":"C","text":"Inverse sampling that reviews only high-confidence routine outputs and skips low-confidence and high-impact outputs."},{"key":"D","text":"Universal review of every output regardless of confidence or throughput impact."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc lấy mẫu phân tầng rủi ro hướng quá trình đánh giá của con người đến những kết quả đầu ra có khả năng xảy ra hoặc chi phí xảy ra lỗi cao nhất—các trường hợp có độ tin cậy thấp và tác động cao—trong khi việc lấy mẫu ngẫu nhiên các kết quả đầu ra có độ tin cậy cao thường quy giúp kiểm tra liên tục các vấn đề chất lượng tiềm ẩn. Điều này duy trì thông lượng có thể mở rộng mà không bỏ qua sự giám sát.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-4', 'ccar-p', 4, 'You operate an interactive assistant where per-turn latency is the primary performance constraint. Quality on routine turns is already acceptable.  
  
Which configuration change most directly improves latency without disproportionately harming quality?', '[{"key":"A","text":"Disable prompt caching entirely to ensure fresh context processing on every request, preventing stale prefix content from affecting latency-sensitive interactions."},{"key":"B","text":"Reduce retrieval depth to the top-k passages that historically cover the answer, and cache stable system-prompt content."},{"key":"C","text":"Increase retrieval depth to the corpus maximum to improve recall regardless of latency."},{"key":"D","text":"Switch every turn to the heaviest available model to maximize output quality, accepting that the increased model latency will worsen the per-turn SLO rather than improve it."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc chỉ truy xuất các đoạn văn top-k cung cấp thông tin cần thiết về mặt lịch sử sẽ làm giảm công việc truy xuất và ngữ cảnh nhanh chóng được xử lý trong mỗi lượt, trong khi vẫn duy trì chất lượng câu trả lời thông thường. Nội dung nhắc hệ thống ổn định được lưu vào bộ nhớ đệm tránh việc xử lý lại tiền tố không thay đổi. Quá trình truy xuất bổ sung tính toán và các chuyến đi khứ hồi, đồng thời duy trì ngữ cảnh được lưu trong bộ nhớ đệm giúp cải thiện việc sử dụng bộ nhớ đệm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-5', 'ccar-p', 5, 'You are evaluating patterns for a batch document-classification job with fixed stages: extract metadata, classify, summarize, and persist.  
  
Which pattern is the best fit, and why?', '[{"key":"A","text":"A workflow pattern, because agentic patterns do not support tool invocations and therefore cannot execute the persist step that writes results to the downstream store."},{"key":"B","text":"An agentic pattern, because the open-ended planning capability of agents produces more consistent structured outputs than a fixed workflow graph on classification tasks."},{"key":"C","text":"An agentic pattern, because agents are categorically more accurate than workflows and therefore always preferable regardless of step predictability."},{"key":"D","text":"A workflow pattern, because the steps are well-defined and predictable per-request token cost is preferred over flexibility."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mẫu quy trình công việc phù hợp với quy trình hàng loạt xác định có các giai đoạn được biết trước. Nó cung cấp khả năng điều phối lặp lại và chi phí mã thông báo theo yêu cầu có thể dự đoán được, trong khi tính linh hoạt của tác nhân và lập kế hoạch mở là không cần thiết đối với trình tự cố định này.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-6', 'ccar-p', 6, 'A pilot AI assistant for procurement specialists has an 89 percent first-response acceptance rate, but follow-up surveys show that specialists often override the assistant’s vendor recommendations after considering criteria the assistant did not assess. The pilot owner wants to launch the assistant unchanged because of the strong acceptance rate.  
  
Which two Discernment-competency observations should you raise **BEFORE** approving the launch? *(Select two.)*', '[{"key":"A","text":"The acceptance rate alone proves readiness for general production use."},{"key":"B","text":"The survey response rate may not be statistically representative of all specialists."},{"key":"C","text":"The unconsidered criteria represent a scope gap in the assistant’s input space."},{"key":"D","text":"Acceptance does not establish whether recommendations remain correct after specialist review."},{"key":"E","text":"The pilot duration was probably too short to demonstrate reliability across the full year."}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc ghi đè của các chuyên gia sau khi xem xét các tiêu chí lựa chọn nhà cung cấp bị bỏ qua cho thấy rằng không gian đầu vào được đánh giá của trợ lý là chưa đầy đủ. Tỷ lệ chấp nhận ban đầu cao đo lường mức độ chấp nhận sớm của người dùng, chứ không phải liệu các đề xuất có còn đúng sau khi có sự xem xét đầy đủ hơn của chuyên gia cần thiết để đưa ra quyết định mua sắm hay không.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-7', 'ccar-p', 7, 'You are a solution architect building a Claude-based assistant that has access to 60 internal tools across multiple business domains. Loading every tool definition with each request increases token usage and time to first response.  
  
Which design pattern best resolves this issue without reducing capability breadth?', '[{"key":"A","text":"Apply progressive tool discovery so a curated initial subset is exposed and additional tools are loaded on demand based on the task."},{"key":"B","text":"Use a separate model call to summarize all 60 tool definitions before each user turn."},{"key":"C","text":"Increase the maximum context length and load all 60 tool definitions on every request, accepting the higher token cost and latency as necessary for full capability."},{"key":"D","text":"Hard-code a fixed set of five tools per request to reduce token usage, regardless of whether those tools are relevant to the current task."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng khám phá công cụ lũy tiến giúp cung cấp danh mục công cụ đầy đủ trong khi trì hoãn các định nghĩa công cụ không cần thiết cho đến khi chúng phù hợp với nhiệm vụ. Điều này làm giảm mức sử dụng mã thông báo ngữ cảnh ban đầu và thời gian cho phản hồi đầu tiên mà không giới hạn trợ lý ở một tập hợp con công cụ cố định vĩnh viễn. Tài liệu Anthropic trì hoãn việc tải công cụ bằng tính năng tìm kiếm công cụ dành riêng cho các bộ công cụ lớn để chỉ những công cụ có liên quan mới được hiển thị cho một truy vấn.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-8', 'ccar-p', 8, 'You are investigating an MCP server that fails on its initial launch but works on later runs. System permission dialogs appeared during that first launch.  
  
Which response is the most appropriate?', '[{"key":"A","text":"Recognize the first-run permission grant as the cause, document the expected behavior in onboarding guidance, and confirm that subsequent runs succeed."},{"key":"B","text":"Reinstall the operating system to clear all permission state without first confirming whether the one-time permission grant caused the failure."},{"key":"C","text":"Disable operating-system permission dialogs entirely, accept the resulting security implications, and proceed without confirming whether the failure recurs."},{"key":"D","text":"Treat the first-run failure as a permanent fault, replace the MCP server, and do not verify whether subsequent runs succeed."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc cấp quyền cho hệ điều hành lần đầu tiên có thể tạm thời chặn quá trình khởi động cho đến khi người dùng cấp quyền truy cập cần thiết. Nếu các lần khởi chạy sau này thành công, phản hồi thích hợp là xác nhận hành vi đó và ghi lại bước ủy quyền dự kiến ​​để triển khai thay vì coi đó là lỗi vĩnh viễn.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-9', 'ccar-p', 9, 'An engineering organization is rolling out Claude Code across 200 developers. A team lead proposes that AI-generated pull requests bypass the standard code-review process for changes under 50 lines, because small changes are viewed as low risk and review capacity is limited.  
  
Which two Diligence-competency objections should you raise? Each correct answer presents part of the solution. (Select two.)', '[{"key":"A","text":"Removing review eliminates the verification mechanism required for AI-generated output across the workflow."},{"key":"B","text":"Code-review capacity should be expanded to handle every code change submitted across the team."},{"key":"C","text":"The threshold should be increased to 200 lines to capture more changes."},{"key":"D","text":"AI-generated pull requests should be rejected by default across the organization."},{"key":"E","text":"Line count is a poor proxy for the actual risk introduced by a code change."}]'::jsonb, ARRAY['A', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Những thay đổi do AI tạo ra vẫn yêu cầu xác minh trước khi tích hợp; Hướng dẫn bảo mật của Anthropic giao cho người dùng trách nhiệm xem xét mã được đề xuất và khuyên nên xem xét tất cả các thay đổi được đề xuất trước khi phê duyệt. Số dòng không thể hiện mức độ bảo mật, tính chính xác, ủy quyền, cấu hình, sự phụ thuộc hoặc tác động hoạt động của một thay đổi, do đó, nó không thể xác định một cách an toàn liệu việc xem xét có thể bị bỏ qua hay không. Đánh giá tự động có thể bổ sung nhưng không thay thế các biện pháp bảo mật và đánh giá mã thủ công hiện có.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-10', 'ccar-p', 10, 'You are choosing a model for a new production workload and must complete the upstream steps before empirically testing candidate models.  
  
Which two steps must be completed **BEFORE** testing a representative sample on a candidate model? Each correct answer is part of the solution. (Select two.)', '[{"key":"A","text":"Select the lightest model that consistently meets the quality bar across the sample."},{"key":"B","text":"Retest the model choice when a new model version becomes available."},{"key":"C","text":"Choose a candidate model based on the requirements profile and known capabilities."},{"key":"D","text":"Define the quality bar, latency tolerance, and expected volume for the workload."},{"key":"E","text":"Sign off the production rollout plan with the platform and security teams."}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bạn nên chọn một mô hình đề xuất dựa trên các yêu cầu đã xác định của khối lượng công việc—chất lượng đầu ra bắt buộc, khả năng chịu độ trễ và khối lượng dự kiến—cùng với các khả năng đã biết của mô hình. Đánh giá đại diện được thực hiện sau khi các tiêu chí đó và một ứng cử viên ban đầu được thiết lập. Lựa chọn mô hình nhẹ nhất đã vượt qua quá trình đánh giá, thử nghiệm lại các phiên bản mới và nhận được phê duyệt triển khai là các hoạt động tiếp theo.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-11', 'ccar-p', 11, 'You are developing a test strategy for a Claude-based pipeline that processes sensitive financial data.  
  
Which two testing types should be prioritized to address both safety under attack and correctness across components? (Select two.)', '[{"key":"A","text":"Adversarial tests using prompt-injection and malformed-input cases."},{"key":"B","text":"Regression tests against a stable reference set of previously known-good outputs."},{"key":"C","text":"Smoke tests that verify core paths after each deployment."},{"key":"D","text":"Integration tests that verify end-to-end pipeline behavior across all components."},{"key":"E","text":"Unit tests targeting only individual prompt-template rendering logic."}]'::jsonb, ARRAY['A', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Thử nghiệm đối nghịch xác thực khả năng chống lại các đầu vào thù địch như chèn nhanh và dữ liệu không đúng định dạng, giúp bảo vệ thông tin nhạy cảm và ngăn chặn hành vi không an toàn. Thử nghiệm tích hợp từ đầu đến cuối xác minh rằng các thành phần của quy trình tương tác và hoạt động chính xác như một hệ thống hoàn chỉnh; cùng với nhau, các thử nghiệm này bao gồm cả khả năng phục hồi sau cuộc tấn công và tính chính xác của nhiều thành phần.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-12', 'ccar-p', 12, 'You are evaluating model-selection claims used by a peer team.  
  
For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Heavier-reasoning models typically consume more of the rate limit and run more slowly than lighter models on the same input.","correctAnswer":"Yes"},{"id":"2","text":"A representative-sample evaluation on the target workload is the right basis for confirming a model selection.","correctAnswer":"Yes"},{"id":"3","text":"The most capable model is always the right choice regardless of the workload profile.","correctAnswer":"No"},{"id":"4","text":"Tiered routing can serve routine traffic with a lighter model while reserving a heavier model for traffic that needs its capability.","correctAnswer":"Yes"},{"id":"5","text":"Selecting a model based on which version was most recently announced is the right basis for production decisions.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No', '4:Yes', '5:No']::text[], '[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Nỗ lực lý luận cao hơn đánh đổi độ trễ tăng lên và việc sử dụng mã thông báo để lý luận sâu hơn, do đó, nó có thể tiêu tốn nhiều công suất giới hạn tốc độ hơn. Việc lựa chọn mô hình phải được xác nhận thông qua các đánh giá thể hiện khối lượng công việc sản xuất cũng như các yêu cầu về chất lượng, độ trễ và chi phí của nó. Mô hình có khả năng nhất không phải lúc nào cũng phù hợp: các mô hình nhỏ hơn có thể tốt hơn cho công việc thường ngày nhạy cảm với chi phí hoặc nhạy cảm với độ trễ. Định tuyến theo từng cấp hướng các yêu cầu đơn giản đến mô hình nhẹ hơn một cách thích hợp và dành mô hình mạnh hơn cho các yêu cầu phức tạp. Thông báo gần đây không chứng minh được sự phù hợp trong sản xuất; đo được hiệu suất trên khối lượng công việc mục tiêu.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-13', 'ccar-p', 13, 'You are assessing instrumentation in a multi-agent system.  
  
Which two findings represent valid observability gaps in the instrumentation? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Trace spans for each agent step are exported to the shared distributed-tracing backend."},{"key":"B","text":"Latency and token usage on every span are emitted to the central metrics pipeline."},{"key":"C","text":"Tool-call payloads and outcomes are recorded with redaction applied to known sensitive fields."},{"key":"D","text":"Model identity and version on each turn are not recorded with the turn artifacts."},{"key":"E","text":"Request-scoped correlation identifiers do not propagate across agent and tool calls."}]'::jsonb, ARRAY['D', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Danh tính và phiên bản của mô hình phải được ghi lại trong mỗi lượt để hành vi, độ trễ, mức sử dụng mã thông báo, lỗi và hồi quy có thể được quy cho cấu hình mô hình cụ thể. Giá trị nhận dạng tương quan trong phạm vi yêu cầu phải truyền qua các cuộc gọi tác nhân và công cụ để các khoảng thời gian và phép đo từ xa của chúng vẫn được kết nối trong một dấu vết phân tán. OpenTelemetry xác định các thuộc tính mô hình GenAI và giải thích rằng việc truyền bá ngữ cảnh cho phép tương quan giữa các ranh giới dịch vụ phân tán.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-14', 'ccar-p', 14, 'An engineer accidentally commits an API key to the repository by placing it in `.claude/settings.json`.  
  
Which configuration design principle was breached?', '[{"key":"A","text":"Project-scope configuration should always override user-scope configuration."},{"key":"B","text":"Managed configuration must be applied before project-scope configuration is read."},{"key":"C","text":"Credentials must be resolved at runtime from a secret store and never stored in version-controlled files."},{"key":"D","text":"MCP server definitions must reside in environment variables to prevent scope conflicts."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khóa API là thông tin xác thực và không được dành riêng cho các tệp cấu hình do phiên bản kiểm soát, nơi quyền truy cập và lịch sử kho lưu trữ có thể làm lộ chúng. Chúng phải được cung cấp một cách an toàn trong thời gian chạy, chẳng hạn như thông qua kho lưu trữ bí mật hoặc cơ chế dựa trên môi trường được bảo vệ. Tài liệu Anthropic sử dụng trình trợ giúp khóa để truy xuất khóa từ bí mật Vault cho thông tin xác thực động.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-15', 'ccar-p', 15, 'A document-analysis service handles legal filings that average 80,000 tokens each. Attorneys query every filing an average of 14 times during a case. The current architecture sends the entire filing with every query. The CFO has asked you to lower per-query costs while maintaining response quality. The security officer requires that filing content not be stored outside Fabrikam''s tenancy.  
  
Which optimization approach should you recommend?', '[{"key":"A","text":"Summarize each filing once at intake and run all subsequent queries against the summary."},{"key":"B","text":"Cache the filing as the prompt prefix for reuse across the 14 queries per case."},{"key":"C","text":"Index filings in a vector store and retrieve only the relevant passages per query."},{"key":"D","text":"Move the workload to a smaller Claude model to reduce the per-token cost paid."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bộ nhớ đệm tiền tố nhắc nhở sử dụng lại bản trình bày đã được xử lý của việc sắp xếp không thay đổi trong các truy vấn lặp lại, giảm chi phí và độ trễ của mã thông báo đầu vào trong khi vẫn duy trì bối cảnh tài liệu đầy đủ và chất lượng phản hồi. Azure OpenAI prompt caching được thiết kế cho các tiền tố dài giống hệt nhau, không làm thay đổi nội dung phản hồi và không chia sẻ bộ đệm nhắc giữa các đăng ký Azure.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-16', 'ccar-p', 16, 'You are creating an ethics-review checklist for AI-supported deployments.  
  
Which two checks should be included on the list? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Confirm that vendor licensing terms permit the planned production use of the model."},{"key":"B","text":"Verify that outputs do not rely on generalizations about people that the underlying data does not support."},{"key":"C","text":"Confirm that high-impact decisions retain human accountability rather than being attributed to the model."},{"key":"D","text":"Restrict ethics review to outputs that exceed a defined model-confidence threshold."},{"key":"E","text":"Confirm that latency and throughput targets are met across supported user populations."}]'::jsonb, ARRAY['B', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc triển khai AI có đạo đức đòi hỏi sự công bằng trong cách đại diện và đối xử với mọi người, vì vậy, kết quả đầu ra không được đưa ra những khái quát hóa không có căn cứ về con người. Nó cũng yêu cầu trách nhiệm giải trình rõ ràng của con người: mọi người và tổ chức triển khai vẫn chịu trách nhiệm về các quyết định mang tính hệ quả và phải duy trì sự giám sát phù hợp thay vì giao trách nhiệm cho một mô hình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-17', 'ccar-p', 17, 'You are classifying chunking strategies by the corpus type to which each is best suited.  
  
For each chunking strategy, select the applicable corpus type: “Long Structured Documents,” “Heterogeneous Short Records,” or “Code or Hierarchical Specs.”', '[]'::jsonb, ARRAY[]::text[], '[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ranh giới cấp chức năng và nhận biết cây duy trì thứ bậc logic của mã nguồn và thông số kỹ thuật. Các đoạn chồng chéo trên mỗi bản ghi và có kích thước cố định phù hợp với các bản ghi ngắn, có ý nghĩa độc lập. Ranh giới đoạn/mệnh đề ngữ nghĩa và hệ thống phân cấp phần tài liệu bảo toàn ngữ cảnh và cấu trúc của các tài liệu dài.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-18', 'ccar-p', 18, 'You are choosing a pattern for a compliance Q&A assistant that must respond to policy questions with citations from the authoritative internal source set. Latency, cost, and audit predictability are priorities.  
  
Which pattern is the best fit?', '[{"key":"A","text":"Augmented LLM with retrieval-augmented generation over the indexed authoritative corpus and citation rendering on each answer."},{"key":"B","text":"Multi-agent orchestration with a planner, researcher, and writer agent for every query."},{"key":"C","text":"A pure agent loop with open web-browsing tools to surface the most current policy information, without constraining retrieval to the authoritative internal corpus."},{"key":"D","text":"A static prompt with the entire policy corpus concatenated into every request."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính năng tạo tăng cường truy xuất truy xuất tài liệu có liên quan từ kho chính sách có thẩm quyền được lập chỉ mục cho mỗi phản hồi, cho phép trích dẫn dựa trên nguồn và khả năng kiểm tra có thể dự đoán được. Nó thường hiệu quả và được kiểm soát hơn so với phối hợp nhiều tác nhân, truy xuất web không hạn chế hoặc bao gồm toàn bộ kho tài liệu trong mỗi lời nhắc.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-20', 'ccar-p', 20, 'For each statement, select Yes if it reflects a sound architectural practice. Otherwise, select No.', '{"statements":[{"id":"1","text":"Authentication and authorization run before retrieval so retrieval can filter by identity.","correctAnswer":"Yes"},{"id":"2","text":"An asynchronous queue absorbs bursty traffic between intake and the model invocation layer.","correctAnswer":"Yes"},{"id":"3","text":"Tax computation is encoded directly in the system prompt rather than in code.","correctAnswer":"No"},{"id":"4","text":"Conversation logs include unredacted government identifiers to maximize signal for tuning.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No', '4:No']::text[], '[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc ủy ​​quyền trước khi truy xuất sẽ bật tính năng lọc quyền truy cập dựa trên danh tính. Xếp hàng lưu lượng truy cập liên tục một cách trơn tru và tách yêu cầu đầu vào khỏi quá trình xử lý mô hình không đồng bộ. Tính toán thuế yêu cầu logic ứng dụng có tính xác định, có thể kiểm tra được thay vì hành vi nhanh chóng. Giá trị nhận dạng của chính phủ là PII nhạy cảm, vì vậy nhật ký nên loại bỏ hoặc che giấu chúng và hạn chế sử dụng chúng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-21', 'ccar-p', 21, 'You are building an evaluation pipeline for a Claude-based deployment and must finish the specification steps before running the deployment against the dataset.  
  
Which two steps must be completed BEFORE running the deployment against the evaluation dataset? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Publish the aggregated metrics to a dashboard and gate releases on threshold checks."},{"key":"B","text":"Curate and label the evaluation dataset to match the defined slices."},{"key":"C","text":"Review failure cases with subject matter experts to refine the scoring rubric."},{"key":"D","text":"Define the metrics and slices the framework will report across representative, edge, and adversarial cases."},{"key":"E","text":"Score the deployment outputs against the reference labels and aggregate the metrics."}]'::jsonb, ARRAY['B', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc đánh giá yêu cầu các tiêu chí thành công có thể đo lường được, được xác định trước và một bộ đánh giá phản ánh việc phân bổ nhiệm vụ dự kiến, bao gồm cả các trường hợp đặc biệt. Số liệu và lát cắt thiết lập những gì sẽ được đo lường, trong khi các nhãn tham chiếu được quản lý cho phép tính điểm kết quả đầu ra. Việc tổng hợp điểm số, xem xét lỗi và xuất bản kết quả bảng thông tin diễn ra sau khi quá trình triển khai đã được chạy trên tập dữ liệu đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-22', 'ccar-p', 22, 'A managed agent deployment for claims triage has expanded from 6 tools to 34 tools over 18 months as product teams added capabilities. Triage accuracy has declined from 91 percent to 78 percent, and average tool-selection latency has risen by 2.3 seconds. A junior engineer has proposed placing a tool-router agent in front of the existing agent to filter the tool list for each request.  
  
Which two findings should you present to support capability decomposition before adding the router? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Tool descriptions overlap across multiple claim categories within the agent’s tool set."},{"key":"B","text":"Several tools have not been invoked across the most recent 90 days of traffic."},{"key":"C","text":"The 34 tools serve four distinct claim-workflow domains within the triage scope."},{"key":"D","text":"The router pattern is well documented across publicly available agent literature."},{"key":"E","text":"The proposed router introduces an additional model call on every incoming request."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bốn miền quy trình xác nhận quyền sở hữu riêng biệt cung cấp ranh giới khả năng rõ ràng để phân chia trách nhiệm phân loại rộng thành các tác nhân tập trung với bộ công cụ nhỏ hơn, dành riêng cho miền cụ thể. Việc thêm bộ định tuyến sẽ giới thiệu một lệnh gọi mô hình khác cho mọi yêu cầu, điều này kết hợp độ trễ thay vì giải quyết tình trạng quá tải cơ bản được tạo ra bởi một tác nhân duy nhất chọn trong số hàng chục công cụ. Hướng dẫn dành cho đại lý của Microsoft lưu ý rằng việc lựa chọn công cụ sẽ giảm xuống khi tổng đài viên tích lũy nhiều công cụ và mỗi lần gọi đại diện được ủy quyền sẽ tăng thêm độ trễ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-23', 'ccar-p', 23, 'An architect is assessing a Claude-based candidate-screening tool before deployment. A stakeholder claims that no bias evaluation is needed because the model was not trained on company data.  
  
Which two responses most accurately dispute this claim? (Select two.)', '[{"key":"A","text":"Transparency obligations are satisfied by disclosing that an AI system is in use, without further evaluation."},{"key":"B","text":"Fairness testing is required only when the training dataset is known to contain protected-class labels."},{"key":"C","text":"The model may carry demographic biases from pretraining that manifest in screening outcomes regardless of fine-tuning."},{"key":"D","text":"The system should be evaluated on outcome-disparity metrics across protected groups before deployment."},{"key":"E","text":"Bias evaluation is unnecessary when the model provider has published a responsible-use policy."}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một mô hình có thể giữ lại những thành kiến ​​về nhân khẩu học từ quá trình đào tạo trước trên diện rộng ngay cả khi mô hình đó chưa được đào tạo về dữ liệu của tổ chức. Đối với trường hợp sử dụng sàng lọc việc làm, việc đánh giá tính công bằng sẽ đo lường xem liệu kết quả có khác nhau giữa các nhóm được bảo vệ hay không trước khi triển khai. Hướng dẫn của NIST yêu cầu đánh giá tính công bằng và thiên vị, đồng thời sử dụng các số liệu theo ngữ cảnh cụ thể để đánh giá hiệu suất và tác hại giữa các nhóm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-24', 'ccar-p', 24, 'You are ordering decomposed components in an invoice-processing pipeline.  
  
For every decomposed component, choose the execution layer to which it belongs: “Pre-Processing”, “Model Stage”, or “Post-Processing”.', '[]'::jsonb, ARRAY[]::text[], '[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Quy trình xử lý trước chuẩn bị dữ liệu đầu vào hóa đơn để suy luận, bao gồm OCR và biên tập lại văn bản nhạy cảm trước khi gọi mô hình. Giai đoạn mô hình thực hiện phân loại Claude và trích xuất dữ liệu có cấu trúc. Quá trình xử lý hậu kỳ xác thực kết quả được trích xuất dựa trên lược đồ của nó và chỉ lưu giữ các bản ghi đã được xác thực vào hệ thống bản ghi.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-25', 'ccar-p', 25, 'You are creating a prompt for a ticket-triage classifier with thirty clearly defined categories and clear descriptions of each category in the prompt.  
  
Which technique is the most appropriate starting point?', '[{"key":"A","text":"A chain-of-thought prompt for a routing decision that does not require multi-step reasoning."},{"key":"B","text":"A zero-shot prompt that specifies the categories with their descriptions and the required output format."},{"key":"C","text":"A prompt that demands the model invent new categories when the supplied ones do not fit."},{"key":"D","text":"A prompt with no category descriptions, expecting the model to infer the category set."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Để phân loại theo phân loại cố định, lời nhắc không bắn phải nêu rõ các danh mục được phép, xác định chúng rõ ràng và chỉ định định dạng phản hồi bắt buộc. Điều này tạo cơ sở cho mô hình trong bộ nhãn dự kiến ​​và tạo ra các quyết định định tuyến nhất quán, máy có thể đọc được.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-26', 'ccar-p', 26, 'You are evaluating a Claude-based system whose primary risk is undetected quality drift in safety-relevant outputs after a model-version upgrade.  
  
Which assessment activity most directly mitigates this risk?', '[{"key":"A","text":"Disable adversarial evaluation entirely during model-version upgrade cycles to reduce evaluation cost, accepting that safety drift will go undetected until it appears in production."},{"key":"B","text":"Rotate adversarial inputs randomly so no two upgrades are scored on the same set."},{"key":"C","text":"Skip evaluation on each model-version upgrade and rely on user-submitted complaints to surface safety drift after the upgraded model has already served production traffic."},{"key":"D","text":"Maintain an adversarial evaluation set with version-attributed scoring so each upgrade is measured against the same set before promotion."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một bộ đánh giá đối thủ ổn định, được phiên bản mô hình cho điểm và ghi lại trước khi được thăng hạng, cung cấp một so sánh hồi quy có kiểm soát có thể phát hiện sự sai lệch về chất lượng an toàn do bản nâng cấp gây ra. Anthropic khuyên bạn nên thử nghiệm kỹ lưỡng các ứng dụng có kiểu máy mới hơn trước khi chuyển sang chúng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-27', 'ccar-p', 27, 'You are conducting a risk assessment for a planned Claude-based deployment and must finish the inventory steps before evaluating threats against assets.  
  
Which two actions must be completed **before** assessing threats against assets to estimate likelihood and impact? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Document the assessment outcome with risks, mitigations, residual risk, and acceptance owners."},{"key":"B","text":"Recommend mitigations and residual-risk acceptance for the risks that remain after analysis."},{"key":"C","text":"Identify the assets that the deployment touches, along with the sensitivity of each asset."},{"key":"D","text":"Recommend mitigations and residual-risk acceptance for risks that remain."},{"key":"E","text":"Enumerate the threat actors and attack vectors relevant to the deployment."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chỉ có thể ước tính khả năng và tác động của rủi ro sau khi xác định các tài sản bị ảnh hưởng bởi việc triển khai và mức độ nhạy cảm của chúng, sau đó xác định các tác nhân đe dọa có liên quan và các phương hướng tấn công. Độ nhạy của tài sản xác định hậu quả tiềm ẩn của sự xâm phạm, trong khi các tác nhân và vectơ đe dọa xác định các kịch bản đe dọa hợp lý. Các khuyến nghị giảm thiểu, chấp nhận rủi ro tồn dư và tài liệu về kết quả sẽ được đưa ra sau quá trình phân tích.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-28', 'ccar-p', 28, 'Following an update to a prompt template, several test cases that had previously passed now generate unexpected outputs.  
  
Which test type is specifically intended to identify this kind of failure?', '[{"key":"A","text":"Integration tests that validate cross-component pipeline behavior."},{"key":"B","text":"Adversarial tests that probe for prompt-injection vulnerabilities."},{"key":"C","text":"Regression tests scored against a stable reference set of known-good behavior."},{"key":"D","text":"Smoke tests that confirm high-level system availability after the change."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Kiểm tra hồi quy phát hiện những thay đổi ngoài ý muốn trong hành vi đúng trước đây bằng cách đánh giá hệ thống đã cập nhật dựa trên các trường hợp tham chiếu ổn định, nổi tiếng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-29', 'ccar-p', 29, 'A platform team runs a self-hosted, multi-agent system on Kubernetes that coordinates seven specialized agents for invoice processing. The team uses approximately 40 percent of its engineering capacity for infrastructure maintenance, message-bus reliability, and agent-state recovery. The CFO has asked for an evaluation of a move to managed agent infrastructure to recover engineering capacity. The security officer requires all customer financial data to stay within an approved network boundary.  
  
Which factor should carry the greatest weight in your recommendation?', '[{"key":"A","text":"Whether the current seven agents map cleanly to the patterns supported by managed agents."},{"key":"B","text":"Whether managed agents reduce per-invoice token costs across the existing processing volume."},{"key":"C","text":"Whether managed agents support the current bus topology used by the platform team."},{"key":"D","text":"Whether managed agent data handling satisfies the network boundary required by security."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc tuân thủ ranh giới mạng đã được phê duyệt đối với dữ liệu tài chính của khách hàng là một hạn chế bảo mật bắt buộc. Các lợi ích vận hành như giảm nỗ lực bảo trì, giảm chi phí mã thông báo hoặc khả năng tương thích về kiến ​​trúc không thể biện minh cho việc áp dụng một dịch vụ được quản lý không đáp ứng được yêu cầu xử lý dữ liệu đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-30', 'ccar-p', 30, 'You are determining where human review must remain in a proposed automated pipeline.  
  
Which placement represents sound human-in-the-loop design?', '[{"key":"A","text":"Place a human reviewer only after the irreversible action has already executed, making the review a post-hoc audit rather than a meaningful pre-action check or approval gate."},{"key":"B","text":"Place a human reviewer between the model’s output and any high-impact, irreversible action, with explicit criteria for what the reviewer must check before approval."},{"key":"C","text":"Place a human reviewer in the loop for a randomly selected sample of requests, without defining criteria for what the reviewer should check or which output categories require mandatory review."},{"key":"D","text":"Remove all human review steps from the pipeline to maximize throughput, accepting that high-impact and irreversible actions will be taken without any human approval or oversight."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc đánh giá của con người phải diễn ra sau khi mô hình tạo ra kết quả đầu ra nhưng trước bất kỳ hành động có tác động lớn, không thể đảo ngược nào và người đánh giá cần có tiêu chí phê duyệt rõ ràng. Điều này duy trì sự giám sát có ý nghĩa và cho phép can thiệp trước khi xảy ra tổn hại hoặc hậu quả không thể khắc phục được.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-31', 'ccar-p', 31, 'A Claude architect at a health services organization is establishing evaluation metrics for a clinical-summary pipeline. The pipeline must stay within a per-query cost ceiling and must never expose patient data to unauthorized roles.  
  
Which two metrics directly address these requirements? (Select two.)', '[{"key":"A","text":"BLEU score computed against a human-annotated reference summary set"},{"key":"B","text":"Role-based access-control enforcement rate measured on a red-team dataset"},{"key":"C","text":"Throughput measured as successful requests processed per minute"},{"key":"D","text":"Per-query token cost measured against the defined cost ceiling"},{"key":"E","text":"Response latency at the 95th percentile across a one-week sample window"}]'::jsonb, ARRAY['B', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chi phí mã thông báo cho mỗi truy vấn trực tiếp kiểm tra việc tuân thủ mức trần chi phí đã xác định. Tỷ lệ thực thi RBAC được đo trên các trường hợp thử nghiệm đối nghịch trực tiếp kiểm tra xem các biện pháp kiểm soát ủy quyền có ngăn chặn các vai trò trái phép truy cập dữ liệu bệnh nhân hay không. Chi phí API Claude được điều chỉnh bởi việc sử dụng mã thông báo và RBAC chỉ định quyền cho người dùng hoặc nhóm được ủy quyền.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-32', 'ccar-p', 32, 'A Claude-based research assistant starts generating responses that confidently contradict its retrieved source documents, even though the retrieval pipeline has not changed.  
  
Which two diagnostic actions most directly identify the root cause of this behavior? (Select two.)', '[{"key":"A","text":"Increase the context-window size to allow more retrieved chunks per query."},{"key":"B","text":"Switch the retrieval index to a denser embedding model to improve chunk-relevance scores."},{"key":"C","text":"Determine whether the failure reproduces on the previous model version to test for a model mismatch."},{"key":"D","text":"Reduce the temperature setting to lower response variance across all query types."},{"key":"E","text":"Inspect the system-prompt grounding instructions to determine whether citation constraints remain intact."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc tái tạo hành vi bằng phiên bản mô hình trước đó có thể tách biệt sự không khớp giữa phiên bản mô hình hoặc định tuyến mô hình khi quá trình truy xuất không thay đổi. Việc xem lại lời nhắc của hệ thống sẽ xác minh rằng các hướng dẫn yêu cầu câu trả lời phải căn cứ vào nội dung được truy xuất và bị ràng buộc bởi các trích dẫn chưa bị xóa hoặc bị suy yếu. Các bản cập nhật mô hình Claude có thể thay đổi hành vi tuân theo hướng dẫn, vì vậy Anthropic khuyên bạn nên thử nghiệm các ứng dụng khi thay đổi mô hình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-33', 'ccar-p', 33, 'You are assessing prompting claims in a peer’s design document.  
  
For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Zero-shot is appropriate as a starting point for closed-set classification when categories and descriptions are provided in the prompt.","correctAnswer":"Yes"},{"id":"2","text":"Adding a few-shot example set with exact field names anchors output formatting on extraction tasks.","correctAnswer":"Yes"},{"id":"3","text":"Chain-of-thought should be the default on every task regardless of complexity.","correctAnswer":"No"},{"id":"4","text":"Leading-question framing is best mitigated by asking for an even-handed comparison with stated criteria.","correctAnswer":"Yes"},{"id":"5","text":"Behavioral differences across model versions can be ignored once a prompt has been validated on one version.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No', '4:Yes', '5:No']::text[], '[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc phân loại không cần thực hiện có hiệu quả khi nhãn và định nghĩa của chúng được chỉ định rõ ràng. Các ví dụ Few-shot với các trường lược đồ chính xác củng cố định dạng trích xuất mong muốn. Chuỗi suy nghĩ chỉ nên được áp dụng khi hữu ích cho nhiệm vụ chứ không phải như một mặc định chung. So sánh trung lập với tiêu chí rõ ràng phản ánh khung dẫn đầu. Hoạt động của mô hình có thể khác nhau tùy theo phiên bản, vì vậy, lời nhắc yêu cầu xác thực sau khi thay đổi phiên bản.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-34', 'ccar-p', 34, 'You are designing a content-moderation classifier that handles high volumes of user-generated comments under a tight per-message latency budget and uses well-defined classification labels.  
  
Which model selection best fits this workload?', '[{"key":"A","text":"Opus, because every moderation decision requires maximum reasoning depth regardless of classification complexity."},{"key":"B","text":"Haiku, because its latency and cost profile align with high-volume classification workloads that require limited reasoning depth."},{"key":"C","text":"Sonnet, because larger general-purpose models are preferred even when workload latency requirements are strict."},{"key":"D","text":"Sonnet with extended thinking enabled, because deeper reasoning should be applied to every moderation request to improve edge-case handling."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Haiku được thiết kế cho công việc có khối lượng lớn, nhạy cảm với độ trễ như phân loại, trích xuất và định tuyến. Cấu hình nhanh hơn, chi phí thấp hơn của nó phù hợp với các nhãn kiểm duyệt được xác định rõ ràng và không yêu cầu lý luận sâu sắc, trong khi các mô hình lớn hơn hoặc tư duy bổ sung sẽ làm tăng độ trễ mà không cần thiết cho khối lượng công việc này.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-35', 'ccar-p', 35, 'A revenue-projection assistant is 38 percent above its monthly cost target. Profiling identifies three contributors: a 6,000-token policy preamble repeated on every call (45 percent of cost), retrieval of historical sales chunks averaging 3,000 tokens per call (30 percent), and inference on a flagship-tier model (25 percent). Stakeholders require that projection accuracy remain unchanged.  
  
Which two optimizations should you sequence first to reduce cost without affecting accuracy? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Reduce the number of historical sales chunks retrieved across each query run."},{"key":"B","text":"Truncate the policy preamble to remove non-essential clauses from the prompt."},{"key":"C","text":"Enable prompt caching on the static policy preamble across the recurring calls."},{"key":"D","text":"Switch the workload to a smaller, faster Claude model tier across all queries."},{"key":"E","text":"Cache common retrieved sales chunks accessed across many of the daily queries."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Prompt caching cho phép các yêu cầu định kỳ sử dụng lại tiền tố ổn định giống hệt nhau, chẳng hạn như phần mở đầu chính sách hoặc ngữ cảnh được sử dụng lại thường xuyên, với chi phí xử lý đầu vào thấp hơn nhiều trong khi vẫn giữ được nội dung chính xác được cung cấp cho mô hình. Do đó, việc lưu chính sách tĩnh vào bộ nhớ đệm và các phần lịch sử-bán hàng thường được sử dụng lại sẽ giảm hai chi phí liên quan đến dấu nhắc có thể lặp lại lớn nhất mà không thay đổi đầu vào dự báo hoặc cấp mô hình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-36', 'ccar-p', 36, 'You are assessing retrieval-strategy claims used by a peer team.  
  
For each claim, select **Yes** when it is generally accurate; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Dense vector retrieval is well suited to recovering paraphrased intent against unstructured text.","correctAnswer":"Yes"},{"id":"2","text":"Sparse term-matching retrieval recovers exact terms (such as identifiers and rare tokens) more reliably than dense alone.","correctAnswer":"Yes"},{"id":"3","text":"Structured query retrieval is the right fit for filter-and-aggregate workloads against a relational store with schema and indexes.","correctAnswer":"Yes"},{"id":"4","text":"Hybrid retrieval is identical to dense-only retrieval and shares the same recall characteristics.","correctAnswer":"No"},{"id":"5","text":"Random sampling of a data store is a sound retrieval strategy for production Q&A.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes', '4:No', '5:No']::text[], '[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }vector search dày đặc nắm bắt được sự tương đồng về ngữ nghĩa, hỗ trợ truy xuất diễn giải. Truy xuất từ ​​vựng thưa thớt là mạnh nhất đối với các chuỗi chính xác, số nhận dạng và thuật ngữ hiếm. Các truy vấn và chỉ mục quan hệ hỗ trợ việc lọc và tổng hợp xác định. Truy xuất kết hợp kết hợp các cách tiếp cận thưa thớt và dày đặc, mang lại cho nó hành vi truy xuất và thu hồi khác với tìm kiếm chỉ dày đặc. Lấy mẫu ngẫu nhiên cung cấp sự đảm bảo về mức độ liên quan của no, do đó, nó không phù hợp để truy xuất câu trả lời cho câu hỏi sản xuất.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-37', 'ccar-p', 37, 'An operations engineer says that a Claude-based pipeline started returning malformed JSON responses after a scheduled maintenance window, resulting in downstream processing failures.  
  
Which two investigative actions most directly isolate the root cause? (Select two.)', '[{"key":"A","text":"Clear the prompt cache and resubmit all pending requests to eliminate stale cached prefixes."},{"key":"B","text":"Compare the current system prompt and output schema configuration against the last known good version from before the maintenance window."},{"key":"C","text":"Switch to a different Claude model tier to rule out provider-side changes as a contributing factor."},{"key":"D","text":"Increase the max_tokens limit to determine whether output truncation is causing incomplete JSON structures."},{"key":"E","text":"Replay a set of premaintenance requests against the current configuration and inspect the raw model output before downstream parsing."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc so sánh cấu hình có thể cho biết liệu việc bảo trì có làm thay đổi các hướng dẫn hệ thống hoặc các yêu cầu về lược đồ đầu ra chi phối định dạng JSON hay không. Việc phát lại các đầu vào bảo trì tốt đã biết dựa trên cấu hình hiện tại và kiểm tra phản hồi thô của Claude sẽ tách đầu ra của mô hình không đúng định dạng khỏi các lỗi do quá trình phân tích cú pháp xuôi dòng gây ra. Các hướng dẫn và ràng buộc định dạng đầu ra rõ ràng rất quan trọng để có hành vi định dạng mô hình nhất quán.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-38', 'ccar-p', 38, 'You are a solution architect evaluating candidate use cases for a Claude-based program.  
  
For each scenario, select Yes if Claude is appropriate as the primary solution at the architectural level. Otherwise, select No.', '[]'::jsonb, ARRAY[]::text[], '[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude rất phù hợp với việc soạn thảo báo cáo từ văn bản bán cấu trúc, xem xét các tài liệu dài, trích xuất các mệnh đề có cấu trúc, xác định các sai lệch, phân loại phiếu hỗ trợ và giải thích các phân loại. Một quyết định gian lận phát trực tuyến dưới 50 ms cần tính điểm chuyên biệt có độ trễ thấp và có thể dự đoán được thay vì LLM làm giải pháp chính. Việc truy xuất ngữ nghĩa trên hàng triệu tài liệu yêu cầu chỉ mục vectơ hoặc hệ thống truy xuất tương đương; Claude có thể sử dụng các kết quả được truy xuất nhưng không thay thế chỉ mục đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-39', 'ccar-p', 39, 'You are assembling factors that should guide the selection among Model Context Protocol (MCP), direct API integration, and agent-to-agent handoff.  
  
Which two factors should be included on the list? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Whether the vendor publishes detailed reference documentation for each candidate protocol."},{"key":"B","text":"Whether the team has prior implementation experience with any of the candidate protocols."},{"key":"C","text":"Whether the underlying transport supports encryption in transit between the integrated services."},{"key":"D","text":"Whether the integration must be portable across multiple AI clients in the ecosystem."},{"key":"E","text":"Whether the interaction is stateless and latency-sensitive or stateful and longer-running."}]'::jsonb, ARRAY['D', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tính di động trên nhiều máy khách AI ưu tiên MCP vì nó cung cấp giao thức máy khách-máy chủ được tiêu chuẩn hóa mà các máy chủ tương thích có thể sử dụng. Vòng đời tương tác cũng xác định phương pháp tích hợp: API trực tiếp phù hợp với các hoạt động phản hồi yêu cầu đơn giản, có độ trễ thấp, trong khi chuyển giao tác nhân chuyển giao quyền kiểm soát và duy trì bối cảnh cho công việc có trạng thái, chạy lâu hơn giữa các tác nhân chuyên biệt.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-40', 'ccar-p', 40, 'You are choosing a protocol for one low-latency, stateless tool call from a Claude-based assistant to an internal pricing service that already offers a stable HTTP API.  
  
Which integration mechanism is most appropriate?', '[{"key":"A","text":"A direct API call to the existing endpoint with the appropriate scoped credentials."},{"key":"B","text":"A long-lived stateful session protocol for a stateless single-call interaction."},{"key":"C","text":"A bespoke streaming protocol layered over an unrelated asynchronous message bus."},{"key":"D","text":"An agent-to-agent handoff that introduces another Claude-based agent in front of the pricing service."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cuộc gọi trực tiếp đến điểm cuối HTTP hiện có là cách tích hợp đơn giản nhất và có độ trễ thấp nhất cho một hoạt động không trạng thái. Thông tin xác thực có phạm vi thực thi quyền truy cập có đặc quyền tối thiểu, trong khi giao thức phiên liên tục, lớp phát trực tuyến tùy chỉnh hoặc tác nhân can thiệp sẽ tăng thêm độ phức tạp và độ trễ mà không đáp ứng yêu cầu đã nêu. Claude hỗ trợ tool use phía máy khách, trong đó ứng dụng thực hiện lệnh gọi công cụ và trả về kết quả của nó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-41', 'ccar-p', 41, 'You are assessing an integration specification for security weaknesses.  
  
Which two findings represent valid security gaps in the specification? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Tool calls execute server-side under a least-privilege service principal scoped to the requested action."},{"key":"B","text":"Service credentials are placed in the prompt context, where they can leak into logs and traces."},{"key":"C","text":"Role-based access control is enforced only at the response-rendering layer after the model accesses restricted data."},{"key":"D","text":"Per-user OAuth tokens are exchanged with scope-restricted permissions and refreshed within the active session."},{"key":"E","text":"Tool inputs and outputs are encrypted in transit using transport-layer security between services."}]'::jsonb, ARRAY['B', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Không được đưa thông tin đăng nhập dịch vụ vào ngữ cảnh kịp thời vì chúng có thể bị lộ thông qua quá trình ghi nhật ký và theo dõi. Việc ủy ​​quyền phải được thực thi trước khi một mô hình hoặc công cụ truy cập dữ liệu bị hạn chế; RBAC chỉ dành cho lớp phản hồi cho phép truy cập trái phép xảy ra trước khi quá trình hiển thị bị chặn.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-42', 'ccar-p', 42, 'The platform team at Trenova Systems, Inc. must lower per-query cost and p95 latency for a high-volume Claude pipeline without reducing output quality for the core use case.  
  
Which two optimizations directly address both cost and latency at the same time? (Select two.)', '[{"key":"A","text":"Enable prompt caching on the static system-prompt prefix to reduce billable input tokens on repeated calls."},{"key":"B","text":"Route straightforward query types to a smaller, faster Claude model and reserve the full model for complex cases."},{"key":"C","text":"Increase max_tokens to reduce the frequency of truncated responses requiring follow-up calls."},{"key":"D","text":"Add a retrieval step that fetches the full source corpus into the context window before generation."},{"key":"E","text":"Expand the system prompt to include additional few-shot examples on every request."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Prompt caching cho phép các cuộc gọi lặp lại sử dụng lại tiền tố tĩnh của lời nhắc hệ thống, do đó dữ liệu đầu vào được lưu vào bộ nhớ đệm sẽ được tính phí ở mức thấp hơn và tránh việc xử lý lại tiền tố đó. Việc định tuyến các yêu cầu đơn giản đến mô hình nhỏ hơn, nhanh hơn sẽ giảm chi phí suy luận và thời gian phản hồi, đồng thời dành mô hình lớn hơn cho các yêu cầu phức tạp để duy trì chất lượng ở những nơi quan trọng. Việc tăng giới hạn đầu ra, truy xuất toàn bộ kho văn bản hoặc mở rộng mọi lời nhắc sẽ thêm quá trình xử lý hoặc mã thông báo thay vì trực tiếp giảm cả hai số liệu.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-43', 'ccar-p', 43, 'You are implementing monitoring for a Claude-based deployment and must complete the specification steps before instrumenting the deployment.  
  
Which two steps must be completed **BEFORE** instrumenting the deployment to emit metrics and traces? Each correct answer is part of the solution. *(Select two.)*', '[{"key":"A","text":"Define the metrics and the slices the deployment will monitor across normal and adversarial traffic."},{"key":"B","text":"Tune the alert thresholds based on observed normal-state distributions to reduce false positives."},{"key":"C","text":"Define the service-level objectives (SLOs) and the error budgets the deployment will be held to."},{"key":"D","text":"Build the dashboards that surface metrics across slices at the cadence the team operates on."},{"key":"E","text":"Document the dashboards, alerts, and runbooks for the on-call rotation that will respond."}]'::jsonb, ARRAY['A', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Thiết bị đo phải được thiết kế để đưa ra các số liệu và thứ nguyên lưu lượng truy cập cần thiết để phân biệt hành vi bình thường và hành vi đối nghịch. Các phép đo đó hỗ trợ các chỉ báo mức dịch vụ được sử dụng để thiết lập SLO; đến lượt SLO xác định mức lỗi của nó. Ngưỡng cảnh báo yêu cầu phân phối cơ sở được quan sát, trong khi bảng thông tin và tài liệu theo yêu cầu sẽ sử dụng kết quả đo từ xa sau khi thiết kế giám sát được thiết lập.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-44', 'ccar-p', 44, 'During discovery, you are differentiating functional requirements from non-functional requirements.  
  
Which item is a non-functional requirement?', '[{"key":"A","text":"The system must extract a defined set of specific fields from invoice attachments and populate a downstream data record."},{"key":"B","text":"The system must produce a draft response that a human reviewer can edit before sending."},{"key":"C","text":"The system must classify inbound tickets into a defined set of categories."},{"key":"D","text":"The system must respond at p95 latency under 800 milliseconds at the expected request volume."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mục tiêu độ trễ p95 dưới 800 mili giây với khối lượng yêu cầu dự kiến ​​là một hạn chế về hiệu suất có thể đo lường được nhằm xác định mức độ hệ thống phải hoạt động tốt như thế nào. Trích xuất trường, tạo bản nháp có thể chỉnh sửa của con người và phân loại vé chỉ định các chức năng mà hệ thống phải thực hiện. Microsoft xác định các yêu cầu chức năng là những gì ứng dụng thực hiện và các yêu cầu phi chức năng là mức độ hoạt động của ứng dụng, bao gồm cả độ trễ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-45', 'ccar-p', 45, 'A healthcare organization is assessing two Claude-powered AI architectures for a clinical-documentation assistant. Architecture X delivers higher output-quality scores, but costs $0.18 per documentation session and averages 4.2 seconds per response. Architecture Y scores slightly lower on quality metrics, but costs $0.09 per session and averages 2.1 seconds per response. The stated SLA requires responses in under 3 seconds, and the projected annual volume is 2 million documentation sessions.  
  
Which evaluation approach properly applies business-value pillar analysis to this decision?', '[{"key":"A","text":"Select Architecture Y based solely on the 50% cost reduction, since solution cost is the most important value pillar in healthcare budget-constrained environments."},{"key":"B","text":"Select Architecture X because the higher quality scores justify the cost premium, and any SLA gap can be addressed through infrastructure optimization after deployment."},{"key":"C","text":"Eliminate Architecture X on SLA grounds, then evaluate Architecture Y against the efficiency and solution cost pillars by calculating annual cost difference and assessing whether the quality delta materially impacts clinical workflow productivity."},{"key":"D","text":"Recommend a hybrid approach using Architecture X for complex cases and Architecture Y for routine cases, without additional analysis, since this preserves quality where it matters most."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }SLA độ trễ bắt buộc là một hạn chế về tính khả thi: Mức trung bình 4,2 giây của Kiến trúc X không đáp ứng yêu cầu dưới 3 giây, trong khi mức trung bình 2,1 giây của Kiến trúc Y thì đáp ứng được. Với 2 triệu phiên, mức chi tiêu hàng năm là 360.000 USD cho X và 180.000 USD cho Y, mang lại chênh lệch 180.000 USD hàng năm. Quyết định còn lại là liệu việc giảm chất lượng của Y có làm giảm đáng kể năng suất của quy trình làm việc lâm sàng đủ để vượt trội hơn so với hiệu suất tuân thủ và chi phí thấp hơn hay không. Tương tự, hướng dẫn của AWS yêu cầu loại bỏ các tùy chọn không đáp ứng yêu cầu về khối lượng công việc, sau đó chọn và thử nghiệm các tùy chọn đáp ứng các yêu cầu về độ trễ, thông lượng và chất lượng phản hồi trong khi đánh giá sự cân bằng giữa chi phí và hiệu suất của chúng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-46', 'ccar-p', 46, 'You are troubleshooting a Claude Code session in which its subagent uses 50,000 context tokens before the engineer types even a single message.  
  
Which root cause is most likely?', '[{"key":"A","text":"The developer''s keyboard layout or input-method configuration is the cause of the elevated context consumption, introducing extra tokens before the engineer types any message."},{"key":"B","text":"Many MCP servers are configured, each contributing tool definitions to the context budget; Tool Search is not enabled, so all definitions load upfront."},{"key":"C","text":"The model has internal personal preferences or default behaviors that silently consume large portions of context budget before any user message is processed, independent of tool configuration."},{"key":"D","text":"The font rendering or display-scaling settings of the IDE are converting visual output into additional context tokens, causing the high pre-session context consumption."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi Tìm kiếm công cụ bị tắt, Claude Code sẽ tải tất cả các định nghĩa công cụ MCP đã định cấu hình vào cửa sổ ngữ cảnh khi khởi động. Do đó, một bộ sưu tập lớn các máy chủ MCP có thể tiêu thụ hàng chục nghìn mã thông báo trước khi bất kỳ thông báo kỹ sư nào được nhập.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-47', 'ccar-p', 47, 'You are assisting an engineer whose newly added MCP server is not appearing in their Claude Code session.  
  
Which diagnostic step should be attempted first?', '[{"key":"A","text":"Disable every MCP server in the configuration to isolate the issue, removing all tool access rather than confirming whether the new server is registered."},{"key":"B","text":"Switch the team to a different Claude product family unrelated to the existing workflow, abandoning the current configuration rather than diagnosing the registration issue."},{"key":"C","text":"Verify the MCP server is registered using the listing command, then reconnect the session if needed, since configuration changes typically require a restart to take effect."},{"key":"D","text":"Reinstall the developer’s operating system from scratch, discarding all local configuration and tool state before attempting any targeted diagnostic steps."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }`claude mcp list` xác nhận xem máy chủ MCP có được định cấu hình hay không và báo cáo trạng thái hoạt động của nó, chẳng hạn như đã kết nối, yêu cầu xác thực hoặc không kết nối được. Điều này xác định xem vấn đề là do đăng ký hay kết nối phiên trước khi thực hiện hành động gây rối; kết nối lại phiên có thể làm mới trạng thái MCP đang hoạt động khi cần thiết.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-48', 'ccar-p', 48, 'You are identifying characteristics of strong architectural-decision communication.  
  
Which two characteristics should be included on the list? Each correct answer represents a complete solution. (Select two.)', '[{"key":"A","text":"Ownership and review cadence for revisiting the decision when conditions or assumptions change."},{"key":"B","text":"Distribution to a standing review forum with mandatory attendance from senior engineering leaders."},{"key":"C","text":"Omission of rejected alternatives to keep the decision document focused and concise for readers."},{"key":"D","text":"Alternatives considered along with the criteria that were used to evaluate each alternative."},{"key":"E","text":"Use of a consistent template across the team to standardize the visual presentation of decisions."}]'::jsonb, ARRAY['A', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hồ sơ quyết định mang tính kiến ​​trúc vững chắc truyền đạt cả trách nhiệm giải trình và lý do căn bản. Quyền sở hữu với nhịp độ đánh giá giúp duy trì quyết định khi các giả định hoặc điều kiện của nó thay đổi, đồng thời ghi lại các lựa chọn thay thế được xem xét và tiêu chí đánh giá của chúng giúp cho sự đánh đổi và biện minh có thể hiểu được đối với các bên liên quan hiện tại và tương lai. Hướng dẫn ADR chính thức yêu cầu quyền sở hữu và ghi lại bối cảnh, bao gồm các giải pháp khả thi được xem xét và hậu quả của quyết định.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-49', 'ccar-p', 49, 'A Claude architect is designing a HIPAA-compliant pipeline that handles patient records.  
  
Which two design decisions directly support HIPAA compliance requirements? (Select two.)', '[{"key":"A","text":"Setting max_tokens to a low value to minimize the volume of text generated per request."},{"key":"B","text":"Selecting the highest-capability Claude model to maximize diagnostic accuracy."},{"key":"C","text":"Enforcing role-based access controls so that PHI is retrievable only by authorized personnel."},{"key":"D","text":"Ensuring patient data is never included in training feedback loops sent to the model provider without a BAA in place."},{"key":"E","text":"Using streaming responses to reduce perceived latency for clinical users."}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các biện pháp bảo vệ của HIPAA bao gồm các biện pháp kiểm soát quyền truy cập nhằm hạn chế thông tin sức khỏe được bảo vệ bằng điện tử (ePHI) đối với các thành viên lực lượng lao động được ủy quyền. Khi nhà cung cấp dịch vụ nhận PHI như một phần của việc thực hiện dịch vụ, thỏa thuận liên kết kinh doanh (BAA) phải xác định và hạn chế việc sử dụng và tiết lộ được phép cũng như yêu cầu các biện pháp bảo vệ thích hợp; Do đó, PHI không được gửi đến nhà cung cấp mô hình để lấy ý kiến ​​phản hồi về đào tạo nếu không có BAA hiện hành.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-50', 'ccar-p', 50, 'An architect reviews a set of architecture-documentation packages before transferring a Claude-based pipeline to an implementation team.  
  
Which two characteristics show that a documentation package is sufficient to enable implementation without continued involvement from the architect? (Select two.)', '[{"key":"A","text":"The document specifies integration contracts, configuration schemas, and expected input/output shapes for each component."},{"key":"B","text":"The document includes a decision log that records the rationale for key architectural choices and the alternatives rejected."},{"key":"C","text":"The document provides a high-level narrative description of the business problem without component-level detail."},{"key":"D","text":"The document includes the architect’s contact information for questions arising during implementation."},{"key":"E","text":"The document lists all Claude models that were evaluated but does not specify which was selected or why."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Nhóm triển khai cần có hợp đồng tích hợp rõ ràng, lược đồ cấu hình và hình dạng đầu vào/đầu ra dự kiến ​​để xây dựng và kết nối các thành phần một cách chính xác. Nhật ký quyết định cũng lưu giữ cơ sở hợp lý cho các lựa chọn kiến ​​trúc then chốt và các phương án thay thế bị từ chối, cho phép nhóm áp dụng những đánh đổi đã dự định mà không cần dựa vào kiến ​​trúc sư.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-51', 'ccar-p', 51, 'The engineering lead at Trenova Systems, Inc. is assessing two proposals to improve developer workflows with Claude-assisted tooling. Proposal A integrates Claude Code into the IDE for inline code generation and review. Proposal B sends all code-generation requests through a shared Slack bot with no IDE integration.  
  
Which two observations most accurately assess these proposals against workflow-improvement objectives? (Select two.)', '[{"key":"A","text":"Proposal B is superior because centralizing requests in Slack creates an auditable log of all code-generation activity."},{"key":"B","text":"Proposal B introduces workflow friction by requiring developers to leave the IDE, undermining the productivity objective."},{"key":"C","text":"Proposal A reduces context switching by providing AI assistance at the point of development without requiring a separate tool."},{"key":"D","text":"Proposal B improves workflow velocity because Slack notifications create an asynchronous review queue."},{"key":"E","text":"Both proposals are equivalent because the model capabilities are identical regardless of the integration point."}]'::jsonb, ARRAY['B', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hỗ trợ AI được tích hợp trực tiếp vào IDE giúp giảm việc chuyển đổi ngữ cảnh và hỗ trợ việc tạo và đánh giá mã tại thời điểm diễn ra công việc phát triển. Việc yêu cầu các nhà phát triển gửi yêu cầu thông qua Slack sẽ đưa họ ra khỏi môi trường đó và gây thêm cản trở cho quy trình làm việc, điều này làm suy yếu mục tiêu năng suất.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-52', 'ccar-p', 52, 'You are reviewing a peer’s draft architecture decision record (ADR). The ADR records the decision and technical details but omits the alternatives considered and the trade-offs accepted.  
  
Which response is most appropriate?', '[{"key":"A","text":"Delete the ADR entirely and rely on the engineering team’s collective memory to reconstruct the decision context, alternatives, and trade-offs during future audits or onboarding."},{"key":"B","text":"Ask the author to add the alternatives considered and the trade-offs accepted before publishing the ADR."},{"key":"C","text":"Approve the ADR as written on the grounds that the decision itself is documented, accepting that reviewers and future maintainers will lack the context to evaluate or revisit it."},{"key":"D","text":"Replace the ADR with a different decision unrelated to the one drafted."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }ADR phải ghi lại không chỉ quyết định mà còn cả các lựa chọn thay thế được đánh giá và hậu quả hoặc sự đánh đổi được chấp nhận. Điều này duy trì cơ sở lý luận cần thiết cho việc xem xét, bảo trì, kiểm tra và triển khai trong tương lai.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-53', 'ccar-p', 53, 'A Claude architect is setting up a shared Claude Code environment for a 12-person development team.  
  
Which two configuration choices most directly create a consistent, secure team environment? (Select two.)', '[{"key":"A","text":"Commit shared MCP server definitions and tool permissions in project-scope configuration files alongside the repository."},{"key":"B","text":"Apply managed configuration to enforce non-overridable security and compliance policies across all team members."},{"key":"C","text":"Set editor theme and display preferences at the project scope so they are uniform across workstations."},{"key":"D","text":"Instruct each engineer to configure their preferred Claude model in personal user-scope settings."},{"key":"E","text":"Store the team’s shared API key in the project-scope settings.json so all engineers use the same credential."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cấu hình trong phạm vi dự án có thể được cam kết với kho lưu trữ để tất cả những người đóng góp đều nhận được cùng một định nghĩa máy chủ MCP và đường cơ sở cấp phép công cụ. Cấu hình được quản lý được ưu tiên hơn cài đặt của người dùng và dự án, đồng thời không thể bị ghi đè, cho phép thực thi các chính sách tuân thủ và bảo mật trên toàn tổ chức. Thông tin xác thực phải được giữ ngoài các cài đặt dự án đã cam kết và được cung cấp thông qua các cơ chế xác thực an toàn hoặc các biến môi trường.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-54', 'ccar-p', 54, 'A security team is assessing two proposed controls. Control A implements an outbound tool allow-list with destination restrictions and per-call review. Control B evaluates responses against a stable adversarial evaluation set after every model-version change.  
  
Which two risk categories are correctly matched to these controls? (Select two.)', '[{"key":"A","text":"Control A — prompt injection from adversarial content in retrieved data"},{"key":"B","text":"Control A — silent quality drift after a model-version upgrade"},{"key":"C","text":"Control A — data exfiltration via outbound tool calls"},{"key":"D","text":"Control B — data exfiltration via outbound tool calls"},{"key":"E","text":"Control B — silent quality drift after a model-version upgrade"}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Danh sách cho phép của công cụ gửi đi, các hạn chế về đích đến và hạn chế phê duyệt mỗi cuộc gọi trong đó nhân viên hỗ trợ có thể truyền thông tin, giảm thiểu việc đánh cắp dữ liệu thông qua các lệnh gọi công cụ. Việc chạy lại bộ đánh giá đối nghịch ổn định sau khi thay đổi phiên bản mô hình sẽ phát hiện sự hồi quy về hành vi và sự trôi dạt chất lượng thầm lặng do thay đổi phiên bản gây ra.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-55', 'ccar-p', 55, 'A Claude Architect reviews a post-deployment performance report for an AI-assisted legal-document summarization system.  
  
The report contains these observations:  
  
1. Average summarization time decreased from 47 minutes to 6 minutes per document.  
2. Associates spend less time on summaries, but overall billable output has not measurably changed.  
3. Infrastructure costs increased by 22% because redundant retry logic generated additional API calls.  
4. Some summaries require attorney correction, adding an average of 8 minutes of review per document.  
  
Which analysis correctly assigns each observation to the appropriate business-value pillar?', '[{"key":"A","text":"Observations 1 and 2 both indicate efficiency gains; Observation 3 is a solution-cost issue; Observation 4 is a performance-SLA issue."},{"key":"B","text":"Observation 1 is a transformation outcome; Observation 2 is an efficiency gain; Observation 3 is a performance-SLA degradation; Observation 4 is a solution-cost issue."},{"key":"C","text":"Observations 1 and 4 together indicate a net performance-SLA improvement; Observation 2 is a transformation gap; Observation 3 is a productivity drain from over-engineering."},{"key":"D","text":"Observation 1 indicates an efficiency gain; Observation 2 shows that productivity has not yet been realized; Observation 3 is a solution-cost issue; Observation 4 is an efficiency loss that partially offsets Observation 1."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Giảm thời gian tóm tắt là một lợi ích hiệu quả vì nó giảm thời gian lao động trên mỗi tài liệu. Giảm nỗ lực không trở thành tăng năng suất cho đến khi nó tạo ra sản lượng bổ sung có thể đo lường được hoặc sản lượng thực tế khác. Các lệnh gọi API bổ sung nhằm tăng chi tiêu cho cơ sở hạ tầng là một vấn đề về chi phí giải pháp. Thời gian sửa lỗi của luật sư sẽ bổ sung thêm công việc vào quy trình, tạo ra sự mất mát về hiệu quả mà bù đắp một phần thời gian tiết kiệm được bằng cách tóm tắt tự động.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-56', 'ccar-p', 56, 'A team manager needs every engineer working in the same repository to use identical MCP server definitions, without manually keeping them in sync.  
  
Which configuration approach meets this requirement?', '[{"key":"A","text":"managed configuration pushed to all endpoints by the administrator"},{"key":"B","text":"environment variables set at the operating-system level on each workstation"},{"key":"C","text":"project-scope .claude/settings.json and .mcp.json files committed to the repository"},{"key":"D","text":"each engineer maintains a personal ~/.claude/settings.json with the shared definitions"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các máy chủ MCP ở phạm vi dự án được lưu trữ trong `.mcp.json` của kho lưu trữ và được thiết kế để cam kết kiểm soát phiên bản, cho phép tất cả những người đóng góp dự án chia sẻ cùng một định nghĩa máy chủ MCP. Tệp cài đặt dự án đã cam kết có thể đi kèm với cấu hình kho lưu trữ được chia sẻ đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-57', 'ccar-p', 57, 'An architect at Trenova Systems, Inc. is evaluating two draft communication packages for the same architectural decision. Package 1 includes a threat model, residual-risk register, and control-mapping table. Package 2 includes a list of delivered capabilities and feature-level roadmap dependencies.  
  
Which two audiences are correctly matched to these packages? (Select two.)', '[{"key":"A","text":"Package 1 engineering implementation team"},{"key":"B","text":"Package 2 executive sponsor"},{"key":"C","text":"Package 1 security and compliance reviewer"},{"key":"D","text":"Package 2 product manager owning the roadmap"},{"key":"E","text":"Package 2 security and compliance reviewer"}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mô hình mối đe dọa, sổ đăng ký rủi ro còn lại và bảng ánh xạ kiểm soát hỗ trợ đảm bảo an ninh, chấp nhận rủi ro và đánh giá tuân thủ, vì vậy Gói 1 phù hợp với người đánh giá tuân thủ và bảo mật. Các khả năng được cung cấp và các phần phụ thuộc của lộ trình ở cấp tính năng hỗ trợ việc lập kế hoạch và ưu tiên sản phẩm, vì vậy Gói 2 phù hợp với người quản lý sản phẩm sở hữu lộ trình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-58', 'ccar-p', 58, 'A research-summarization assistant has been in production for six months. A user reports that a generated summary included a fabricated citation. The product team asks whether the incident needs architectural action or is an isolated occurrence.  
  
Which two Diligence-competency actions should you take? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Sample recent summaries to estimate the fabrication frequency across the population."},{"key":"B","text":"Disable the assistant immediately for all current users without any prior diagnostic analysis."},{"key":"C","text":"Review whether citation-grounding controls exist anywhere in the current generation pipeline."},{"key":"D","text":"Communicate to users that the assistant does not fabricate output as a matter of design."},{"key":"E","text":"Treat the incident as an anecdotal isolated case and take no further investigative action."}]'::jsonb, ARRAY['A', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc đánh giá mẫu tóm tắt gần đây sẽ xác định liệu việc bịa đặt trích dẫn có phải là vấn đề về chất lượng sản xuất rộng hơn hay không và cung cấp bằng chứng để quyết định phạm vi của nó. Việc xem xét quy trình tạo các biện pháp kiểm soát trích dẫn-grounding xác định liệu hệ thống có cơ chế hiệu quả để liên kết các trích dẫn với các nguồn hỗ trợ và bộc lộ lỗ hổng kiến ​​trúc hệ thống hay không. NIST mô tả việc đánh giá có hệ thống về grounding thực tế và đánh giá trích dẫn tự động, trong khi Microsoft khuyến nghị xác thực và giám sát việc truy xuất cũng như các thành phần grounding.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-59', 'ccar-p', 59, 'You are presenting an architecture decision to a mixed audience that includes an executive sponsor and the engineering leads responsible for implementing the decision.  
  
Which presentation approach best serves both audiences?', '[{"key":"A","text":"Open with a deep dive into low-level implementation details targeted at engineering leads, and stop there without addressing the business outcomes or trade-offs the executive sponsor needs."},{"key":"B","text":"Lead with the decision, the business outcomes it serves, and the trade-offs accepted; follow with the technical rationale, alternatives, and implementation implications for the engineering audience."},{"key":"C","text":"Skip the rationale, alternatives, and trade-off discussion entirely and simply announce the chosen decision, leaving both audiences without the context needed to implement or validate it."},{"key":"D","text":"Present a single undifferentiated narrative that addresses technical and business concerns with equal weight throughout, treating both audiences as requiring the same depth on every section."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bản trình bày quyết định về kiến ​​trúc hiệu quả bắt đầu bằng quyết định, kết quả kinh doanh mà nó hỗ trợ và những đánh đổi được chấp nhận để các bên liên quan điều hành có thể đánh giá giá trị và rủi ro. Sau đó, nó cung cấp cơ sở kỹ thuật, các lựa chọn thay thế được xem xét và các ý nghĩa triển khai cần thiết của kỹ thuật để xác nhận và thực hiện quyết định.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-60', 'ccar-p', 60, 'You are identifying characteristics of robust guardrail design for an enterprise deployment.  
  
Which two characteristics should be on the list? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Centralized log retention for guardrail violations with quarterly review by the security team."},{"key":"B","text":"Per-role tool allow-lists enforced at the orchestration layer before any tool call executes."},{"key":"C","text":"User feedback channels that route reported guardrail failures into the product backlog for triage."},{"key":"D","text":"Periodic refresh of the system prompt wording to keep refusal language current and clear."},{"key":"E","text":"Adversarial-input coverage in the evaluation set with regression tracking on guardrail performance."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các biện pháp bảo vệ doanh nghiệp mạnh mẽ thực thi đặc quyền tối thiểu ở ranh giới hành động: danh sách cho phép công cụ theo vai trò cụ thể ngăn chặn lệnh gọi công cụ trái phép trước khi nó thực thi, thay vì dựa vào lệnh mô hình để từ chối lệnh đó. Chất lượng lan can cũng cần thử nghiệm đối nghịch lặp đi lặp lại và theo dõi hồi quy để ngăn chặn các nỗ lực tiêm nhanh và bỏ qua khác cũng như phát hiện các hư hỏng theo thời gian. Hướng dẫn của OpenAI hỗ trợ hạn chế các công cụ được phép và các ứng dụng nhóm đỏ chống lại đầu vào đối nghịch.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-61', 'ccar-p', 61, 'You are establishing a feedback-and-alignment routine for a deployment with multiple stakeholders.  
  
Which two practices should be included in the routine? Each correct answer provides a complete solution. *(Select two.)*', '[{"key":"A","text":"Record each session and distribute the recording to stakeholders who could not attend live."},{"key":"B","text":"Escalate any disagreement among stakeholders to the executive sponsor for binding resolution."},{"key":"C","text":"Rotate facilitation among the participating stakeholder groups to share ownership of the routine."},{"key":"D","text":"Set a regular cadence for revisiting expectations and assumptions as conditions evolve over time."},{"key":"E","text":"Reconcile divergent stakeholder positions explicitly rather than papering over them in the moment."}]'::jsonb, ARRAY['D', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một nhịp độ thường xuyên để đánh giá lại các kỳ vọng và giả định giúp duy trì sự đồng bộ của các bên liên quan khi điều kiện triển khai thay đổi. Việc dung hòa một cách rõ ràng các quan điểm khác nhau của các bên liên quan sẽ giải quyết được các xung đột thực chất thay vì giấu kín chúng, tạo ra sự liên kết bền vững.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-62', 'ccar-p', 62, 'You are establishing an SLA for a Claude-based assistant.  
  
Which SLA definition is the most operationally meaningful?', '[{"key":"A","text":"A target tied to a stakeholder sentiment measure such as “the team feels satisfied,” which cannot be measured objectively or used to trigger a documented breach response."},{"key":"B","text":"A measurable target with a defined metric, threshold, evaluation window, and consequence for breach—for example, “p95 per-request latency under 800 ms over a 28-day window.”"},{"key":"C","text":"A qualitative commitment such as “the system will be fast and reliable,” which names no metric, threshold, or evaluation window."},{"key":"D","text":"A target that names the metric and threshold but omits the evaluation window and breach consequence, leaving compliance periods and remediation triggers undefined."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }SLA hoạt động xác định chỉ số khách quan, ngưỡng có thể chấp nhận, khoảng thời gian dùng để đánh giá sự tuân thủ và hậu quả hoặc phản hồi được ghi lại đối với hành vi vi phạm. Những yếu tố này làm cho hiệu suất có thể đo lường được và thiết lập khi nào cần khắc phục.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-63', 'ccar-p', 63, 'You are explaining Claude Code configuration-scope precedence to the team.  
  
Which ordering of precedence, from highest to lowest, is correct?', '[{"key":"A","text":"Local → managed → user → command-line arguments → project"},{"key":"B","text":"Project → user → managed → local → command-line arguments"},{"key":"C","text":"Managed → command-line arguments → local → project → user"},{"key":"D","text":"User → project → local → command-line arguments → managed"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code ưu tiên cao nhất cho cài đặt do tổ chức quản lý, tiếp theo là cài đặt dòng lệnh, cài đặt dự án cục bộ, cài đặt dự án dùng chung và cài đặt người dùng. Cài đặt có mức độ ưu tiên cao hơn sẽ ghi đè cùng một khóa ở các cấp độ thấp hơn.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-64', 'ccar-p', 64, 'You are establishing transparency practices for a customer-facing assistant whose responses are materially influenced by AI.  
  
Which transparency practice most directly promotes responsible deployment?', '[{"key":"A","text":"Misrepresent the AI’s role in producing responses in order to make the assistant feel more trustworthy or more human, undermining informed user consent and organizational transparency."},{"key":"B","text":"Refuse to answer any user question about how the responses were produced or whether AI was involved, treating the AI’s role as confidential operational information."},{"key":"C","text":"Disclose AI involvement to end users in line with the organization’s transparency policy and provide a documented path to reach a human when needed."},{"key":"D","text":"Disclose AI involvement only to internal staff and operators while withholding that information from the end users whose interactions are materially shaped by the AI system."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc triển khai có trách nhiệm đòi hỏi phải tiết lộ rõ ​​ràng về sự tham gia của AI cho những người bị ảnh hưởng bởi hệ thống, giúp họ hiểu được bản chất của sự tương tác và điều chỉnh mức độ tin cậy của họ một cách thích hợp. Một lộ trình hỗ trợ con người được ghi lại, dễ tiếp cận cũng hỗ trợ việc giám sát và báo cáo khi trợ lý không thể giải quyết nhu cầu một cách thích hợp. Hướng dẫn của Microsoft yêu cầu tiết lộ AI rõ ràng cho các tác nhân làm việc bên ngoài và các tùy chọn tương tác hoặc chuyển giao trực quan của con người.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-65', 'ccar-p', 65, 'You are auditing a procurement-assistant agent whose defined responsibility is drafting purchase requests for review. For each currently configured tool, select Yes if it should remain after a least-privilege audit. Otherwise, select No if it should be removed.  
  
For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"a read-only catalog lookup tool that returns vendor and SKU information","correctAnswer":"Yes"},{"id":"2","text":"an inbox-send tool that emails purchase requests to vendors directly","correctAnswer":"No"},{"id":"3","text":"a draft-write tool that creates purchase-request drafts in the review queue","correctAnswer":"Yes"},{"id":"4","text":"a production-database admin tool unrelated to procurement","correctAnswer":"No"},{"id":"5","text":"A read-only policy-document tool that returns the relevant procurement policies","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes', '4:No', '5:Yes']::text[], '[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R2cqjmlfiv5tpfiv5uadb"]::highlight(question-marker-R2cqjmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đặc quyền tối thiểu cho phép tra cứu chính sách và danh mục chỉ đọc cần thiết để chuẩn bị các bản nháp theo yêu cầu mua hàng tuân thủ, cùng với khả năng ghi bản nháp cần thiết để đưa các bản nháp vào hàng đợi xem xét. Việc gửi email trực tiếp của nhà cung cấp vượt quá trách nhiệm chỉ dành cho người xem xét và việc quản lý cơ sở dữ liệu sản xuất không liên quan là không cần thiết và có đặc quyền quá mức.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-66', 'ccar-p', 66, 'You are establishing escalation criteria for ambiguous cases in an automated workflow.  
  
Which set of criteria best enables consistent escalation?', '[{"key":"A","text":"No escalation criteria; the model decides independently on every turn whether to escalate, without explicit confidence thresholds, impact categories, or classifier-based ambiguity flags."},{"key":"B","text":"Escalation only after an affected customer has contacted support to complain, after the automated workflow has already completed without human review."},{"key":"C","text":"Escalation at the discretion of whoever is available when the team’s on-call engineer has spare capacity, without a defined threshold, category, or ambiguity criterion."},{"key":"D","text":"A confidence score below a defined threshold, presence of high-impact decision categories, ambiguity flags raised by content classifiers, and the user’s explicit request for review."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mức tăng nhất quán phụ thuộc vào các yếu tố kích hoạt rõ ràng, có thể lặp lại: ngưỡng tin cậy được xác định, các danh mục quyết định có tác động cao được chỉ định, các tín hiệu không rõ ràng dựa trên bộ phân loại và yêu cầu xem xét của người dùng. Các tiêu chí này cho phép quy trình làm việc xác định các trường hợp cần có sự giám sát của con người trước khi đưa ra quyết định tự động có khả năng gây hậu quả.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-67', 'ccar-p', 67, 'A loan pre-qualification assistant produces approval recommendations that agree with the human underwriter’s decision 94 percent of the time. The fairness team has evaluated approval-rate parity across protected groups and found no significant difference. A board member asks whether this evidence is enough to declare the assistant fair.  
  
Which two Discernment-competency findings should you report? Each correct answer provides part of the solution. (Select two.)', '[{"key":"A","text":"Approval rate parity does not by itself assess error rate parity across protected groups."},{"key":"B","text":"Match with human underwriters does not establish freedom from underwriter-introduced bias."},{"key":"C","text":"The 94 percent match rate is sufficient evidence of fairness for the assistant’s decisions."},{"key":"D","text":"The fairness team’s review process likely missed at least some of the protected groups studied."},{"key":"E","text":"A larger sample is needed before any meaningful fairness claim can be made about the model."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Chỉ tính tương đương của tỷ lệ phê duyệt không xác định liệu tỷ lệ lỗi, chẳng hạn như tỷ lệ dương tính giả hoặc âm tính giả, có thể so sánh được giữa các nhóm được bảo vệ hay không. Thỏa thuận với những người bảo lãnh là con người cũng không chứng minh được sự công bằng, bởi vì người trợ lý có thể tìm hiểu và duy trì sự thiên vị gắn liền với các quyết định của con người được sử dụng làm tài liệu tham khảo.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-68', 'ccar-p', 68, 'You are integrating Claude Code into the team’s pull-request workflow. The team wants AI-assisted reviews while retaining human approval.  
  
Which integration design best meets this requirement?', '[{"key":"A","text":"Claude Code reviews the pull request and posts a structured analysis as a comment, while a human reviewer retains the approval decision under the existing branch-protection rules."},{"key":"B","text":"Claude Code merges every pull request automatically after completing its analysis, bypassing human approval and the existing branch-protection rules."},{"key":"C","text":"Claude Code disables all existing branch-protection rules to streamline the merge process, removing human approval as a required gate."},{"key":"D","text":"Claude Code silently deletes pull requests it assesses as low quality without posting a comment or notifying the author."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code có thể chạy quy trình đánh giá theo yêu cầu kéo và cung cấp phản hồi đánh giá tự động. Duy trì yêu cầu bảo vệ chi nhánh hiện tại về việc phê duyệt đánh giá của con người sẽ duy trì quyền kiểm soát của con người đối với quyết định sáp nhập; Bảo vệ nhánh GitHub có thể yêu cầu phê duyệt đánh giá trước khi yêu cầu kéo được hợp nhất.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-69', 'ccar-p', 69, 'The compliance team at a firm has approved a Claude Skill that produces client-facing investment summaries. The Skill contains the firm’s required disclaimers and prohibited-language list. A product manager has asked whether extra guardrails are required in the application layer, or whether the Skill alone is adequate.  
  
Which two guardrail responsibilities must remain at the application layer instead of the Skill? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Log every generated summary to the firm’s compliance audit trail for retention."},{"key":"B","text":"Verify the requesting user is authorized to generate investment summaries at all."},{"key":"C","text":"Format output sections according to the firm’s standardized house style guidelines."},{"key":"D","text":"Apply the disclaimer template that the compliance team has standardized firm-wide."},{"key":"E","text":"Apply the prohibited-language list that the compliance team maintains and updates."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ủy quyền là một quyết định kiểm soát quyền truy cập ở cấp ứng dụng vì nó phụ thuộc vào danh tính và quyền của người dùng yêu cầu. Việc lưu giữ kiểm toán tuân thủ cũng là một trách nhiệm ở cấp độ ứng dụng vì ứng dụng phải ghi lại mọi bản tóm tắt được tạo một cách đáng tin cậy trong quá trình kiểm toán của công ty. Kỹ năng được phê duyệt có thể áp dụng tập trung tuyên bố từ chối trách nhiệm có thể sử dụng lại và kiểm soát nội dung bằng ngôn ngữ bị cấm. Hướng dẫn của Anthropic mô tả xác thực tập trung và ghi nhật ký kiểm tra dưới dạng cơ sở hạ tầng hoặc khả năng cổng xung quanh các tương tác mô hình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-70', 'ccar-p', 70, 'You are addressing inefficiency in a Claude Code workflow in which every engineer must manually re-explain the project’s conventions and architecture during each session.  
  
Which change most directly eliminates this inefficiency?', '[{"key":"A","text":"Forbid the use of Claude Code on the project entirely to avoid the session-initialization overhead, accepting that the team loses all AI-assisted development productivity for this codebase."},{"key":"B","text":"Capture the project''s conventions and architecture in a project-scoped CLAUDE.md (or equivalent persistent project-context file) committed to the repository, so each session loads it automatically."},{"key":"C","text":"Tell each engineer to retype the project conventions and architecture context more quickly at the start of each session, reducing time lost without eliminating the repeated manual effort."},{"key":"D","text":"Remove all documented project conventions and architectural standards so engineers have nothing to re-explain at session start, accepting the loss of consistency and shared coding standards."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; } CLAUDE.md trong phạm vi dự án, được cam kết với kho lưu trữ liên tục lưu trữ các quy ước và bối cảnh kiến ​​trúc được chia sẻ, cho phép các phiên Claude Code trong dự án đó tải thông tin tự động thay vì yêu cầu giải thích thủ công nhiều lần.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-71', 'ccar-p', 71, 'You are deploying a standardized Claude Code configuration to an engineering team and need to complete the planning activities before piloting the configuration.  
  
Which two steps must be completed **BEFORE** piloting the configuration with a small group of engineers? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Define the project-scope baseline covering Model Context Protocol (MCP) servers, permission rules, and subagents."},{"key":"B","text":"Onboard every engineer in the organization to the new configuration through mandatory training sessions."},{"key":"C","text":"Roll out the stabilized configuration to additional teams with documentation and a defined support channel."},{"key":"D","text":"Identify the team workflows, security boundaries, and which decisions belong to managed configuration versus project scope."},{"key":"E","text":"Iterate the configuration based on the pilot findings and stabilize the baseline before broader rollout."}]'::jsonb, ARRAY['A', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một chương trình thí điểm có kiểm soát yêu cầu xác định các quy trình làm việc hiện hành của nhóm và ranh giới bảo mật, bao gồm cả các biện pháp kiểm soát phải được quản lý tập trung và biện pháp kiểm soát nào thuộc về một dự án. Quyết định đó tạo ra đường cơ sở trong phạm vi dự án cho các máy chủ MCP được chia sẻ, quy tắc cấp phép và tác nhân phụ. Claude Code phân biệt cài đặt được quản lý tập trung với cài đặt dự án được chia sẻ và các máy chủ MCP trong phạm vi dự án được dành cho cấu hình chia sẻ nhóm. Đào tạo trên toàn tổ chức, triển khai rộng hơn và sàng lọc sau thí điểm diễn ra sau thay vì đi trước thí điểm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-72', 'ccar-p', 72, 'You are assembling a diagnostic toolkit for Claude Code operational problems.  
  
Which two diagnostic actions should be included in the toolkit? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Increase the model sampling temperature so that intermittent issues surface more frequently for analysis."},{"key":"B","text":"File a support ticket with vendor support before any local reproduction or evidence collection."},{"key":"C","text":"Reproduce the issue with a minimal reproduction case that isolates one variable at a time."},{"key":"D","text":"Roll back to the previous Claude Code version immediately to confirm whether the issue is version specific."},{"key":"E","text":"List the configured Model Context Protocol (MCP) servers and inspect server status to identify connection failures."}]'::jsonb, ARRAY['C', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc sao chép tối thiểu nhằm tách biệt một biến tại một thời điểm sẽ xác định liệu một điều kiện đầu vào, cấu hình hoặc môi trường cụ thể có gây ra lỗi hay không và đưa ra bằng chứng có thể xử lý được. Máy chủ MCP là các máy chủ phụ thuộc hoạt động bên ngoài; Claude Code ghi lại trạng thái và quản lý máy chủ MCP, do đó, việc liệt kê các máy chủ được định cấu hình và kiểm tra trạng thái của chúng có thể phát hiện lỗi kết nối hoặc cấu hình. Việc tăng cường hỗ trợ sẽ hiệu quả hơn sau khi đã thu thập được bằng chứng chẩn đoán, trong khi việc thay đổi nhiệt độ mô hình hoặc khôi phục ngay phiên bản không tạo thành một phương pháp chẩn đoán hoàn chỉnh, có mục tiêu.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-73', 'ccar-p', 73, 'You are incorporating Claude Code into a workflow that operates against a production database.  
  
Which guardrail design most directly maintains safety for data-modifying operations?', '[{"key":"A","text":"Allow Claude Code to write directly to the production database without subagent scoping, read-only credential defaults, or human confirmation gates on data-modifying operations."},{"key":"B","text":"Configure the database MCP server with a fully privileged credential that can perform any read or write operation, and allow all operations to proceed without explicit human confirmation."},{"key":"C","text":"Disable all logging and auditing on database operations through the MCP server to reduce alert noise, removing the observability needed to detect unintended data modifications."},{"key":"D","text":"Configure the database MCP server with a read-only credential by default, restrict the subagent’s tool list to read-only operations, and require explicit human confirmation on any operation that would modify data."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Theo mặc định, thông tin xác thực cơ sở dữ liệu chỉ đọc và danh sách công cụ được giới hạn ở các hoạt động chỉ đọc sẽ ngăn chặn việc ghi ngoài ý muốn, trong khi xác nhận rõ ràng của con người sẽ cung cấp một cổng phê duyệt trước bất kỳ hành động thay đổi dữ liệu nào. Điều này áp dụng biện pháp bảo vệ theo chiều sâu và ít đặc quyền nhất đối với quyền truy cập sản xuất. Claude Code hỗ trợ hạn chế các công cụ có sẵn và lời nhắc cấp phép cho các hành động yêu cầu phê duyệt.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-74', 'ccar-p', 74, 'You need to present an architectural recommendation for deploying a Claude-based contract review assistant to a steering committee that includes the CFO, general counsel, and CIO. Each stakeholder focuses on different aspects of the decision.  
  
How should you organize the recommendation document?', '[{"key":"A","text":"Lead with the technical architecture diagram and the full component list before any other section."},{"key":"B","text":"Lead with detailed cost projections across the full multi-year horizon before the rationale section."},{"key":"C","text":"Present the same dense narrative throughout with no stakeholder differentiation in any section."},{"key":"D","text":"Lead with the architectural decision, then address each stakeholder’s primary concerns directly."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khuyến nghị điều hành hiệu quả bắt đầu bằng quyết định kiến ​​trúc, sau đó trực tiếp giải quyết các mối lo ngại về tài chính của CFO, các mối lo ngại về pháp lý và rủi ro của cố vấn chung cũng như các mối lo ngại về kỹ thuật, bảo mật và hoạt động của CIO. Điều này làm cho cơ sở lý luận trở nên phù hợp và có thể áp dụng được đối với mỗi người ra quyết định mà không đưa ra khuyến nghị chi tiết về kỹ thuật hoặc chi phí quá sớm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-75', 'ccar-p', 75, 'You are moving a Claude-based deployment from the design phase into implementation.  
  
Which handoff package most directly enables a smooth transition?', '[{"key":"A","text":"The most recent set of design presentation slides without component-level diagrams, interface contracts, an evaluation framework with a reference set, runbooks, or a known-limitations register."},{"key":"B","text":"A verbal walkthrough conducted on the day of handoff with no written architecture overview, ADRs, component contracts, evaluation framework, runbooks, playbook, or known limitations."},{"key":"C","text":"Architecture overview, ADRs, component contracts, evaluation framework with reference set, runbooks, on-call playbook, and known limitations."},{"key":"D","text":"Source code alone with no integrating architecture overview, ADRs, component contracts, evaluation framework, runbooks, on-call playbook, or known-limitations register to support the delivery team."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc chuyển giao triển khai hoàn chỉnh cần có tổng quan về kiến ​​trúc và ADR để truyền tải cơ sở lý luận và thiết kế hệ thống; hợp đồng thành phần để xác định ranh giới hội nhập; một khung đánh giá với một bộ tham chiếu để xác nhận hành vi; sổ điều hành và sổ tay theo yêu cầu để hỗ trợ hoạt động; và một bản ghi các giới hạn đã biết để làm rõ các rủi ro và ràng buộc.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-76', 'ccar-p', 76, 'You are identifying indicators that a deployment should return to design instead of continuing to iterate in place.  
  
Which indicator most directly shows that a new design cycle is needed?', '[{"key":"A","text":"A runbook step requires a clarification edit to improve on-call guidance accuracy, which can be handled as a documentation update without changes to component responsibilities or core contracts."},{"key":"B","text":"A dashboard alert threshold needs a small numerical adjustment to reduce false-positive noise, which can be handled as an operational configuration change without a new design cycle."},{"key":"C","text":"A minor copy edit is requested in a customer-facing string within the existing UI, which can be handled as a localized content change without altering component responsibilities or contracts."},{"key":"D","text":"The system’s current architecture cannot meet the new requirements without changes to component responsibilities or core contracts."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cần có chu trình thiết kế mới khi không thể đáp ứng các yêu cầu mới trong kiến ​​trúc hiện tại nếu không thay đổi trách nhiệm của thành phần hoặc hợp đồng cốt lõi. Những thay đổi đó làm thay đổi ranh giới thiết kế cơ bản thay vì thực hiện cập nhật nội dung, tài liệu, cấu hình hoặc hoạt động cục bộ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-77', 'ccar-p', 77, 'A Claude architect notices that, after a recent model-version upgrade, grounded responses started to include claims that are not supported by the retrieved source documents.  
  
Which mitigation most directly addresses this failure mode?', '[{"key":"A","text":"Constrain responses to source-supported content, require citations, and add a verification step."},{"key":"B","text":"Score each new model version against a stable adversarial evaluation set."},{"key":"C","text":"Replace the shared API key with per-user OAuth tokens to restrict data access."},{"key":"D","text":"Treat retrieved data as untrusted and apply input classifiers at ingestion time."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Ràng buộc Source-grounding, trích dẫn bắt buộc và bước xác minh trực tiếp giảm các xác nhận quyền sở hữu không được hỗ trợ bằng cách yêu cầu nội dung phản hồi phải được theo dõi và kiểm tra đối với các tài liệu được truy xuất.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-78', 'ccar-p', 78, 'You are reviewing a colleague’s Claude Code permission rules for an enterprise rollout. The rules provide unrestricted Bash access across all projects for every developer.  
  
Which response is most appropriate?', '[{"key":"A","text":"Add unrestricted access to additional tool categories as well, so that Bash is not asymmetrically more permissive than other tools, expanding the attack surface further in the name of consistency."},{"key":"B","text":"Approve the unrestricted Bash access as written on the grounds that narrowing the rules would add configuration complexity, accepting the full attack surface for all engineers across all projects."},{"key":"C","text":"Replace unrestricted Bash with narrowly scoped tool patterns that allow only the specific commands the workflows require, and add explicit deny rules for sensitive operations."},{"key":"D","text":"Disable all permission rules for the enterprise rollout so every command across every project runs without any tool-pattern scoping or explicit deny rules for sensitive operations."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các quyền Claude Code dành cho doanh nghiệp phải tuân theo đặc quyền tối thiểu: chỉ cho phép các mẫu lệnh Bash được yêu cầu bởi quy trình làm việc đã được phê duyệt và từ chối rõ ràng các hoạt động nhạy cảm. Claude Code hỗ trợ các mẫu cho phép `Bash(.)` trong phạm vi và cơ chế `--disallowedTools`, tránh rủi ro bảo mật khi thực thi shell tùy ý trên tất cả các dự án.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-79', 'ccar-p', 79, 'A solutions architect is reviewing stakeholder feedback gathered after the first quarter of a Claude-powered procurement automation deployment.  
  
The feedback contains four statements:  
  
(1) “Our procurement team is processing 3x more purchase orders per analyst per day.”  
  
(2) “We have eliminated the manual data entry role entirely and redeployed those staff to vendor relationship management.”  
  
(3) “The API integration costs are running 40% over the projected per-transaction budget.”  
  
(4) “Response latency during end-of-month batch runs is averaging 11 seconds, against our committed 5-second SLA.”  
  
Which option correctly identifies the primary business-value pillar represented by each stakeholder statement?', '[{"key":"A","text":"Statement 1: Efficiency; Statement 2: Transformation; Statement 3: Solution Cost; Statement 4: Performance SLA"},{"key":"B","text":"Statement 1: Productivity; Statement 2: Efficiency; Statement 3: Solution Cost; Statement 4: Performance SLA"},{"key":"C","text":"Statement 1: Transformation; Statement 2: Productivity; Statement 3: Solution Cost; Statement 4: Efficiency"},{"key":"D","text":"Statement 1: Efficiency; Statement 2: Productivity; Statement 3: Performance SLA; Statement 4: Solution Cost"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc xử lý số lượng đơn đặt hàng nhiều gấp ba lần cho mỗi nhà phân tích sẽ tăng thông lượng và giảm nỗ lực cho mỗi giao dịch trong quy trình làm việc hiện tại, đó là Hiệu quả. Việc loại bỏ công việc nhập dữ liệu thủ công và chuyển nhân viên sang quản lý mối quan hệ với nhà cung cấp sẽ thiết kế lại các trách nhiệm xung quanh công việc có giá trị cao hơn, đó là Chuyển đổi. Chi phí API vượt quá 40% là mối lo ngại về Chi phí giải pháp, trong khi độ trễ 11 giây so với mục tiêu 5 giây đã cam kết là vấn đề SLA hiệu suất. Anthropic mô tả quá trình tự động hóa giúp giải phóng các chuyên gia cho công việc mang tính chiến lược giống như việc chuyển đổi quy trình làm việc.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-80', 'ccar-p', 80, 'You are creating an architecture guide for a new deployment and must finish the planning activities before drafting each guide section.  
  
Which two activities must be completed **BEFORE** drafting every section of the guide? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Identify the audience and the questions the guide must answer for that audience."},{"key":"B","text":"Translate the guide into the supported regional languages for the candidate population."},{"key":"C","text":"Validate the guide with the implementation team and incorporate corrections."},{"key":"D","text":"Establish the document under version control with a defined review cadence and approver list."},{"key":"E","text":"Outline the guide sections covering the overview, components, contracts, flows, runbooks, and limitations."}]'::jsonb, ARRAY['A', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hướng dẫn kiến ​​trúc phải được lập kế hoạch phù hợp với đối tượng mục tiêu và thông tin mà đối tượng cần. Nó cũng phải có một dàn ý sắp xếp nội dung được yêu cầu—chẳng hạn như phần tổng quan, các thành phần, hợp đồng, quy trình, sổ sách và các giới hạn—trước khi các phần riêng lẻ được soạn thảo.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-81', 'ccar-p', 81, 'You are supporting an EU-based deployment subject to GDPR obligations.  
  
Which combination of measures best supports the deployment’s GDPR posture?', '[{"key":"A","text":"enterprise-tier deployment with a signed Data Processing Addendum, defined data-retention configuration, redaction of personal data not needed for the task, and documented data-subject-rights handling"},{"key":"B","text":"disabling all data-retention configuration, redaction controls, and data-subject-rights handling to simplify day-to-day operations, accepting the resulting GDPR compliance exposure"},{"key":"C","text":"using a personal Claude account tier for processing EU personal data at scale, with no signed Data Processing Addendum and no documented data-subject-rights handling procedure"},{"key":"D","text":"pasting full EU personal data into every prompt to “give Claude complete context” without considering purpose limitation, data minimization, or the organization’s Data Processing Addendum obligations"}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }GDPR yêu cầu dữ liệu cá nhân phải được giới hạn ở mức cần thiết, no được lưu giữ lâu hơn mức cần thiết và được nhà cung cấp dịch vụ xử lý theo thỏa thuận xử lý ràng buộc thích hợp. Việc biên tập lại dữ liệu cá nhân không cần thiết, xác định việc lưu giữ, duy trì Phụ lục xử lý dữ liệu và ghi lại các thủ tục về quyền của chủ thể dữ liệu hỗ trợ các nghĩa vụ này. Claude Enterprise cũng cung cấp các điều khiển lưu giữ dữ liệu có thể định cấu hình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-82', 'ccar-p', 82, 'You support a team whose Claude Code sessions routinely load 60 or more MCP tools from numerous servers, exhausting the context budget before a session starts.  
  
Which change most directly resolves this problem without removing capability?', '[{"key":"A","text":"Enable Tool Search so tool definitions are deferred and discovered on demand rather than loaded into context upfront."},{"key":"B","text":"Disable every MCP server in the configuration to free up context budget, accepting that the team loses all tool access and cannot perform any MCP-dependent task in the session."},{"key":"C","text":"Increase the prompt’s verbosity with additional instructions and context, which consumes more of the context budget rather than reducing the tool-definition overhead causing the issue."},{"key":"D","text":"Add additional MCP servers to give the team more capability, which increases rather than reduces the number of tool definitions loaded into the session’s context budget."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tìm kiếm công cụ hỗ trợ tải trì hoãn, ngăn chặn các mô tả công cụ MCP bị trì hoãn nhập vào ngữ cảnh ban đầu của mô hình. Các công cụ này vẫn có sẵn và các định nghĩa của chúng tải theo yêu cầu khi được phát hiện thông qua tìm kiếm, giảm chi phí ngữ cảnh ban đầu mà không loại bỏ khả năng MCP.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-83', 'ccar-p', 83, 'During an architecture review, the security team identifies a risk that adversarial content inserted into retrieved documents could influence the model’s behavior.  
  
Which mitigation most directly addresses this threat?', '[{"key":"A","text":"Treat all retrieved content as untrusted input and apply input classifiers with output validation."},{"key":"B","text":"Require citations for each claim and constrain responses to source-supported content."},{"key":"C","text":"Restrict outbound tool calls to an approved destination allow-list."},{"key":"D","text":"Score outputs against a stable adversarial evaluation set on each model-version change."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tài liệu được truy xuất có thể chứa hướng dẫn chèn nhắc gián tiếp. Xử lý tất cả nội dung được truy xuất là không đáng tin cậy, áp dụng bộ phân loại hoặc phát hiện tiêm trước khi nội dung đó đến mô hình và xác thực kết quả đầu ra sẽ thiết lập các biện pháp kiểm soát tại ranh giới tin cậy có liên quan.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-84', 'ccar-p', 84, 'You are selecting the appropriate level of detail for an implementation guide. The audience is a delivery team that will build the deployment.  
  
Which guidance composition best supports them?', '[{"key":"A","text":"Component responsibilities, contracts between components, sequence diagrams of the dominant flows, configuration parameters with defaults, and operational runbooks."},{"key":"B","text":"Component responsibilities and interface contracts only, without sequence diagrams of the dominant flows, configuration parameters with defaults, or runbooks to guide operational tasks."},{"key":"C","text":"An architecture overview and sequence diagrams for the dominant flows, without interface contracts, configuration-parameter tables, or operational runbooks for the delivery team to follow."},{"key":"D","text":"An architecture overview and a list of known limitations, without component-level diagrams, interface contracts, configuration parameters, or operational runbooks to support implementation."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Nhóm phân phối cần hướng dẫn ở cấp độ triển khai bao gồm các trách nhiệm của thành phần, hợp đồng giữa các thành phần, trình tự luồng chi phối, thông số cấu hình và mặc định cũng như quy trình vận hành. Cùng với nhau, các tạo phẩm này hỗ trợ xây dựng, tích hợp, định cấu hình và vận hành quá trình triển khai.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-85', 'ccar-p', 85, 'You are incorporating Claude Code into a team workflow and must complete the design and configuration steps before piloting the integrated workflow with a small group.  
  
Which two steps must be completed BEFORE piloting the integrated workflow? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Document the integrated workflow with handoff criteria, permission boundaries, and on-call runbooks."},{"key":"B","text":"Identify the workflow steps where AI-assisted tooling adds value and where human authority must remain."},{"key":"C","text":"Negotiate the workflow change with affected teams and obtain formal sign-off from each manager."},{"key":"D","text":"Iterate the integrated workflow based on pilot findings before broader rollout to the team."},{"key":"E","text":"Configure the project-scope MCP servers, permissions, subagents, and persistent project context."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phi công Claude Code cần có sự phân chia rõ ràng giữa các hoạt động trong quy trình công việc, trong đó sự hỗ trợ của AI sẽ tăng thêm giá trị và các hoạt động vẫn thuộc thẩm quyền của con người. Nó cũng cần có sẵn cấu hình hoạt động của dự án: tích hợp MCP, kiểm soát quyền, các tác nhân phụ chuyên biệt và hướng dẫn/ngữ cảnh liên tục của dự án. Claude Code ghi lại thiết lập, quyền, tác nhân phụ và bộ nhớ dự án của MCP trong phạm vi dự án dưới dạng các cơ chế cấu hình riêng biệt nhằm thiết lập các khả năng và ranh giới đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-86', 'ccar-p', 86, 'You are documenting an architectural decision to enable future audit and onboarding.  
  
Which artifact is the best fit?', '[{"key":"A","text":"A slide deck in a presentation folder with no accompanying written rationale."},{"key":"B","text":"A code comment in a single file that contains an opinion of one engineer."},{"key":"C","text":"An Architecture Decision Record that states the context, the decision, the alternatives considered, the consequences, and the date and authors."},{"key":"D","text":"A short verbal note shared during a hallway conversation with no written record."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bản ghi Quyết định Kiến trúc lưu giữ bối cảnh và cơ sở lý luận cho một lựa chọn kiến ​​trúc, bao gồm các lựa chọn thay thế, kết quả quyết định và hậu quả. Bản ghi có thể quy kết bằng văn bản của nó hỗ trợ các cuộc kiểm tra sau này và giúp các thành viên mới trong nhóm hiểu lý do tại sao kiến ​​trúc lại có hình thức hiện tại.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-87', 'ccar-p', 87, 'You are a platform architect building an internal Claude-based assistant for both finance analysts and external auditors. Each group must be able to access only the documents authorized for its role.  
  
At which point in the pipeline should role-based access control be enforced?', '[{"key":"A","text":"Inside the system prompt as a natural-language instruction for Claude to ignore unauthorized documents."},{"key":"B","text":"At the retrieval layer, before any role-restricted content reaches the prompt-construction step or the model."},{"key":"C","text":"Nowhere in the pipeline; rely on the model’s general refusal behavior to reject unauthorized document access without any enforced access control."},{"key":"D","text":"After the response is generated, by post-filtering content that should not have been retrieved."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Role-based access control thuộc về thời điểm truy xuất, trước khi tài liệu được truy xuất được thêm vào lời nhắc hoặc hiển thị với mô hình. Việc thực thi ủy quyền ở đó ngăn chặn nội dung trái phép xâm nhập vào bối cảnh mô hình; hướng dẫn chỉ nhắc nhở, hành vi từ chối chung và lọc sau phản hồi không cung cấp ranh giới bảo mật đó. Amazon Bedrock ghi lại truy xuất nhận biết ACL dưới dạng lọc trước truy xuất chỉ trả về những tài liệu mà người dùng được cung cấp được phép truy cập.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-88', 'ccar-p', 88, 'A Claude architect is implementing safety controls for a customer-facing advice assistant that must never give regulated investment recommendations.  
  
Which two guardrail implementations most directly enforce this requirement? (Select two.)', '[{"key":"A","text":"Increase response temperature to introduce variability that reduces the likelihood of specific recommendations."},{"key":"B","text":"Add an output classifier that detects and blocks responses containing regulated investment-recommendation language."},{"key":"C","text":"Limit session length to reduce the volume of queries processed per user per day."},{"key":"D","text":"Log all user queries to a SIEM for post-hoc compliance review."},{"key":"E","text":"Define explicit out-of-scope categories in the system prompt with fixed refusal phrasing for investment advice requests."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Trình phân loại đầu ra có thể chặn ngôn ngữ đề xuất đầu tư bị cấm trước khi nó được gửi, trong khi các ranh giới rõ ràng do hệ thống nhắc nhở và từ ngữ từ chối được quy định sẽ hướng dẫn trợ lý từ chối các yêu cầu tư vấn đầu tư ngoài phạm vi. Hướng dẫn của Anthropic đề xuất các lời nhắc hệ thống được củng cố nhằm nêu rõ các ranh giới pháp lý và đạo đức cũng như cách từ chối, đồng thời mô tả các bộ lọc như một cách để thực thi các rào cản đầu ra.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-89', 'ccar-p', 89, 'A business sponsor has asked for an AI solution to “improve customer experience.” The sponsor cannot specify which customer journey is failing, which metric demonstrates that failure, or which decisions the AI should support. The sponsor is asking you to start design work next week.  
  
Which delegation-competency action should you take first?', '[{"key":"A","text":"Recommend that the sponsor revise the request and resubmit it later for evaluation."},{"key":"B","text":"Begin prototyping a generic assistant against the broad request before the next deadline."},{"key":"C","text":"Propose a fixed scope that you commit to by default based on your own assumptions."},{"key":"D","text":"Facilitate a structured discovery to define the failing decision and the target metric."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phiên khám phá có cấu trúc sẽ thiết lập quyết định không thành công cụ thể, hành trình của khách hàng bị ảnh hưởng và kết quả mục tiêu có thể đo lường được trước khi bắt đầu thiết kế giải pháp. Những định nghĩa này cung cấp phạm vi vấn đề và tiêu chí thành công cần thiết để xác định liệu AI có phù hợp hay không và nó sẽ hỗ trợ những gì.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-90', 'ccar-p', 90, 'You are evaluating data-exfiltration risk in a Claude-based assistant that has tools for internal-document retrieval and outbound HTTP calls.  
  
Which scenario most directly signals a data-exfiltration risk?', '[{"key":"A","text":"The outbound HTTP tool returns a 200 response when the assistant calls an allow-listed domain to fulfil a user-initiated data-lookup request."},{"key":"B","text":"The user submits a routine question and receives a routine answer."},{"key":"C","text":"Adversarial content in a retrieved document instructs the model to call the outbound HTTP tool and send sensitive content to an attacker-controlled URL."},{"key":"D","text":"The internal-document retrieval tool returns a document that the user is authorized to view."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các hướng dẫn bất lợi được nhúng trong nội dung được truy xuất có thể chuyển hướng trợ lý gọi một công cụ gửi đi và truyền dữ liệu nhạy cảm đến điểm cuối do kẻ tấn công kiểm soát. Đây là đường dẫn tiêm nhắc gián tiếp cho phép trích xuất dữ liệu trái phép.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-91', 'ccar-p', 91, 'A Claude architect must ensure that, once it is set, a security-hardening flag cannot be disabled by any individual engineer.  
  
Which configuration scope correctly enforces this requirement?', '[{"key":"A","text":"User scope (~/.claude/settings.json) on each engineer’s machine"},{"key":"B","text":"Environment variable defined in the CI/CD pipeline only"},{"key":"C","text":"Managed configuration applied centrally and marked as non-overridable"},{"key":"D","text":"Project scope (.claude/settings.json) committed to the repository"}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code áp dụng các cài đặt được quản lý tập trung trên cấu hình người dùng, dự án, cục bộ và dòng lệnh, ngăn kỹ sư ghi đè chính sách bảo mật đã thực thi. Do đó, chính sách được quản lý là phạm vi thích hợp cho cờ tăng cường không thể ghi đè trên toàn tổ chức.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-92', 'ccar-p', 92, 'You are setting up a HIPAA-eligible deployment for a healthcare customer.  
  
Which configuration enables HIPAA compliance when using Anthropic-provided tools?', '[{"key":"A","text":"Claude Free with no contractual addendum, since consumer products meet HIPAA requirements out of the box."},{"key":"B","text":"Claude Enterprise with a signed Business Associate Agreement, Zero Data Retention enabled, and audit logging configured for compliance tracking."},{"key":"C","text":"Disabling all audit logging so that no PHI is recorded in any log store, on the assumption that the absence of logs satisfies HIPAA requirements without a signed BAA."},{"key":"D","text":"An ad-hoc personal Claude account used by individual clinicians for PHI-related tasks, with no Business Associate Agreement, no Zero Data Retention, and no audit logging configured."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc triển khai Anthropic đủ điều kiện HIPAA phải tuân theo Thỏa thuận liên kết kinh doanh phù hợp cho dịch vụ được phê duyệt. Ghi nhật ký kiểm tra và lưu giữ dữ liệu bằng không hỗ trợ các biện pháp kiểm soát trách nhiệm và xử lý cần thiết, trong khi tài khoản cá nhân và người tiêu dùng không có BAA không cung cấp phạm vi bảo hiểm HIPAA theo hợp đồng. Việc triển khai cũng phải tuân theo các giới hạn tính năng và cấu hình dành riêng cho HIPAA của Anthropic.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-93', 'ccar-p', 93, 'A Claude architect is leading the discovery phase of a new AI-powered customer-service solution.  
  
Which two activities are typical of structured discovery and requirements gathering for a Claude-based deployment? (Select two.)', '[{"key":"A","text":"Facilitating stakeholder workshops to surface latency, accuracy, and compliance constraints before scoping begins."},{"key":"B","text":"Selecting the Claude model tier based on the architect’s prior project experience before stakeholder input is collected."},{"key":"C","text":"Generating an initial prototype and iterating based on user reaction rather than written requirements."},{"key":"D","text":"Documenting explicit success criteria and failure thresholds that will gate production deployment."},{"key":"E","text":"Deferring constraint documentation until the integration design phase to avoid scope creep."}]'::jsonb, ARRAY['A', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khám phá có cấu trúc đưa ra các hạn chế về hoạt động, hiệu suất và tuân thủ từ các bên liên quan trước khi xác định phạm vi để giải pháp có thể được thiết kế theo yêu cầu thực tế. Mức độ sẵn sàng sản xuất cũng phụ thuộc vào các tiêu chí thành công rõ ràng, có thể đo lường được và ngưỡng thất bại có thể đóng vai trò là cổng triển khai. Hướng dẫn của Anthropic khuyến nghị xác định các tiêu chí thành công có thể đo lường được và đánh giá việc triển khai hỗ trợ khách hàng dựa trên các tiêu chuẩn đã thiết lập.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-94', 'ccar-p', 94, 'When presenting an architectural decision to a security and compliance reviewer, which set of content best aligns with that audience’s primary concerns?', '[{"key":"A","text":"Feature delivery schedule, roadmap dependencies, and scope boundaries for the product manager."},{"key":"B","text":"Implementation timeline, component interfaces, and deployment sequence for the engineering team."},{"key":"C","text":"Threat model, control mappings, residual-risk acceptance criteria, and audit traceability."},{"key":"D","text":"Decision rationale, business outcomes, and high-level risk summary for executive review."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đánh giá về tính bảo mật và tuân thủ tập trung vào các mối đe dọa đã xác định, ánh xạ từ yêu cầu đến biện pháp kiểm soát, tiêu chí chấp nhận rủi ro còn sót lại và bằng chứng có thể theo dõi để kiểm tra. Những tạo phẩm này chứng minh rằng kiến ​​trúc giải quyết các nghĩa vụ bảo mật và có thể được đánh giá về mức độ tuân thủ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-95', 'ccar-p', 95, 'You are addressing a stakeholder request that adds significant scope to a deployment already underway.  
  
Which response best aligns expectations while respecting the stakeholder’s underlying need?', '[{"key":"A","text":"Hide the scope-addition request from the broader delivery team to avoid a difficult conversation, allowing the change to proceed without team awareness of its timeline implications."},{"key":"B","text":"Decline the request outright without acknowledging the stakeholder’s underlying need or offering alternatives such as deferral, descoping, or timeline extension."},{"key":"C","text":"Acknowledge the request, describe the scope and timeline implications transparently, and propose options—defer it, descope something else, or extend the timeline—for the stakeholder to choose."},{"key":"D","text":"Accept the additional scope into the current release without describing the timeline or descoping implications, allowing the delivery plan to absorb unacknowledged changes until they surface as delays."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc quản lý phạm vi hiệu quả làm cho hiệu quả phân phối và tiến trình của công việc được thêm vào trở nên rõ ràng, đồng thời duy trì mục tiêu cơ bản của bên liên quan thông qua các lựa chọn thay thế rõ ràng như trì hoãn yêu cầu, loại bỏ phạm vi khác hoặc kéo dài lịch trình.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-96', 'ccar-p', 96, 'You are preparing an operational runbook for a service based on Claude.  
  
Which content is essential to include in the runbook?', '[{"key":"A","text":"Dashboard and log references only, without alert definitions, triage steps, escalation paths, or rollback procedures for the on-call engineer to act on."},{"key":"B","text":"Common alerts and their triage steps, escalation paths, rollback procedures, and references to the relevant dashboards and logs."},{"key":"C","text":"Alert definitions and triage steps only, without escalation paths, rollback procedures, or references to dashboards and logs for on-call use."},{"key":"D","text":"Escalation paths and rollback procedures only, without alert definitions, triage steps, or dashboard references to guide initial incident response."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một sổ tay chạy hiệu quả cung cấp cho các kỹ sư đang làm việc các quy trình có thể thực hiện được đối với các cảnh báo phổ biến, bao gồm hướng dẫn phân loại và điều tra, đường dẫn báo cáo, quy trình khôi phục hoặc khôi phục cũng như các liên kết đến trang tổng quan và nhật ký cần thiết để chẩn đoán dịch vụ. Hướng dẫn vận hành của AWS cũng yêu cầu một quy trình cho mỗi cảnh báo và các đường dẫn leo thang được xác định trong sổ tay và sổ tay giải quyết.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-97', 'ccar-p', 97, 'You are assisting an engineer whose Claude Code session shows a permission denial when the engineer expected the action to be permitted.  
  
Which resolution step is most appropriate?', '[{"key":"A","text":"Tell the engineer to retry the denied action verbatim repeatedly until the denial stops appearing, without inspecting the active permission rules to determine whether the denial is intentional."},{"key":"B","text":"Disable the permission system entirely across all scopes to remove the denial, eliminating all tool-pattern and deny-rule controls rather than identifying and amending the specific rule."},{"key":"C","text":"Inspect the active permission rules across all scopes—managed, command-line, local, project, and user—to identify which rule is denying the action and confirm whether it should be amended or remain denied."},{"key":"D","text":"Grant the engineer unrestricted Bash access to bypass the specific rule causing the denial, removing all tool-pattern constraints rather than amending only the rule in question."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Code hiển thị các quy tắc cấp phép và tệp `settings.json` mà mỗi quy tắc bắt nguồn. Các quy tắc từ chối của nó được đánh giá trước các quy tắc hỏi và cho phép, trong khi các cài đặt có thể được cung cấp ở phạm vi được quản lý, dòng lệnh, dự án cục bộ, dự án dùng chung và người dùng. Việc kiểm tra các quy tắc đang hoạt động và nguồn của chúng sẽ xác định liệu việc từ chối cụ thể là cố ý hay liệu quy tắc có phạm vi hẹp có cần được sửa đổi mà không loại bỏ các biện pháp bảo vệ không liên quan hay không.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-98', 'ccar-p', 98, 'A technical team is deciding whether to implement a new capability that generates regulatory filings from internal data as a Claude Skill or an MCP server. The capability requires a fixed authoring procedure with embedded examples, does not need to invoke live external systems, and must be portable across three Claude deployments: claude.ai, an internal API integration, and Claude Code.  
  
Which factor most strongly supports implementing the capability as a Skill?', '[{"key":"A","text":"The capability needs to query a live database for the most recent regulatory filings."},{"key":"B","text":"The capability must also be callable from a developer’s command-line interface."},{"key":"C","text":"The capability requires direct authentication against the corporate identity provider."},{"key":"D","text":"The capability is procedural knowledge with no live external-system calls required."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Kỹ năng Claude là các gói kiến ​​thức quy trình có thể tái sử dụng, bao gồm quy trình công việc, hướng dẫn, tài nguyên và ví dụ, đồng thời các Kỹ năng tùy chỉnh được hỗ trợ trong claude.ai, API Claude và Claude Code. Máy chủ MCP được thiết kế để hiển thị các hệ thống bên ngoài như nguồn dữ liệu và công cụ. Do đó, một quy trình soạn thảo cố định có các lệnh gọi hệ thống bên ngoài trực tiếp no được thể hiện tốt nhất dưới dạng Kỹ năng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-99', 'ccar-p', 99, 'A customer-support team proposes assigning customer refund decisions to a Claude-driven workflow without human review for refunds below 50 USD. The team argues that small refunds are low risk and that human review would eliminate the efficiency benefit.  
  
Which Delegation-competency principle should guide your response?', '[{"key":"A","text":"Delegation should always include human review on every decision the workflow produces."},{"key":"B","text":"Delegation scope should reflect the type of risk involved, not the transaction size alone."},{"key":"C","text":"Delegation scope should be set primarily by maximizing efficiency gains across the workflow."},{"key":"D","text":"Delegation should be avoided entirely wherever financial transactions occur in the workflow."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc ủy ​​quyền phải được điều chỉnh theo tính chất rủi ro trong công việc được giao. Các quyết định hoàn trả tài chính có thể gây ra rủi ro về gian lận, tuân thủ chính sách, tính công bằng và tác động đến khách hàng mà không chỉ được xác định bởi số tiền hoàn trả; hiệu quả không tự nó biện minh cho sự phê duyệt hoàn toàn tự chủ. Hướng dẫn Ủy quyền của Anthropic coi việc phân bổ nhiệm vụ là sự phân bổ công việc chu đáo dựa trên nhiệm vụ cũng như khả năng và giới hạn của hệ thống AI.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-100', 'ccar-p', 100, 'You are assembling guardrail tactics for a customer-facing assistant.  
  
Which two tactics should be included on the guardrail list?  
  
Each correct answer provides a complete solution.', '[{"key":"A","text":"Embed approved override phrases that let trusted users relax guardrails on demand."},{"key":"B","text":"Lower sampling temperature globally to reduce the chance of off-policy completions."},{"key":"C","text":"Validate the model output against a structured schema before downstream actions are taken."},{"key":"D","text":"Layer prompt-level guardrails with runtime content checks rather than relying on either alone."},{"key":"E","text":"Rely on a single hardened system prompt that enumerates every disallowed behavior."}]'::jsonb, ARRAY['C', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc xác thực đầu ra dựa trên lược đồ có cấu trúc trước khi thực hiện các thao tác tiếp theo sẽ hạn chế dữ liệu mà các thao tác đó có thể nhận được. An toàn AI hiệu quả cũng sử dụng khả năng phòng thủ theo chiều sâu: hướng dẫn ở cấp độ nhắc nhở phải được bổ sung bằng cách kiểm tra nội dung thời gian chạy, vì lời nhắc hoặc điều khiển duy nhất của no tự nó đã cung cấp đủ khả năng bảo vệ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-101', 'ccar-p', 101, 'You are planning a feedback session for a deployment that is in progress.  
  
Which structure most effectively supports productive stakeholder feedback?', '[{"key":"A","text":"Hold an open-ended meeting with no pre-distributed agenda or artifacts, and rely on participants’ memory to carry decisions and follow-up owners forward."},{"key":"B","text":"Define a focused agenda, share the artifacts in advance, capture decisions and follow-ups in writing, and confirm action owners and dates."},{"key":"C","text":"Distribute artifacts at the session start rather than in advance, so stakeholders review materials in real time without preparation before the discussion begins."},{"key":"D","text":"End the session without recording decisions, follow-up items, action owners, or dates, relying on participant memory to carry the session’s outcomes forward."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một chương trình nghị sự tập trung và phân phối trước các hiện vật cho phép các bên liên quan chuẩn bị thông tin đầu vào có ý nghĩa. Việc ghi lại các quyết định và hành động tiếp theo, sau đó xác nhận chủ sở hữu và ngày đến hạn, tạo ra trách nhiệm chung và đảm bảo phản hồi được thực hiện.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-102', 'ccar-p', 102, 'A senior architect is developing briefing materials for a new retrieval architecture. The executive sponsor has asked for a summary of the architectural decision.  
  
Which framing is most suitable for that audience?', '[{"key":"A","text":"Technical alternatives evaluated, implementation implications, and component-level consequences."},{"key":"B","text":"Business outcomes achieved, trade-offs accepted, and high-level risks acknowledged."},{"key":"C","text":"Capabilities delivered, scope implications, and feature-level dependencies on the roadmap."},{"key":"D","text":"Threat model, control mappings, residual-risk acceptance, and audit traceability."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Truyền thông kiến ​​trúc ở cấp điều hành nên tập trung vào kết quả kinh doanh do quyết định mang lại, những đánh đổi đáng kể liên quan và những rủi ro cấp cao cần có nhận thức hoặc tài trợ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-103', 'ccar-p', 103, 'You are setting up Claude Code for a team that requires every engineer to use the same MCP server set, permission rules, and project context throughout the engineering monorepo.  
  
Which configuration scope best meets this requirement?', '[]'::jsonb, ARRAY[]::text[], '[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Phạm vi dự án lưu trữ cấu hình cấp kho lưu trữ có thể được kiểm soát phiên bản và chia sẻ với tất cả cộng tác viên. Phạm vi người dùng và cục bộ là dành riêng cho cá nhân hoặc máy cụ thể, do đó, chúng không thể thực thi một cách đáng tin cậy một bộ máy chủ MCP chung, các quyền và bối cảnh dự án trong một nhóm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-104', 'ccar-p', 104, 'You are conducting a discovery session with a business sponsor who requests “an AI system to fix our customer escalations.”  
  
Which approach is most likely to produce actionable requirements?', '[{"key":"A","text":"Accept the sponsor’s original phrasing as a complete and final requirement and proceed directly to design without asking targeted questions to surface actors, triggers, or constraints."},{"key":"B","text":"Decompose the request by asking targeted questions about who escalates, what triggers escalation, what good resolution looks like, and which constraints—latency, cost, audit, and data sensitivity—apply."},{"key":"C","text":"Defer the discovery session indefinitely on the grounds that the sponsor must fully specify the system before the architect can ask any clarifying or scoping questions."},{"key":"D","text":"Assume the requirement matches the architect’s previous engagement in a different industry and proceed with that context, without validating actors, triggers, or constraints for this sponsor."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các yêu cầu có thể thực hiện được yêu cầu làm rõ những người có liên quan, các sự kiện bắt đầu leo ​​thang, định nghĩa mong muốn về cách giải quyết thành công và các ràng buộc phi chức năng hiện hành như độ trễ, chi phí, khả năng kiểm tra và độ nhạy cảm của dữ liệu. Những chi tiết này biến một yêu cầu giải pháp mơ hồ thành các yêu cầu về phạm vi và thiết kế.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-105', 'ccar-p', 105, 'You are incorporating AI-assisted tools into the team’s documentation workflow. The team wants generated documentation to remain grounded in the actual code.  
  
Which integration approach best meets this requirement?', '[{"key":"A","text":"Generate documentation from the model’s training-data recall without reading any of the actual repository code, accepting that the output will not reflect the current implementation."},{"key":"B","text":"Have the subagents publish generated documentation directly to the public-facing site without passing through the team’s normal review workflow or any human approval step."},{"key":"C","text":"Configure subagents that read the relevant code files via filesystem and code-search tools, generate the documentation, and emit changes through the team’s normal review workflow."},{"key":"D","text":"Disable all filesystem and code-search tools so the subagents cannot read any repository code, accepting that documentation generation will be entirely disconnected from the actual implementation."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tài liệu có căn cứ yêu cầu nhân viên kiểm tra mã kho lưu trữ có liên quan thông qua hệ thống tệp và các công cụ tìm kiếm mã, để nội dung phản ánh cách triển khai hiện tại. Việc định tuyến các thay đổi được tạo ra thông qua quy trình đánh giá thông thường sẽ duy trì sự giám sát của con người và các biện pháp kiểm soát chất lượng đã được thiết lập của nhóm.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-106', 'ccar-p', 106, 'You are assembling team-setup practices for a Claude Code rollout across an engineering organization.  
  
Which two practices should be included on the list? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Use project scope for team-shared Model Context Protocol (MCP) servers and permission rules under version control."},{"key":"B","text":"Apply managed configuration centrally for security-critical settings that must not be overridden by individual engineers."},{"key":"C","text":"Use local scope for security-critical permission rules so each engineer can adapt them to ongoing work."},{"key":"D","text":"Use user scope for team-shared MCP servers so every engineer on the team has consistent access."},{"key":"E","text":"Use project scope for personal editor preferences so the preferences apply consistently within the project."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Các máy chủ MCP trong phạm vi dự án được lưu trữ trong `.mcp.json` và cam kết kiểm soát phiên bản để các thành viên trong nhóm nhận được các công cụ tương tự. Cài đặt dự án được chia sẻ cũng có thể cung cấp các quy tắc cấp phép cho nhóm. Các cài đặt được quản lý là phạm vi thích hợp cho các yêu cầu về bảo mật và tuân thủ vì chúng được ưu tiên hơn các cài đặt cá nhân, dự án và cục bộ và không thể bị từng kỹ sư ghi đè.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-107', 'ccar-p', 107, 'You are determining the highest-impact optimization for a deployment whose token cost is dominated by a long, recurring system prompt and a large retrieved context for each request.  
  
Which optimization most directly addresses the dominant cost driver?', '[{"key":"A","text":"Increase retrieval depth on every request to maximize recall, worsening the dominant cost driver by adding more retrieved tokens per request rather than reducing them."},{"key":"B","text":"Add additional repeated content to the system prompt to give the model more guidance."},{"key":"C","text":"Move the long, repeated system prompt into a cacheable prefix and trim retrieved context to the spans relevant to each query."},{"key":"D","text":"Switch every request to the heaviest available model to maximize output quality, accepting that higher per-request inference cost compounds rather than addresses the dominant cost driver."}]'::jsonb, ARRAY['C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc lưu vào bộ nhớ đệm tiền tố nhắc nhở ổn định, lặp lại cho phép mã thông báo đầu vào được tính phí ở tốc độ đầu vào được lưu vào bộ nhớ đệm thấp hơn khi được hỗ trợ và việc hạn chế truy xuất trong các khoảng thời gian liên quan đến truy vấn sẽ làm giảm số lượng mã thông báo đầu vào được gửi trên mỗi yêu cầu. Cùng với nhau, các biện pháp này trực tiếp làm giảm chi phí nhắc lại và truy xuất ngữ cảnh.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-108', 'ccar-p', 108, 'You are reviewing a peer''s draft system prompt containing conflicting instructions: one section says never to speculate beyond the supplied source, while another instructs the model to confidently fill in any gaps.  
  
Which response is most appropriate?', '[{"key":"A","text":"Add a priority instruction directing the model to evaluate all instructions and apply whichever appears most contextually appropriate on each request."},{"key":"B","text":"Remove or rewrite the gap-filling instruction so the prompt consistently constrains the model to source-supported content."},{"key":"C","text":"Increase temperature so output randomness masks the contradiction."},{"key":"D","text":"Keep both instructions and rely on the model to decide which one to follow on each request."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Lời nhắc của hệ thống phải đưa ra hướng dẫn nhất quán, rõ ràng. Việc xóa hoặc viết lại hướng dẫn để lấp đầy các khoảng trống đảm bảo mô hình không phát minh ra thông tin không được hỗ trợ và vẫn bị hạn chế ở nội dung được nguồn cung cấp hỗ trợ.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-109', 'ccar-p', 109, 'You are assessing an evaluation set used to score a Claude-based hiring-support tool. The set comes from a single geographic region and a single tenure band.  
  
Which response is most appropriate?', '[{"key":"A","text":"Discard all quantitative evaluation and replace it with qualitative impressions collected from a small, convenience-selected group that may not represent the tool’s full user population."},{"key":"B","text":"Expand the evaluation set to cover the geographic regions and tenure bands the tool will serve, and rescore the system on the expanded set before broader release."},{"key":"C","text":"Reduce the evaluation set further to a single demographic subgroup to simplify score interpretation, narrowing coverage rather than expanding it to match the intended user population."},{"key":"D","text":"Continue using the narrow evaluation set drawn from one region and one tenure band because the existing benchmark scores are already high on that subset."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Bộ đánh giá phải thể hiện tập hợp liên quan và các điều kiện mà hệ thống sẽ được triển khai. Chỉ kiểm tra một khu vực và một nhóm nhiệm kỳ không thể tạo ra hiệu suất đáng tin cậy hoặc công bằng cho số lượng tuyển dụng rộng hơn; việc mở rộng tập hợp và tính điểm lại trước khi phát hành rộng rãi hơn sẽ cung cấp bằng chứng về phạm vi phủ sóng dự định.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-110', 'ccar-p', 110, 'You are conducting a controlled experiment to compare two prompts and must finish the design steps before running the experiment.  
  
Which two steps must be completed **BEFORE** running the experiment with random assignment? Each correct answer presents part of the solution. *(Select two.)*', '[{"key":"A","text":"Determine the minimum detectable effect size and the sample size needed for power."},{"key":"B","text":"Decide whether to promote, reject, or iterate the candidate based on the analysis."},{"key":"C","text":"Define the hypothesis and the primary success metric for the comparison."},{"key":"D","text":"Analyze the results against the predefined success metric and significance threshold."},{"key":"E","text":"Document the recommendation, the trade-offs accepted, and the alternatives considered."}]'::jsonb, ARRAY['A', 'C']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một thử nghiệm hợp lệ được thiết kế trước khi phân công bằng cách xác định giả thuyết và chỉ số thành công chính, sau đó lập kế hoạch về sức mạnh thống kê. Hiệu ứng tối thiểu có thể phát hiện được và cỡ mẫu yêu cầu xác định liệu thử nghiệm có thể phát hiện một cách đáng tin cậy sự khác biệt có ý nghĩa hay không. Phân tích kết quả, quyết định phát hành và tài liệu diễn ra sau khi dữ liệu được thu thập.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-111', 'ccar-p', 111, 'You are assessing a Claude-based deployment for compliance with a particular regulation.  
  
Which two steps must be performed **before** mapping the deployment’s data flows to individual regulatory clauses? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Compare the in-place controls against the regulatory requirements to identify any compliance gaps."},{"key":"B","text":"Identify the applicability of the regulation based on data types, jurisdiction, and audience."},{"key":"C","text":"Schedule the remediation work with the engineering team based on the prioritized gap findings."},{"key":"D","text":"Document the identified gaps along with recommended remediations and residual risk for sign-off."},{"key":"E","text":"Inventory the vendor-provided compliance tooling and confirm which compliance affordances are in place."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khả năng áp dụng quy định phải được thiết lập từ các loại dữ liệu, khu vực pháp lý và đối tượng trước khi có thể xác định phạm vi phân tích ở cấp điều khoản. Công cụ tuân thủ sẵn có của nhà cung cấp và khả năng chi trả tuân thủ được kích hoạt cũng phải được xác định để các biện pháp kiểm soát thực tế và khả năng xử lý dữ liệu có thể được ánh xạ tới các điều khoản áp dụng. Phân tích lỗ hổng, lập kế hoạch khắc phục và phê duyệt tuân theo bản đồ đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-112', 'ccar-p', 112, 'You are an architect supporting the iteration phase of a deployed Claude-based system.  
  
Which activity most directly aligns with this phase?', '[{"key":"A","text":"Rebuild the entire system architecture from scratch at the start of every iteration cycle regardless of what production telemetry, evaluations, and stakeholder feedback indicate is needed."},{"key":"B","text":"Stop measuring production outcomes once the deployment has successfully launched, treating the go-live milestone as the end of the evaluation and iteration cycle."},{"key":"C","text":"Discard the evaluation framework and reference set once the deployment is in production, accepting that future iterations will have no structured basis for measuring the impact of changes."},{"key":"D","text":"Review production telemetry, sampled output evaluations, and stakeholder feedback to identify the highest-impact change for the next cycle, then plan the change against the evaluation framework."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Hệ thống LLM được triển khai phải duy trì khung đánh giá và sử dụng phương pháp đo từ xa về hoạt động, chất lượng đầu ra được lấy mẫu cũng như phản hồi của người dùng hoặc bên liên quan để ưu tiên cải tiến có giá trị nhất. Sau đó, thay đổi theo kế hoạch có thể được đo lường dựa trên các tiêu chí thành công đã xác định và bộ đánh giá đã được thiết lập, cho phép lặp lại dựa trên bằng chứng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-113', 'ccar-p', 113, 'You are conducting a discovery engagement for a new Claude-based capability and must complete the requirements-gathering activities before validating the captured requirements with stakeholders.  
  
Which two steps must be completed **BEFORE** validating the captured requirements with stakeholders? Each correct answer presents part of the solution. *(Select two.)*', '[{"key":"A","text":"Produce architecture decision records that capture the rationale for major design choices."},{"key":"B","text":"Capture the business goals, success criteria, and the in-scope user population for the engagement."},{"key":"C","text":"Document the consolidated requirements with traceability to the source stakeholder for each item."},{"key":"D","text":"Schedule the rollout milestones and dependencies with engineering and product partners."},{"key":"E","text":"Identify the non-functional constraints covering latency, cost, audit, data sensitivity, and regulatory needs."}]'::jsonb, ARRAY['B', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mục tiêu kinh doanh, tiêu chí thành công có thể đo lường, phạm vi và đối tượng người dùng dự kiến ​​sẽ xác định kết quả mà khả năng này phải đáp ứng. Các ràng buộc phi chức năng như độ trễ, chi phí, khả năng kiểm toán, độ nhạy cảm của dữ liệu và các nghĩa vụ pháp lý ràng buộc giải pháp nào được chấp nhận. Những đầu vào này phải được gợi ra trước khi các bên liên quan có thể xác nhận các yêu cầu một cách có ý nghĩa.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-114', 'ccar-p', 114, 'You are setting up tool permissions for a Claude-based assistant. Its defined duties require read access to a knowledge base and write access to a draft queue, with no other access.  
  
Which scoping design best enforces least privilege?', '[{"key":"A","text":"Allow access to all tools with read permissions globally and restrict write permissions to the draft-queue tool, without scoping to only the specific tools required for defined tasks."},{"key":"B","text":"Per-role allow-list of exactly the read-knowledge-base and write-draft-queue tools, enforced at the orchestration layer."},{"key":"C","text":"Allow access to every tool in the catalog and rely on the model to decline tools it should not use."},{"key":"D","text":"Disable all tools entirely to achieve a minimal permission surface, accepting that the assistant can no longer perform the read-knowledge-base or write-draft-queue tasks it was designed for."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Đặc quyền tối thiểu yêu cầu chỉ cấp những khả năng cụ thể cần thiết để thực hiện các nhiệm vụ đã xác định. Danh sách cho phép theo từng vai trò chỉ cho phép công cụ đọc cơ sở kiến ​​thức và công cụ ghi hàng đợi nháp, được thực thi bởi lớp điều phối, ngăn chặn quyền truy cập vào các công cụ không liên quan trong khi vẫn giữ được chức năng cần thiết.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-115', 'ccar-p', 115, 'The compliance team has developed a regulatory-disclosure procedure that must be used identically across customer-service, sales, and onboarding workflows. Regulators update the procedure four to six times per year. You are designing how to package the procedure for Claude’s use across all three workflows.  
  
Which two design decisions should you make? Each correct answer represents part of the solution. (Select two.)', '[{"key":"A","text":"Package the procedure as a Claude Skill owned directly by the compliance team."},{"key":"B","text":"Embed the procedure text into each workflow’s system prompt at integration time."},{"key":"C","text":"Store the procedure in a shared retrieval corpus accessed by all three workflows."},{"key":"D","text":"Have each workflow team rewrite the procedure for its own context."},{"key":"E","text":"Reference the same Claude Skill from all three workflow integrations."}]'::jsonb, ARRAY['A', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Claude Skill thuộc sở hữu tuân thủ tập trung quy trình đã được phê duyệt dưới dạng quy trình làm việc được quản lý và có thể tái sử dụng. Việc tham chiếu cùng một Kỹ năng đó từ cả ba hoạt động tích hợp giúp giữ cho việc triển khai dịch vụ khách hàng, bán hàng và triển khai được nhất quán và cho phép các bản cập nhật tuân thủ được phổ biến từ một nguồn được duy trì. Anthropic ghi lại các Kỹ năng như một cách để phân phối quy trình làm việc được tiêu chuẩn hóa, đã được phê duyệt một cách nhất quán, bao gồm cả việc quản lý và cập nhật trên toàn tổ chức.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-116', 'ccar-p', 116, 'A senior architect is overseeing stakeholder expectations for a Claude-based reporting assistant midway through development. Stakeholders have growing concerns about response latency.  
  
Which two actions most directly align stakeholder expectations in this situation? (Select two.)', '[{"key":"A","text":"Present measured p50 and p95 latency baselines against the agreed SLA thresholds so stakeholders have accurate data."},{"key":"B","text":"Pause all development and reallocate engineering resources entirely to latency optimization."},{"key":"C","text":"Communicate that latency concerns are a known LLM limitation and outside the architecture team’s control."},{"key":"D","text":"Replace the current Claude model with a third-party model that may offer lower latency without evaluation."},{"key":"E","text":"Revise the SLA definition collaboratively with stakeholders if current targets are not achievable given production constraints."}]'::jsonb, ARRAY['A', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Độ trễ p50 và p95 được đo so với ngưỡng SLA đã thỏa thuận mang lại cái nhìn khách quan, chung về hiệu suất thực tế. Nếu những hạn chế về sản xuất khiến các mục tiêu hiện tại không thể đạt được, thì việc cộng tác sửa đổi SLA sẽ điều chỉnh lại cam kết dịch vụ với những kỳ vọng về hiệu suất khả thi. Độ trễ là một chỉ báo cấp độ dịch vụ tiêu chuẩn có thể được đánh giá bằng cách sử dụng phần trăm và các mục tiêu dịch vụ được công bố đặt ra kỳ vọng của người dùng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-117', 'ccar-p', 117, 'You are deciding when to introduce a project subagent instead of relying on Claude Code’s general capabilities.  
  
Which scenario most directly warrants a dedicated subagent?', '[{"key":"A","text":"The team has a recurring specialized task, such as database schema review, that requires a focused system prompt, narrow tool permissions, and a specific model selection across many sessions."},{"key":"B","text":"The team has a one-time ad hoc question that will not recur and does not require a focused system prompt, narrow tool permissions, or dedicated model selection."},{"key":"C","text":"The team has no recurring specialized tasks and uses Claude Code only for isolated general-purpose work that does not justify a dedicated system prompt or tool scope."},{"key":"D","text":"The team wants every Claude Code interaction to use the same generic system prompt with no task-specific specialization, narrow tool permissions, or dedicated model selection."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Một tác nhân phụ chuyên dụng phù hợp cho công việc chuyên môn định kỳ cần lời nhắc hệ thống có phạm vi chặt chẽ, quyền hạn chế đối với công cụ và tùy chọn một mô hình riêng biệt. Các tác nhân phụ Claude Code tùy chỉnh có thể tái sử dụng và có thể được định cấu hình bằng lời nhắc hệ thống, quyền truy cập công cụ và mô hình của riêng chúng.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-118', 'ccar-p', 118, 'You are creating a human-in-the-loop validation workflow for a new Claude-based deployment and must finish the design steps before running a pilot of the workflow.  
  
Which two steps must be completed **BEFORE** piloting the workflow using a representative subset of traffic? Each correct answer represents part of the solution. *(Select two.)*', '[{"key":"A","text":"Define the sampling strategy and the escalation criteria at each oversight point in the pipeline."},{"key":"B","text":"Iterate the workflow design based on observed pilot findings before broader rollout to production."},{"key":"C","text":"Onboard the reviewer pool with role-specific training on the check criteria and escalation procedures."},{"key":"D","text":"Document the workflow with check criteria, escalation paths, and service-level agreements (SLAs) for each step."},{"key":"E","text":"Identify the decision points in the pipeline that require human oversight by impact and reversibility."}]'::jsonb, ARRAY['A', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Thiết kế xác thực con người trong vòng lặp phải xác định các quyết định trong quy trình đảm bảo sự giám sát của con người tùy theo tác động và khả năng đảo ngược của chúng, đồng thời xác định tiêu chí lấy mẫu và báo cáo cho từng điểm giám sát. Những biện pháp kiểm soát đó thiết lập phạm vi và hành vi được thử nghiệm trong chương trình thí điểm; những sửa đổi dựa trên những phát hiện thí điểm sẽ diễn ra sau đó.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-119', 'ccar-p', 119, 'Engineering leadership plans to deploy Claude Skills to 280 developers across 14 teams. The Skills will capture internal coding standards, code-review checklists, and incident-postmortem templates. Leadership has asked how Skill authorship should be governed so that Skills stay trustworthy without creating a bottleneck around one central team.  
  
Which governance model should you recommend?', '[{"key":"A","text":"Per-developer authorship across the 280 engineers with no team-level coordination required."},{"key":"B","text":"Centralized authorship by a single platform team responsible for every Skill produced."},{"key":"C","text":"Fully decentralized authorship across the 14 teams with no review before publication."},{"key":"D","text":"Federated authorship across the 14 teams with a central review and publication gate."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Quyền tác giả liên kết cho phép mỗi nhóm tạo và duy trì Kỹ năng cho miền riêng của mình, phân bổ khối lượng công việc tác giả. Cổng đánh giá và xuất bản trung tâm đảm bảo rằng các Kỹ năng được chia sẻ đáp ứng các yêu cầu về chất lượng, bảo mật, tính nhất quán và độ tin cậy trên toàn tổ chức trước khi chúng được phổ biến rộng rãi.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-120', 'ccar-p', 120, 'You are assembling continuity practices that extend across the deployment lifecycle.  
  
Which two practices should be included on the list? Each correct answer provides a complete solution. (Select two.)', '[{"key":"A","text":"Maintain a stakeholder register and notify the listed parties at every phase transition event."},{"key":"B","text":"Carry the evaluation framework and reference set forward across iterations rather than rebuilding each time."},{"key":"C","text":"Archive every phase deliverable in long-term storage to preserve a record of what was produced."},{"key":"D","text":"Capture lessons learned at the end of each phase and surface them as inputs to the next phase."},{"key":"E","text":"Lock decisions made in early phases to prevent revisiting them as later phases begin."}]'::jsonb, ARRAY['B', 'D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Vòng đời triển khai liên tục sử dụng khung đánh giá liên tục và bộ tham chiếu để có thể phát hiện các kết quả có thể so sánh được qua các lần lặp lại và hồi quy. Nó cũng kết hợp các bài học kinh nghiệm từ từng giai đoạn sang giai đoạn tiếp theo, cho phép cải tiến một cách có hệ thống. Hướng dẫn của Microsoft mô tả quá trình đánh giá được vận hành liên tục và đề xuất các kết quả thử nghiệm để nắm bắt các bài học triển khai.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-121', 'ccar-p', 121, 'A Claude architect is reviewing configuration-scope assignments.  
  
Which two statements correctly describe an appropriate use of user-scope configuration versus other scopes? (Select two.)', '[{"key":"A","text":"Persisting personal editor theme preferences that follow an engineer across projects."},{"key":"B","text":"Saving a preferred Claude response language that applies to all repositories the engineer uses."},{"key":"C","text":"Enforcing a company-wide policy that disables a feature for all engineers."},{"key":"D","text":"Defining MCP server endpoints shared by all contributors to a specific repository."},{"key":"E","text":"Storing API authentication keys so they are not committed to version control."}]'::jsonb, ARRAY['A', 'B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Cài đặt phạm vi người dùng áp dụng cho một người trong mọi dự án trên máy của người đó và dành cho các sở thích cá nhân, chẳng hạn như chủ đề. Do đó, ngôn ngữ phản hồi ưa thích cá nhân được sử dụng trên tất cả các kho lưu trữ thuộc phạm vi người dùng. Các hạn chế trên toàn tổ chức yêu cầu cài đặt được quản lý, điểm cuối MCP của kho lưu trữ dùng chung yêu cầu cấu hình dự án dùng chung và thông tin xác thực phải được giữ ở cấu hình cục bộ riêng tư, không được cam kết.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-122', 'ccar-p', 122, 'You are choosing the documentation set that should accompany a Claude-based deployment at handoff.  
  
Which set is the most complete?', '[{"key":"A","text":"Architecture overview, ADRs, component-level diagrams, runbooks for common operations, an on-call playbook, and a list of known limitations."},{"key":"B","text":"Code comments scattered across individual source files with no integrating architecture overview, no ADRs, no runbooks, and no on-call playbook to orient operators or new team members."},{"key":"C","text":"A single one-page architecture diagram with no ADRs, no runbooks, no on-call playbook, and no list of known limitations to support operators or future maintainers."},{"key":"D","text":"A verbal handover walkthrough conducted on the day of transition, with no written architecture overview, ADRs, runbooks, playbook, or known limitations captured for future reference."}]'::jsonb, ARRAY['A']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Gói bàn giao triển khai hoàn chỉnh ghi lại kiến ​​trúc tổng thể và thiết kế thành phần, ghi lại các quyết định về kiến ​​trúc, cung cấp sổ tay cho các hoạt động thông thường và sổ tay hỗ trợ theo yêu cầu, đồng thời xác định các hạn chế đã biết đối với người vận hành và người bảo trì trong tương lai.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-123', 'ccar-p', 123, 'A security audit identifies two issues:  
  
1. All end users use one shared API key.  
2. Tool calls run without logging the user who initiated them.  
  
Which two mitigations directly remediate these specific findings? (Select two.)', '[{"key":"A","text":"Validate structured outputs against a schema before downstream actions are executed."},{"key":"B","text":"Enforce RBAC at the retrieval layer before content enters the model context."},{"key":"C","text":"Move credentials out of the prompt context and resolve them from a server-side secret store."},{"key":"D","text":"Add actor attribution to tool-call logs so each call records the initiating user identity."},{"key":"E","text":"Replace the shared API key with per-user OAuth tokens carrying scope-restricted permissions."}]'::jsonb, ARRAY['D', 'E']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Mã thông báo OAuth cho mỗi người dùng thay thế thông tin xác thực được chia sẻ bằng quyền truy cập có phạm vi giới hạn, có thể phân bổ riêng lẻ. Việc đưa danh tính của người dùng bắt đầu vào nhật ký cuộc gọi công cụ sẽ thiết lập trách nhiệm giải trình và dấu vết kiểm tra cho từng hành động.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-124', 'ccar-p', 124, 'You are categorizing token-management tactics by the request-lifecycle stage at which each applies.  
  
For each tactic, select its applicable request-lifecycle stage.', '[]'::jsonb, ARRAY[]::text[], '[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R17ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R17ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Việc chuẩn bị đầu vào làm giảm hoặc thu gọn cuộc hội thoại và truy xuất ngữ cảnh trước khi tập hợp. Việc xây dựng lời nhắc xác định thứ tự và tiền tố có thể lưu trong bộ nhớ đệm ổn định của lời nhắc. Xử lý đầu ra xác thực dữ liệu có cấu trúc được tạo và duy trì các kết quả đã xác thực để sử dụng và kiểm tra tiếp theo.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-125', 'ccar-p', 125, 'You are addressing an adversarial input pattern where users insert text that claims administrative authority and directs the model to circumvent safety restrictions.  
  
Which combination of controls most effectively mitigates this attack pattern?', '[{"key":"A","text":"Trusting that the model will intrinsically recognize and reject all bypass attempts without prompt-level instructions, runtime classifiers, scoped permissions, or audit logging."},{"key":"B","text":"Prompt-level instructions that treat user content as untrusted data, runtime classifiers that detect override attempts, scoped tool permissions that cannot be elevated by user content, and audit logging of attempts."},{"key":"C","text":"Removing all safety restrictions and guardrails to eliminate the attack surface that bypass attempts target, accepting that this makes the assistant unrestricted for all inputs."},{"key":"D","text":"Granting users any privilege level they assert in their message content, on the assumption that cooperative behavior requires honoring self-declared authority without independent verification."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Văn bản do người dùng cung cấp phải được coi là không đáng tin cậy và không thể cấp đặc quyền hoặc ghi đè các quy tắc an toàn có mức độ ưu tiên cao hơn. Các biện pháp giảm thiểu theo lớp—hướng dẫn nhắc nhở, phát hiện các lần ghi đè trong thời gian chạy, các quyền của công cụ có đặc quyền tối thiểu mà nội dung người dùng không thể nâng cao và ghi nhật ký kiểm tra—giảm cả khả năng và tác động của các lần thử chèn nhắc nhở.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-126', 'ccar-p', 126, 'When the support agent invokes escalate_to_human, human agents report they must re-read the entire raw conversation to understand each case, and average handle time for escalated tickets has risen. What should the agent do at the moment of escalation to fix this?', '[{"key":"A","text":"Attach the full untrimmed transcript of the conversation so the human has complete information."},{"key":"B","text":"Enable extended thinking on the escalation turn so the model reasons longer before handing off."},{"key":"C","text":"Escalate earlier in ambiguous cases so humans receive tickets before much conversation has accumulated."},{"key":"D","text":"Produce a structured handoff summary — the customer''s issue, verified identifiers, tool results and account state gathered, actions already attempted, and the specific recommended next step."}]'::jsonb, ARRAY['D']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Tại sao D đúng. Việc chuyển giao hiệu quả của con người đòi hỏi một bản tóm tắt có cấu trúc hiển thị trước chính xác những gì con người cần: vấn đề, số nhận dạng đã được xác nhận, nội dung đã được thử và đề xuất. Đó là điều giúp loại bỏ gánh nặng đọc lại và rút ngắn thời gian xử lý. Việc hủy bản ghi đầy đủ (A) là phương thức lỗi hiện tại - nó buộc con người phải tự xây dựng lại vụ việc. Tư duy mở rộng (B) cải thiện khả năng suy luận của chính mô hình nhưng tạo ra tạo tác no cho con người. Báo cáo những thay đổi trước đó (C) khi yêu cầu đến, chứ không phải vấn đề thiếu thông tin và có thể sẽ làm giảm khả năng giải quyết trong lần liên hệ đầu tiên.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published'),
  ('ccarp-127', 'ccar-p', 127, 'You are evaluating two configurations for an internal compliance Q&A assistant. Configuration X decreases top-k retrieval and uses a lighter model, reducing p95 latency by 38 percent but resulting in a measured 2 percent decrease in the accuracy benchmark. Configuration Y keeps the current top-k retrieval setting and heavier model, with no change to p95 latency and no measurable accuracy change. The deployment’s declared priorities are accuracy first and latency second.  
  
Which configuration is the better recommendation?', '[{"key":"A","text":"Configuration X, because the 2 percent accuracy reduction falls within normal benchmark variance and is not a meaningful regression."},{"key":"B","text":"Configuration Y, because the deployment’s stated priority is accuracy first, and Configuration X produces a measured reduction in accuracy."},{"key":"C","text":"Configuration X, because lower latency generally matters more than accuracy, regardless of the deployment’s stated priorities."},{"key":"D","text":"Configuration X, because a 38 percent latency improvement outweighs a 2 percent accuracy reduction as a general rule across compliance deployments."}]'::jsonb, ARRAY['B']::text[], '[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb- yellow) { màu nền: color-mix(in srgb, var(--accent) 55%, #000); màu sắc: #ffffff; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-green) { màu nền: color-mix(in srgb, var(--accent) 65%, #fff); màu: #172033; }
[data-question-highlight-id="question-marker-R16ajmlfiv5tpfiv5uadb"]::highlight(question-marker-R16ajmlfiv5tpfiv5uadb-pink) { màu nền: color-mix(in srgb, var(--accent) 35%, #fff); màu: #172033; }Khi độ chính xác là ưu tiên triển khai chính thì cấu hình duy trì độ chính xác đo được sẽ phù hợp hơn. Cấu hình Y duy trì độ chính xác, trong khi Cấu hình X giới thiệu hồi quy độ chính xác đo được; việc cải thiện độ trễ của nó chỉ là thứ yếu so với mức độ ưu tiên đã nêu.', 'General', ARRAY['CCAR-P', 'General']::text[], NULL, 'published')
